        } else if before == Class::Sp {
            allow = true; // LB18
        } else if after == Class::Qu || before == Class::Qu {
            allow = false; // LB19
        } else if matches!(after, Class::Ba | Class::Hy | Class::Ns) || before == Class::Bb {
            allow = false; // LB21
        } else if before == Class::Hy && after == Class::Nu {
            allow = false; // LB25 (HY × NU)
        } else if after == Class::In {
            allow = false; // LB22
        } else if (matches!(before, Class::Al) && after == Class::Nu)
            || (before == Class::Nu && after == Class::Al)
        {
            allow = false; // LB23
        } else if (matches!(before, Class::Pr | Class::Po) && matches!(after, Class::Al))
            || (matches!(before, Class::Al) && matches!(after, Class::Pr | Class::Po))
        {
            allow = false; // LB24
        } else if (matches!(before, Class::Pr | Class::Po) && matches!(after, Class::Nu | Class::Op))
            || (matches!(before, Class::Nu) && matches!(after, Class::Nu | Class::Po | Class::Pr))
            || (matches!(before, Class::Is | Class::Sy) && after == Class::Nu)
            || (before == Class::Op && after == Class::Nu)
            || (before == Class::Hy && after == Class::Nu)
        {
            allow = false; // LB25
        } else if before == Class::Al && after == Class::Al {
            allow = false; // LB28
        } else if before == Class::Is && after == Class::Al {
            allow = false; // LB29
        } else if (matches!(before, Class::Al | Class::Nu) && after == Class::Op)
            || (before == Class::Cp && matches!(after, Class::Al | Class::Nu))
        {
            allow = false; // LB30
        } else {
            allow = true; // LB31
        }
        if before == Class::Pr && after == Class::Id {
            allow = false;
        }
        if allow {
            out.push(chars[i].0);
        }
        i += 1;
    }
    out
}

fn find_words(line: &str) -> Vec<Word> {
    let mut words = Vec::new();
    let mut start = 0;
    for idx in break_opportunities(line) {
        if idx > start {
            words.push(Word::from(&line[start..idx]));
            start = idx;
        }
    }
    if start < line.len() || line.is_empty() {
        words.push(Word::from(&line[start..]));
    }
    words
}

fn hyphen_split_points(word: &str) -> Vec<usize> {
    // textwrap HyphenSplitter: split after '-' when preceded and followed by alphanumeric chars.
    let mut points = Vec::new();
    let chars: Vec<(usize, char)> = word.char_indices().collect();
    for (i, (idx, c)) in chars.iter().enumerate() {
        if *c == '-' && i > 0 && i + 1 < chars.len() {
            let prev = chars[i - 1].1;
            let next = chars[i + 1].1;
            if prev.is_alphanumeric() && next.is_alphanumeric() {
                points.push(idx + 1);
            }
        }
    }
    points
}

fn split_words(words: Vec<Word>) -> Vec<Word> {
    let mut out = Vec::new();
    for word in words {
        let points = hyphen_split_points(&word.text);
        let mut prev = 0;
        for idx in points {
            let piece = &word.text[prev..idx];
            let need_hyphen = !piece.ends_with('-');
            out.push(Word {
                text: piece.to_string(),
                whitespace: String::new(),
                penalty: if need_hyphen { "-".to_string() } else { String::new() },
                width: display_width(piece),
            });
            prev = idx;
        }
        if prev < word.text.len() || prev == 0 {
            let piece = &word.text[prev..];
            out.push(Word {
                text: piece.to_string(),
                whitespace: word.whitespace.clone(),
                penalty: word.penalty.clone(),
                width: display_width(piece),
            });
        }
    }
    out
}

fn break_apart(word: &Word, line_width: usize) -> Vec<Word> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut width = 0;
    for (idx, ch) in word.text.char_indices() {
        let cw = char_width(ch);
        if width > 0 && width + cw > line_width {
            out.push(Word {
                text: word.text[start..idx].to_string(),
                whitespace: String::new(),
                penalty: String::new(),
                width,
            });
            start = idx;
            width = 0;
        }
        width += cw;
    }
    out.push(Word {
        text: word.text[start..].to_string(),
        whitespace: word.whitespace.clone(),
        penalty: word.penalty.clone(),
        width,
    });
    out
}

fn break_words(words: Vec<Word>, line_width: usize) -> Vec<Word> {
    let mut out = Vec::new();
    for w in words {
        if w.width > line_width {
            out.extend(break_apart(&w, line_width));
        } else {
            out.push(w);
        }
    }
    out
}

const NLINE_PENALTY: f64 = 1000.0;
const OVERFLOW_PENALTY: f64 = 50_000.0;
const SHORT_LAST_LINE_FRACTION: f64 = 4.0;
const SHORT_LAST_LINE_PENALTY: f64 = 25.0;
const HYPHEN_PENALTY: f64 = 25.0;

/// Optimal-fit wrapping. Returns indices of line starts (fragment indices) as ranges.
fn wrap_optimal_fit(fragments: &[Word], line_widths: &[usize]) -> Vec<(usize, usize)> {
    let n = fragments.len();
    let mut widths = Vec::with_capacity(n + 1);
    let mut w = 0.0f64;
    widths.push(w);
    for f in fragments {
        w += f.width as f64 + f.whitespace_width() as f64;
        widths.push(w);
    }
    // dp[j] = (min cost for fragments[..j], predecessor i, line count)
    let mut cost = vec![f64::INFINITY; n + 1];
    let mut pred = vec![0usize; n + 1];
    let mut lines = vec![0usize; n + 1];
    cost[0] = 0.0;
    for j in 1..=n {
        for i in 0..j {
            if cost[i] == f64::INFINITY {
                continue;
            }
            let line_number = lines[i];
            let ln = line_number.min(line_widths.len() - 1);
            let target_width = (line_widths[ln] as f64).max(1.0);
            let last = &fragments[j - 1];
            let line_width =
                widths[j] - widths[i] - last.whitespace_width() as f64 + last.penalty_width() as f64;
            let mut c = cost[i];
            if line_width > target_width {
                let overflow = line_width - target_width;
                c += overflow * OVERFLOW_PENALTY;
            } else if j < n {
                let gap = target_width - line_width;
                c += gap * gap;
            } else if i + 1 == j && line_width < target_width / SHORT_LAST_LINE_FRACTION {
                c += SHORT_LAST_LINE_PENALTY;
            }
            if last.penalty_width() > 0 {
                c += HYPHEN_PENALTY;
            }
            c += NLINE_PENALTY;
            if c < cost[j] {
                cost[j] = c;
                pred[j] = i;
                lines[j] = lines[i] + 1;
            }
        }
    }
    let mut ranges = Vec::new();
    let mut j = n;
    while j > 0 {
        let i = pred[j];
        ranges.push((i, j));
        j = i;
    }
    ranges.reverse();
    ranges
}

fn wrap_single_line(line: &str, width: usize, initial_indent: &str, subsequent_indent: &str, lines: &mut Vec<String>) {
    let indent = if lines.is_empty() { initial_indent } else { subsequent_indent };
    if line.len() < width && indent.is_empty() {
        lines.push(line.trim_end_matches(' ').to_string());
        return;
    }
    let initial_width = width.saturating_sub(display_width(initial_indent));
    let subsequent_width = width.saturating_sub(display_width(subsequent_indent));
    let line_widths = [initial_width, subsequent_width];
    let words = find_words(line);
    let split = split_words(words);
    let mut broken = break_words(split, line_widths[1]);
    if !initial_indent.is_empty() {
        broken.insert(0, Word::from(""));
    }
    let ranges = wrap_optimal_fit(&broken, &line_widths);
    let mut idx = 0;
    for (a, b) in ranges {
        let words = &broken[a..b];
        let last_word = match words.last() {
            None => {
                lines.push(String::new());
                continue;
            }
            Some(w) => w,
        };
        let len: usize = words.iter().map(|w| w.len() + w.whitespace.len()).sum::<usize>() - last_word.whitespace.len();
        let mut result = if lines.is_empty() && !initial_indent.is_empty() {
            initial_indent.to_string()
        } else if !lines.is_empty() && !subsequent_indent.is_empty() {
            subsequent_indent.to_string()
        } else {
            String::new()
        };
        result.push_str(&line[idx..idx + len]);
        if !last_word.penalty.is_empty() {
            result.push_str(&last_word.penalty);
        }
        lines.push(result);
        idx += len + last_word.whitespace.len();
    }
}

/// Equivalent of `textwrap::fill(text, Options::new(width).initial_indent(..).subsequent_indent(..))`.
pub fn fill(text: &str, width: usize, initial_indent: &str, subsequent_indent: &str) -> String {
    let mut lines = Vec::new();
    for line in text.split('\n') {
        let line = line.strip_suffix('\r').unwrap_or(line);
        wrap_single_line(line, width, initial_indent, subsequent_indent, &mut lines);
    }
    lines.join("\n")
}
