        // Footer
        if let Some(help) = &self.help {
            let initial = paint("  help: ", Style::Cyan);
            out.push_str(&fill_styled(help, width - 4, &initial, "        "));
            out.push('\n');
        }
        out
    }
}

/// textwrap::fill but with styled (ANSI-containing) indents: widths are
/// computed on the unstyled indents.
fn fill_styled(text: &str, width: usize, initial: &str, subsequent: &str) -> String {
    let plain_initial = strip_ansi(initial);
    let plain_subsequent = strip_ansi(subsequent);
    let wrapped = fill(text, width, &plain_initial, &plain_subsequent);
    if plain_initial == initial && plain_subsequent == subsequent {
        return wrapped;
    }
    let mut lines = Vec::new();
    for (i, line) in wrapped.split('\n').enumerate() {
        if i == 0 {
            lines.push(format!("{}{}", initial, &line[plain_initial.len()..]));
        } else {
            lines.push(format!("{}{}", subsequent, &line[plain_subsequent.len()..]));
        }
    }
    lines.join("\n")
}

fn strip_ansi(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            // skip until 'm'
            for d in chars.by_ref() {
                if d == 'm' {
                    break;
                }
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn render_snippet(snip: &Snippet, chars: &Chars, theme: &Theme) -> Option<String> {
    let src = &snip.source;
    if snip.offset >= src.len() && !(src.is_empty() && snip.offset == 0) {
        return None;
    }
    if src.is_empty() {
        return None;
    }
    // Split into lines with their byte offsets.
    let mut lines: Vec<(usize, usize, &str)> = Vec::new(); // (start, end_excl_newline, text)
    let mut start = 0;
    let bytes = src.as_bytes();
    let mut i = 0;
    while i <= bytes.len() {
        if i == bytes.len() || bytes[i] == b'\n' {
            let text = &src[start..i];
            let text = text.strip_suffix('\r').unwrap_or(text);
            lines.push((start, i, text));
            start = i + 1;
        }
        i += 1;
    }
    // Drop a phantom last line if source ends with newline
    if src.ends_with('\n') {
        lines.pop();
    }
    // Find label line
    let mut label_line = lines.len().saturating_sub(1);
    for (idx, (s, e, _)) in lines.iter().enumerate() {
        if snip.offset >= *s && snip.offset <= *e {
            label_line = idx;
            break;
        }
    }
    let first = label_line.saturating_sub(1);
    let last = (label_line + 1).min(lines.len().saturating_sub(1));
    let linum_width = (last + 1).to_string().len();
    let mut out = String::new();
    let paint = |s: &str, st: Style| theme.paint(s, st);
    // header
    out.push_str(&format!(
        "{:width$} {}{}{}{}:{}:{}{}\n",
        "",
        paint(&format!("{}{}", chars.ltop, chars.hbar), Style::Plain),
        chars.lbox,
        snip.filename,
        "",
        first + 1,
        1,
        chars.rbox,
        width = linum_width + 1
    ));
    for idx in first..=last {
        let (ls, _le, text) = lines[idx];
        let shown = text.replace('\t', "    ");
        out.push_str(&format!(
            " {:>width$} {} {}\n",
            idx + 1,
            paint(chars.vbar, Style::Plain),
            shown,
            width = linum_width
        ));
        if idx == label_line {
            let col = snip.offset.saturating_sub(ls);
            let col_text = &text[..col.min(text.len())];
            let vis = display_width(&col_text.replace('\t', "    "));
            let len = snip.length.max(1);
            let underline: String = std::iter::repeat(chars.underline).take(len).collect();
            out.push_str(&format!(
                "{:width$} {} {}{}\n",
                "",
                paint(chars.vbar_break, Style::Plain),
                " ".repeat(vis),
                paint(&underline, theme.severity_style()),
                width = linum_width + 1
            ));
        }
    }
    out.push_str(&format!(
        "{:width$} {}{}{}{}{}\n",
        "",
        paint(chars.lbot, Style::Plain),
        chars.hbar,
        chars.hbar,
        chars.hbar,
        chars.hbar,
        width = linum_width + 1
    ));
    Some(out)
}

#[derive(Clone, Copy)]
pub enum Style {
    Plain,
    Red,
    Yellow,
    Cyan,
}

pub struct Chars {
    pub hbar: &'static str,
    pub vbar: &'static str,
    pub vbar_break: &'static str,
    pub rarrow: &'static str,
    pub ltop: &'static str,
    pub lbot: &'static str,
    pub lcross: &'static str,
    pub lbox: &'static str,
    pub rbox: &'static str,
    pub underline: &'static str,
    pub error: &'static str,
    pub warning: &'static str,
}

#[derive(Clone, Copy)]
pub struct Theme {
    pub unicode: bool,
    pub color: bool,
    sev_red: bool,
}

impl Theme {
    pub fn detect() -> Theme {
        let is_tty = std::io::stderr().is_terminal();
        let unicode = if is_tty { locale_supports_unicode() } else { true };
        let color = is_tty && term_supports_color();
        Theme { unicode, color, sev_red: true }
    }
    pub fn plain_unicode() -> Theme {
        Theme { unicode: true, color: false, sev_red: true }
    }
    fn chars(&self) -> Chars {
        if self.unicode {
            Chars {
                hbar: "─",
                vbar: "│",
                vbar_break: "·",
                rarrow: "▶",
                ltop: "╭",
                lbot: "╰",
                lcross: "├",
                lbox: "[",
                rbox: "]",
                underline: "─",
                error: "×",
                warning: "⚠",
            }
        } else {
            Chars {
                hbar: "-",
                vbar: "|",
                vbar_break: ":",
                rarrow: ">",
                ltop: ",",
                lbot: "`",
                lcross: "|",
                lbox: "[",
                rbox: "]",
                underline: "^",
                error: "x",
                warning: "!",
            }
        }
    }
    fn severity_style(&self) -> Style {
        if self.sev_red {
            Style::Red
        } else {
            Style::Yellow
        }
    }
    fn paint(&self, s: &str, st: Style) -> String {
        if !self.color {
            return s.to_string();
        }
        match st {
            Style::Plain => s.to_string(),
            Style::Red => format!("\x1b[31m{}\x1b[0m", s),
            Style::Yellow => format!("\x1b[33m{}\x1b[0m", s),
            Style::Cyan => format!("\x1b[36m{}\x1b[0m", s),
        }
    }
}

pub fn locale_supports_unicode() -> bool {
    if let Ok(term) = std::env::var("TERM") {
        if term == "linux" {
            return false;
        }
    }
    let check = |v: &str| {
        let l = v.to_ascii_lowercase();
        l.contains("utf8") || l.contains("utf-8")
    };
    if let Ok(v) = std::env::var("LC_ALL") {
        if !v.is_empty() {
            return check(&v);
        }
    }
    if let Ok(v) = std::env::var("LC_CTYPE") {
        if !v.is_empty() {
            return check(&v);
        }
    }
    if let Ok(v) = std::env::var("LANG") {
        if !v.is_empty() {
            return check(&v);
        }
    }
    false
}

pub fn term_supports_color() -> bool {
    if std::env::var("NO_COLOR").map(|v| !v.is_empty()).unwrap_or(false) {
        return false;
    }
    match std::env::var("TERM") {
        Ok(t) => t != "dumb",
        Err(_) => false,
    }
}
