pub fn init() {
    let enabled = stdout_colors_enabled();
    COLOR.store(enabled, Ordering::Relaxed);
}

fn stdout_colors_enabled() -> bool {
    if let Ok(v) = std::env::var("CLICOLOR_FORCE") {
        if v != "0" {
            return true;
        }
    }
    if let Ok(v) = std::env::var("CLICOLOR") {
        if v == "0" {
            return false;
        }
    }
    if !std::io::stdout().is_terminal() {
        return false;
    }
    match std::env::var("TERM") {
        Ok(t) => t != "dumb",
        Err(_) => false,
    }
}

pub fn set_prefix(p: Option<String>) {
    *PREFIX.lock().unwrap() = p;
}

fn emit(icon: &str, label: &str, color: &str, msg: &str) {
    let prefix = PREFIX.lock().unwrap().clone().unwrap_or_default();
    if COLOR.load(Ordering::Relaxed) {
        println!(
            "{}{}{}\x1b[1m{}\x1b[0m >o_o< {}: {}\x1b[1m{}\x1b[0m",
            prefix, color, "", icon, label, color, msg
