pub fn parse_layer_str(contents: &str, display_name: &str) -> Result<OrandaLayer> {
    match serde_json::from_str::<OrandaLayer>(contents) {
        Ok(l) => Ok(l),
        Err(e) => {
            let line = e.line();
            let col = e.column();
            let offset = source_offset(contents, line, col);
            Err(OrandaError::Json {
                message: e.to_string(),
                filename: display_name.to_string(),
                source: contents.to_string(),
                offset,
                has_label: col > 0 || !contents.is_empty(),
