    /// whether a cargo-dist config was detected
    pub cargo_dist: bool,
}

pub const DEFAULT_PROJECT_NAME: &str = "My Oranda Project";

pub fn resolve(layer: OrandaLayer, detected: DetectedProject, root: &Path) -> Config {
    let p = layer.project.unwrap_or_default();
    let project = ProjectConfig {
        name: p
            .name
            .or(detected.name)
            .unwrap_or_else(|| DEFAULT_PROJECT_NAME.to_string()),
        version: p.version.or(detected.version),
        description: p.description.or(detected.description),
        homepage: p.homepage.or(detected.homepage),
        repository: p.repository.or(detected.repository),
        readme_path: p
            .readme_path
            .or(detected.readme_path)
            .unwrap_or_else(|| "README.md".to_string()),
        license: p.license.or(detected.license),
    };
    let b = layer.build.unwrap_or_default();
    let build = BuildConfig {
        dist_dir: b.dist_dir.unwrap_or_else(|| "public".to_string()),
        static_dir: b.static_dir.unwrap_or_else(|| "static".to_string()),
        path_prefix: b.path_prefix,
        additional_pages: b.additional_pages.unwrap_or_default(),
    };
    let m = layer.marketing.unwrap_or_default();
    let social = m
        .social
        .map(|s| SocialConfig {
            image: s.image,
            image_alt: s.image_alt,
            twitter_account: s.twitter_account,
        })
        .unwrap_or_default();
    let s = layer.styles.unwrap_or_default();
    let styles = StyleConfig {
        theme: s.theme.unwrap_or(Theme::Dark),
        syntax_theme: s.syntax_theme.unwrap_or(SyntaxTheme::MaterialTheme),
        additional_css: s.additional_css.unwrap_or_default(),
        oranda_css_version: s.oranda_css_version,
        logo: s.logo,
        favicon: s.favicon,
    };
    let c = layer.components.unwrap_or_default();
    // changelog: default enabled (page generated when a repository exists)
    let changelog = match c.changelog {
        Some(BoolOr::Bool(false)) => None,
        Some(BoolOr::Bool(true)) | None => Some(ChangelogConfig {
            read_changelog_file: true,
            rss_feed: true,
        }),
        Some(BoolOr::Val(v)) => Some(ChangelogConfig {
            read_changelog_file: v.read_changelog_file.unwrap_or(true),
            rss_feed: v.rss_feed.unwrap_or(true),
        }),
    };
    let mut mdbook_explicit = false;
    let mdbook = match c.mdbook {
        Some(BoolOr::Bool(false)) => None,
        Some(BoolOr::Bool(true)) => {
            mdbook_explicit = true;
            Some(MdBookConfig {
                path: None,
                theme: true,
            })
        }
        None => Some(MdBookConfig {
            path: None,
            theme: true,
        }),
        Some(BoolOr::Val(v)) => {
            mdbook_explicit = true;
            Some(MdBookConfig {
                path: v.path,
                theme: v.theme.unwrap_or(true),
            })
        }
    };
    let funding = match c.funding {
        Some(BoolOr::Bool(false)) => None,
        Some(BoolOr::Bool(true)) | None => Some(FundingConfig {
            preferred_funding: None,
            md_path: None,
            yml_path: None,
        }),
        Some(BoolOr::Val(v)) => Some(FundingConfig {
            preferred_funding: v.preferred_funding,
            md_path: v.md_path,
            yml_path: v.yml_path,
        }),
    };
    let artifacts = match c.artifacts {
        Some(BoolOr::Bool(false)) => None,
        Some(BoolOr::Bool(true)) => Some(ArtifactsConfig {
            cargo_dist: detected.cargo_dist,
            package_managers: None,
            auto: false,
            hidden: vec![],
            match_package_names: true,
        }),
        None => {
            if detected.cargo_dist {
                Some(ArtifactsConfig {
                    cargo_dist: true,
                    package_managers: None,
                    auto: false,
                    hidden: vec![],
                    match_package_names: true,
                })
            } else {
                None
            }
        }
        Some(BoolOr::Val(v)) => Some(ArtifactsConfig {
            cargo_dist: v.cargo_dist.unwrap_or(detected.cargo_dist),
            package_managers: v.package_managers.map(|pm| PackageManagersConfig {
                preferred: pm.preferred.unwrap_or_default(),
                additional: pm.additional.unwrap_or_default(),
            }),
            auto: v.auto.unwrap_or(false),
            hidden: v.hidden.unwrap_or_default(),
            match_package_names: v.match_package_names.unwrap_or(true),
        }),
    };
    let components = ComponentConfig {
        changelog,
        mdbook,
        funding,
        artifacts,
        source: c.source.unwrap_or(ReleasesSource::Github),
    };
    Config {
        project,
        build,
        analytics: m.analytics,
        social,
        styles,
        components,
        workspace: layer.workspace,
        mdbook_explicit,
        project_root: root.to_path_buf(),
    }
}
