//! Error types, rendered the way the original tool (via miette) renders them.

use crate::report::{Report, Snippet};

#[derive(Debug)]
pub enum OrandaError {
    Json {
        message: String,
        filename: String,
        source: String,
        offset: usize,
        has_label: bool,
    },
    FileRead {
        path: String,
        source: std::io::Error,
    },
    AssetRead {
        path: String,
        source: std::io::Error,
    },
    PathNotFound {
        path: String,
    },
    RemoteFetch {
        url: String,
        causes: Vec<String>,
    },
    CssFetch {
        causes: Vec<String>,
    },
    GithubReleases {
        causes: Vec<String>,
    },
    RepoParse {
        url: String,
    },
    FundingYml,
    Panic {
        location: String,
        message: String,
    },
    Other {
        message: String,
        causes: Vec<String>,
        help: Option<String>,
    },
}

pub type Result<T> = std::result::Result<T, OrandaError>;

impl OrandaError {
    pub fn other(msg: impl Into<String>) -> OrandaError {
        OrandaError::Other {
            message: msg.into(),
            causes: vec![],
            help: None,
        }
    }

    pub fn report(&self) -> Report {
        match self {
            OrandaError::Json {
                message,
                filename,
                source,
                offset,
                has_label,
            } => {
                let mut r = Report::error("failed to parse JSON").cause(message.clone());
                if *has_label {
                    r = r.snippet(Snippet {
                        filename: filename.clone(),
                        source: source.clone(),
                        offset: *offset,
                        length: 1,
                    });
                }
                r
            }
            OrandaError::FileRead { path, source } => {
                Report::error(format!("failed to read file at {}", path)).cause(source.to_string())
            }
            OrandaError::AssetRead { path, source } => {
                Report::error(format!("failed to read asset from {}", path))
                    .cause(source.to_string())
                    .help("Make sure your path is relative to your oranda config or project manifest file.")
            }
            OrandaError::PathNotFound { path } => Report::error(format!(
                "Specified path `{}` was not found on your filesystem!",
                path
            ))
            .help("Make sure you specify your path relative to the oranda.json/manifest file/README file of your project!"),
            OrandaError::RemoteFetch { url, causes } => Report::error(format!(
                "failed to fetch asset at {}: Encountered an error when requesting a remote asset.",
                url
            ))
            .causes(causes.clone())
            .help("Make sure the url you provided is accurate."),
            OrandaError::CssFetch { causes } => {
                let mut c = causes.clone();
                let first = if c.is_empty() { String::new() } else { c.remove(0) };
                Report::error(first).causes(c)
            }
            OrandaError::GithubReleases { causes } => {
                Report::error("Failed fetching releases from Github.").causes(causes.clone())
            }
            OrandaError::RepoParse { url } => {
                Report::error(format!("Your repository URL {} couldn't be parsed.", url))
                    .help("Only GitHub URLs are supported at the moment.")
            }
            OrandaError::FundingYml => Report::error("Error while parsing FUNDING.yml")
                .help("Make sure your FUNDING.yml conforms to GitHub's format!"),
            OrandaError::Panic { location, message } => Report::error("oranda panicked.")
                .cause(format!("at {}", location))
                .cause(message.clone())
                .help("set the `RUST_BACKTRACE=1` environment variable to display a backtrace."),
            OrandaError::Other {
                message,
                causes,
                help,
            } => {
                let mut r = Report::error(message.clone()).causes(causes.clone());
                if let Some(h) = help {
                    r = r.help(h.clone());
                }
                r
            }
        }
    }
}
EOF
echo ok"}

