//! Project auto-detection (Cargo.toml via `cargo metadata`, package.json).

use crate::config::DetectedProject;
use crate::message;
use crate::report::{Report, Snippet, Theme};
use std::path::Path;
use std::process::Command;

pub fn detect(root: &Path) -> DetectedProject {
    let cargo_toml = root.join("Cargo.toml");
    let package_json = root.join("package.json");
    let has_cargo = cargo_toml.is_file();
    let has_js = package_json.is_file();

    let rust = if has_cargo { detect_rust(root, &cargo_toml) } else { None };
    let js = if has_js { detect_js(&package_json) } else { None };

    match (rust, js) {
        (Some(r), Some(_)) => {
            message::warning(&format!(
                "Also found a Javascript project at {}, but we're ignoring it",
                abs(&package_json)
            ));
            r
        }
        (Some(r), None) => r,
        (None, Some(j)) => j,
        (None, None) => DetectedProject::default(),
    }
}

fn abs(p: &Path) -> String {
    std::fs::canonicalize(p)
        .map(|p| p.display().to_string())
        .unwrap_or_else(|_| p.display().to_string())
}

fn detect_rust(root: &Path, cargo_toml: &Path) -> Option<DetectedProject> {
    let output = Command::new("cargo")
        .arg("metadata")
        .arg("--format-version")
        .arg("1")
        .arg("--no-deps")
        .current_dir(root)
        .output();
    let output = match output {
        Ok(o) => o,
        Err(e) => {
            Report::warning(format!(
                "We found a potential rust project at {} but there was an issue",
                abs(cargo_toml)
            ))
            .cause("  × `cargo metadata` execution failed\n")
            .cause(format!("failed to run `cargo metadata`: {}", e))
            .eprint();
            return None;
        }
    };
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
        Report::warning(format!(
            "We found a potential rust project at {} but there was an issue",
            abs(cargo_toml)
        ))
        .cause("  × `cargo metadata` execution failed\n")
        .cause(format!("`cargo metadata` exited with an error: {}", stderr))
        .eprint();
        return None;
    }
    let json: serde_json::Value = match serde_json::from_slice(&output.stdout) {
        Ok(v) => v,
        Err(_) => return None,
    };
    let manifest_abs = abs(cargo_toml);
    let packages = json.get("packages").and_then(|p| p.as_array())?;
    let pkg = packages.iter().find(|p| {
        p.get("manifest_path")
            .and_then(|m| m.as_str())
            .map(|m| m == manifest_abs)
            .unwrap_or(false)
    });
    let mut detected = DetectedProject::default();
    // cargo-dist detection: [workspace.metadata.dist]
    if let Some(meta) = json.get("metadata") {
        if meta.get("dist").map(|d| !d.is_null()).unwrap_or(false) {
            detected.cargo_dist = true;
        }
    }
    let pkg = match pkg {
        Some(p) => p,
        None => {
            if detected.cargo_dist {
                return Some(detected);
            }
            return None;
        }
    };
    let s = |k: &str| pkg.get(k).and_then(|v| v.as_str()).map(|v| v.to_string());
    detected.name = s("name");
    detected.version = s("version");
    detected.description = s("description");
    detected.homepage = s("homepage");
    detected.repository = s("repository");
    detected.license = s("license");
    if let Some(readme) = s("readme") {
        let manifest_dir = Path::new(&manifest_abs).parent().unwrap_or(root);
        detected.readme_path = Some(manifest_dir.join(readme).display().to_string());
    }
    Some(detected)
}

fn detect_js(package_json: &Path) -> Option<DetectedProject> {
    let path_str = abs(package_json);
    let contents = match std::fs::read_to_string(package_json) {
        Ok(c) => c,
        Err(_) => return None,
    };
    let value: serde_json::Value = match serde_json::from_str(&contents) {
        Ok(v) => v,
        Err(e) => {
            // Nested diagnostic: "failed to parse JSON" with snippet, then the serde cause.
            let offset = crate::config::source_offset(&contents, e.line(), e.column());
            let mut inner = Report::error("failed to parse JSON");
            if e.column() > 0 && !contents.is_empty() {
                inner = inner.snippet(Snippet {
                    filename: path_str.clone(),
                    source: contents.clone(),
                    offset,
                    length: 1,
                });
            }
            let inner_rendered = inner.render(Theme::plain_unicode());
            Report::warning(format!(
                "We found a potential javascript project at {} but there was an issue",
                path_str
            ))
            .cause(inner_rendered)
            .cause(e.to_string())
            .eprint();
            return None;
        }
    };
    let name = value.get("name").and_then(|v| v.as_str());
    let name = match name {
        Some(n) => n.to_string(),
        None => {
            let inner = Report::error(format!("your package doesn't have a name: {}", path_str))
                .help("is it a workspace? We don't support that yet.");
            let inner_rendered = inner.render(Theme::plain_unicode());
            Report::warning(format!(
                "We found a potential javascript project at {} but there was an issue",
                path_str
            ))
            .cause(inner_rendered)
            .eprint();
            return None;
        }
    };
    let s = |k: &str| value.get(k).and_then(|v| v.as_str()).map(|v| v.to_string());
    let repository = match value.get("repository") {
        Some(serde_json::Value::String(s)) => Some(s.clone()),
        Some(serde_json::Value::Object(o)) => o.get("url").and_then(|u| u.as_str()).map(|u| u.to_string()),
        _ => None,
    };
    Some(DetectedProject {
        name: Some(name),
        version: s("version"),
        description: s("description"),
        homepage: s("homepage"),
        repository,
        license: s("license"),
        readme_path: None,
        cargo_dist: false,
    })
}
EOF
echo ok"}

