use std::net::ToSocketAddrs;
use std::time::Duration;

/// Compute the error chain (outermost first) for a failed request to `url`.
pub fn request_error_chain(url: &str) -> Vec<String> {
    let host = host_of(url);
    let port = if url.starts_with("http://") { 80 } else { 443 };
    let inner = match format!("{}:{}", host, port).to_socket_addrs() {
