//! A tiny Jinja-like template engine with minijinja's default whitespace
//! behaviour (no trimming). Supports `{{ expr }}`, `{% if %}/{% elif %}/{% else %}/{% endif %}`,
//! `{% for x in expr %}/{% endfor %}` and a few simple expressions.

use serde_json::Value;

#[derive(Debug, Clone)]
enum Node {
    Text(String),
    Var(Expr, bool), // expr, escape
    If(Vec<(Option<Expr>, Vec<Node>)>),
    For(String, Expr, Vec<Node>),
}

#[derive(Debug, Clone)]
enum Expr {
    Path(Vec<String>),
    Str(String),
    Int(i64),
    Not(Box<Expr>),
    And(Box<Expr>, Box<Expr>),
    Or(Box<Expr>, Box<Expr>),
    Eq(Box<Expr>, Box<Expr>),
    Ne(Box<Expr>, Box<Expr>),
    Filter(Box<Expr>, String),
    Defined(Box<Expr>),
}

pub struct Template {
    nodes: Vec<Node>,
    autoescape: bool,
}

pub fn render(template: &str, ctx: &Value) -> String {
    Template::parse(template, false).render(ctx)
}

pub fn render_escaped(template: &str, ctx: &Value) -> String {
    Template::parse(template, true).render(ctx)
}

impl Template {
    pub fn parse(src: &str, autoescape: bool) -> Template {
        let tokens = tokenize(src);
        let mut pos = 0;
        let nodes = parse_nodes(&tokens, &mut pos, &[]);
        Template { nodes, autoescape }
    }

    pub fn render(&self, ctx: &Value) -> String {
        let mut out = String::new();
        let mut scopes: Vec<Value> = vec![ctx.clone()];
        render_nodes(&self.nodes, &mut scopes, &mut out, self.autoescape);
        out
    }
}

#[derive(Debug, Clone)]
enum Token {
    Text(String),
    Var(String),
    Block(String),
}

fn tokenize(src: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut rest = src;
    loop {
        let next_var = rest.find("{{");
        let next_block = rest.find("{%");
        let next = match (next_var, next_block) {
            (None, None) => None,
            (Some(a), None) => Some((a, true)),
            (None, Some(b)) => Some((b, false)),
            (Some(a), Some(b)) => {
                if a < b {
                    Some((a, true))
                } else {
                    Some((b, false))
                }
            }
        };
        match next {
            None => {
                if !rest.is_empty() {
                    tokens.push(Token::Text(rest.to_string()));
                }
                break;
            }
            Some((idx, is_var)) => {
                if idx > 0 {
                    tokens.push(Token::Text(rest[..idx].to_string()));
                }
                let after = &rest[idx + 2..];
                let close = if is_var { "}}" } else { "%}" };
                let end = after.find(close).expect("unclosed tag");
                let inner = after[..end].trim().to_string();
                if is_var {
                    tokens.push(Token::Var(inner));
                } else {
                    tokens.push(Token::Block(inner));
                }
                rest = &after[end + 2..];
            }
        }
    }
    tokens
}

fn parse_nodes(tokens: &[Token], pos: &mut usize, stop: &[&str]) -> Vec<Node> {
    let mut nodes = Vec::new();
    while *pos < tokens.len() {
        match &tokens[*pos] {
            Token::Text(t) => {
                nodes.push(Node::Text(t.clone()));
                *pos += 1;
            }
            Token::Var(v) => {
                let (expr, escape) = parse_var(v);
                nodes.push(Node::Var(expr, escape));
                *pos += 1;
            }
            Token::Block(b) => {
                let kw = b.split_whitespace().next().unwrap_or("");
                if stop.contains(&kw) {
                    return nodes;
                }
                match kw {
                    "if" => {
                        *pos += 1;
                        let cond = parse_expr(b[2..].trim());
                        let mut branches = Vec::new();
                        let body = parse_nodes(tokens, pos, &["elif", "else", "endif"]);
                        branches.push((Some(cond), body));
                        loop {
                            match &tokens[*pos] {
                                Token::Block(b2) => {
                                    let kw2 = b2.split_whitespace().next().unwrap_or("");
                                    if kw2 == "elif" {
                                        *pos += 1;
                                        let c = parse_expr(b2[4..].trim());
                                        let body = parse_nodes(tokens, pos, &["elif", "else", "endif"]);
                                        branches.push((Some(c), body));
                                    } else if kw2 == "else" {
                                        *pos += 1;
                                        let body = parse_nodes(tokens, pos, &["endif"]);
                                        branches.push((None, body));
                                    } else {
                                        // endif
                                        *pos += 1;
                                        break;
                                    }
                                }
                                _ => panic!("bad template"),
                            }
                        }
                        nodes.push(Node::If(branches));
                    }
                    "for" => {
                        *pos += 1;
                        let rest = b[3..].trim();
                        let in_idx = rest.find(" in ").expect("for without in");
                        let var = rest[..in_idx].trim().to_string();
                        let expr = parse_expr(rest[in_idx + 4..].trim());
                        let body = parse_nodes(tokens, pos, &["endfor"]);
                        *pos += 1; // endfor
                        nodes.push(Node::For(var, expr, body));
                    }
                    _ => panic!("unknown block tag {}", b),
                }
            }
        }
    }
    nodes
}

fn parse_var(v: &str) -> (Expr, bool) {
    let expr = parse_expr(v);
    // `| safe` disables escaping
    let mut escape = true;
    if let Expr::Filter(_, name) = &expr {
        if name == "safe" {
            escape = false;
        }
    }
    (expr, escape)
}

fn parse_expr(s: &str) -> Expr {
    let s = s.trim();
    // lowest precedence: or
    if let Some(idx) = find_top_level(s, " or ") {
        return Expr::Or(Box::new(parse_expr(&s[..idx])), Box::new(parse_expr(&s[idx + 4..])));
    }
    if let Some(idx) = find_top_level(s, " and ") {
        return Expr::And(Box::new(parse_expr(&s[..idx])), Box::new(parse_expr(&s[idx + 5..])));
    }
    if let Some(rest) = s.strip_prefix("not ") {
        return Expr::Not(Box::new(parse_expr(rest)));
    }
    if let Some(idx) = find_top_level(s, " == ") {
        return Expr::Eq(Box::new(parse_expr(&s[..idx])), Box::new(parse_expr(&s[idx + 4..])));
    }
    if let Some(idx) = find_top_level(s, " != ") {
        return Expr::Ne(Box::new(parse_expr(&s[..idx])), Box::new(parse_expr(&s[idx + 4..])));
    }
    if let Some(rest) = s.strip_suffix(" is defined") {
        return Expr::Defined(Box::new(parse_expr(rest)));
    }
    if let Some(idx) = find_top_level(s, "|") {
        let name = s[idx + 1..].trim().to_string();
        return Expr::Filter(Box::new(parse_expr(&s[..idx])), name);
    }
    if (s.starts_with('"') && s.ends_with('"') && s.len() >= 2)
        || (s.starts_with('\'') && s.ends_with('\'') && s.len() >= 2)
    {
        return Expr::Str(s[1..s.len() - 1].to_string());
    }
    if let Ok(i) = s.parse::<i64>() {
        return Expr::Int(i);
    }
    if s.starts_with('(') && s.ends_with(')') {
        return parse_expr(&s[1..s.len() - 1]);
    }
    Expr::Path(s.split('.').map(|p| p.to_string()).collect())
}

fn find_top_level(s: &str, pat: &str) -> Option<usize> {
    let mut depth = 0i32;
    let mut in_str: Option<char> = None;
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < s.len() {
        let c = bytes[i] as char;
        if let Some(q) = in_str {
            if c == q {
                in_str = None;
            }
        } else if c == '"' || c == '\'' {
            in_str = Some(c);
        } else if c == '(' {
            depth += 1;
        } else if c == ')' {
            depth -= 1;
        } else if depth == 0 && s[i..].starts_with(pat) {
            return Some(i);
        }
        i += 1;
    }
    None
}

fn lookup<'a>(scopes: &'a [Value], path: &[String]) -> Value {
    for scope in scopes.iter().rev() {
        if let Some(v) = scope.get(&path[0]) {
            let mut cur = v.clone();
            for p in &path[1..] {
                cur = match cur.get(p) {
                    Some(x) => x.clone(),
                    None => Value::Null,
                };
            }
            return cur;
        }
    }
    Value::Null
}

fn truthy(v: &Value) -> bool {
    match v {
        Value::Null => false,
        Value::Bool(b) => *b,
        Value::Number(n) => n.as_f64().map(|f| f != 0.0).unwrap_or(true),
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(o) => !o.is_empty(),
    }
}

fn eval(expr: &Expr, scopes: &[Value]) -> Value {
    match expr {
        Expr::Path(p) => lookup(scopes, p),
        Expr::Str(s) => Value::String(s.clone()),
        Expr::Int(i) => Value::from(*i),
        Expr::Not(e) => Value::Bool(!truthy(&eval(e, scopes))),
        Expr::And(a, b) => {
            let av = eval(a, scopes);
            if !truthy(&av) {
                av
            } else {
                eval(b, scopes)
            }
        }
        Expr::Or(a, b) => {
            let av = eval(a, scopes);
            if truthy(&av) {
                av
            } else {
                eval(b, scopes)
            }
        }
        Expr::Eq(a, b) => Value::Bool(eval(a, scopes) == eval(b, scopes)),
        Expr::Ne(a, b) => Value::Bool(eval(a, scopes) != eval(b, scopes)),
        Expr::Defined(e) => Value::Bool(!eval(e, scopes).is_null()),
        Expr::Filter(e, name) => {
            let v = eval(e, scopes);
            match name.as_str() {
                "safe" => v,
                "length" => Value::from(match &v {
                    Value::Array(a) => a.len(),
                    Value::String(s) => s.chars().count(),
                    Value::Object(o) => o.len(),
                    _ => 0,
                }),
                "lower" => Value::String(stringify(&v).to_lowercase()),
                "upper" => Value::String(stringify(&v).to_uppercase()),
                _ => v,
            }
        }
    }
}

fn stringify(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        other => other.to_string(),
    }
}

pub fn html_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#x27;"),
            '/' => out.push_str("&#x2f;"),
            _ => out.push(c),
        }
    }
    out
}

fn render_nodes(nodes: &[Node], scopes: &mut Vec<Value>, out: &mut String, autoescape: bool) {
    for node in nodes {
        match node {
            Node::Text(t) => out.push_str(t),
            Node::Var(e, escape) => {
                let v = eval(e, scopes);
                let s = stringify(&v);
                if autoescape && *escape {
                    out.push_str(&html_escape(&s));
                } else {
                    out.push_str(&s);
                }
            }
            Node::If(branches) => {
                for (cond, body) in branches {
                    let ok = match cond {
                        Some(c) => truthy(&eval(c, scopes)),
                        None => true,
                    };
                    if ok {
                        render_nodes(body, scopes, out, autoescape);
                        break;
                    }
                }
            }
            Node::For(var, e, body) => {
                let v = eval(e, scopes);
                let items: Vec<Value> = match v {
                    Value::Array(a) => a,
                    Value::Object(o) => o.into_iter().map(|(k, v)| {
                        let mut m = serde_json::Map::new();
                        m.insert("key".to_string(), Value::String(k));
                        m.insert("value".to_string(), v);
                        Value::Object(m)
                    }).collect(),
                    _ => vec![],
                };
                let n = items.len();
                for (i, item) in items.into_iter().enumerate() {
                    let mut scope = serde_json::Map::new();
                    scope.insert(var.clone(), item);
                    let mut lp = serde_json::Map::new();
                    lp.insert("index".to_string(), Value::from(i + 1));
                    lp.insert("index0".to_string(), Value::from(i));
                    lp.insert("first".to_string(), Value::Bool(i == 0));
                    lp.insert("last".to_string(), Value::Bool(i + 1 == n));
                    scope.insert("loop".to_string(), Value::Object(lp));
                    scopes.push(Value::Object(scope));
                    render_nodes(body, scopes, out, autoescape);
                    scopes.pop();
                }
            }
        }
    }
}
