//! Site building.

use crate::config::{self, AnalyticsConfig, Config, DetectedProject, FundingType};
use crate::errors::{OrandaError, Result};
use crate::message;
use crate::report::Report;
use crate::templates;
use crate::tmpl;
use serde_json::{json, Value};
use std::path::{Path, PathBuf};

pub const FAVICON: &[u8] = include_bytes!("../assets/favicon.ico");
pub const ARTIFACTS_JS: &str = include_str!("../assets/artifacts.js");
pub const ORANDA_CSS_VERSION: &str = "v0.6.1";

pub struct BuildOpts {
    pub json_only: bool,
}

/// Parsed GitHub repository.
#[derive(Debug, Clone)]
pub struct GithubRepo {
    pub owner: String,
    pub name: String,
}

pub fn parse_github_repo(url: &str) -> Option<GithubRepo> {
    let mut rest = url.trim();
    if let Some(r) = rest.strip_prefix("git+") {
        rest = r;
    }
    let path = if let Some(r) = rest.strip_prefix("git@github.com:") {
        r
    } else {
        let r = rest
            .strip_prefix("https://github.com/")
            .or_else(|| rest.strip_prefix("http://github.com/"))
            .or_else(|| rest.strip_prefix("https://www.github.com/"))
            .or_else(|| rest.strip_prefix("ssh://git@github.com/"))?;
        r
    };
    let path = path.trim_end_matches('/');
    let path = path.strip_suffix(".git").unwrap_or(path);
    let mut parts = path.split('/');
    let owner = parts.next()?;
    let name = parts.next()?;
    if owner.is_empty() || name.is_empty() || parts.next().is_some() {
        return None;
    }
    Some(GithubRepo {
        owner: owner.to_string(),
        name: name.to_string(),
    })
}

pub struct Site {
    pub config: Config,
    pub root: PathBuf,
    pub dist: PathBuf,
    pub prefix: String,
    pub css_override: Option<String>,
}

pub fn load_config(root: &Path) -> Result<Config> {
    let cfg_path = root.join("oranda.json");
    let layer = if cfg_path.is_file() {
        config::parse_layer(&cfg_path)?
    } else {
        config::OrandaLayer::default()
    };
    let detected: DetectedProject = crate::project::detect(root);
    Ok(config::resolve(layer, detected, root))
}

pub fn load_config_display(root: &Path, display: &str) -> Result<Config> {
    let cfg_path = root.join("oranda.json");
    let layer = if cfg_path.is_file() {
        let contents = std::fs::read_to_string(&cfg_path).map_err(|e| OrandaError::FileRead {
            path: display.to_string(),
            source: e,
        })?;
        config::parse_layer_str(&contents, display)?
    } else {
        config::OrandaLayer::default()
    };
    let detected: DetectedProject = crate::project::detect(root);
    Ok(config::resolve(layer, detected, root))
}

fn path_prefix(cfg: &Config) -> String {
    match &cfg.build.path_prefix {
        Some(p) if !p.is_empty() => format!("/{}", p.trim_matches('/')),
        _ => String::new(),
    }
}

/// Run the full build for a single project rooted at `root`.
pub fn build(root: &Path, cfg: Config, opts: &BuildOpts) -> Result<()> {
    let dist = root.join(&cfg.build.dist_dir);
    let prefix = path_prefix(&cfg);
    let css_override = std::env::var("ORANDA_CSS").ok().filter(|s| !s.is_empty());
    let site = Site {
        config: cfg,
        root: root.to_path_buf(),
        dist,
        prefix,
        css_override,
    };
    site.build(opts)
}

impl Site {
    fn cfg(&self) -> &Config {
        &self.config
    }

    fn components_list(&self) -> Vec<&'static str> {
        let mut v = Vec::new();
        if self.artifacts_enabled() {
            v.push("artifacts");
        }
        if self.cfg().components.changelog.is_some() {
            v.push("changelog");
        }
        if self.funding_enabled() {
            v.push("funding");
        }
        if self.mdbook_enabled() {
            v.push("mdbook");
        }
        v
    }

    fn artifacts_enabled(&self) -> bool {
        match &self.cfg().components.artifacts {
            None => false,
            Some(a) => a.cargo_dist || a.package_managers.is_some(),
        }
    }

    fn funding_yml_path(&self) -> Option<PathBuf> {
        let f = self.cfg().components.funding.as_ref()?;
        let p = f
            .yml_path
            .clone()
            .unwrap_or_else(|| ".github/FUNDING.yml".to_string());
        Some(self.root.join(p))
    }

    fn funding_md_path(&self) -> Option<PathBuf> {
        let f = self.cfg().components.funding.as_ref()?;
        let p = f.md_path.clone().unwrap_or_else(|| "funding.md".to_string());
        Some(self.root.join(p))
    }

    fn funding_enabled(&self) -> bool {
        if self.cfg().components.funding.is_none() {
            return false;
        }
        let yml = self.funding_yml_path().map(|p| p.is_file()).unwrap_or(false);
        let md = self.funding_md_path().map(|p| p.is_file()).unwrap_or(false);
        yml || md
    }

    fn mdbook_dir(&self) -> Option<PathBuf> {
        let m = self.cfg().components.mdbook.as_ref()?;
        if let Some(p) = &m.path {
            let d = self.root.join(p);
            if d.join("book.toml").is_file() {
                return Some(d);
            }
            return None;
        }
        for cand in ["book", "docs"] {
            let d = self.root.join(cand);
            if d.join("book.toml").is_file() {
                return Some(d);
            }
        }
        None
    }

    fn mdbook_enabled(&self) -> bool {
        self.mdbook_dir().is_some()
    }

    fn has_repo(&self) -> bool {
        self.cfg().project.repository.is_some()
    }

    fn changelog_page(&self) -> bool {
        self.cfg().components.changelog.is_some() && self.has_repo()
    }

    fn funding_page(&self) -> bool {
        self.funding_enabled() && self.has_repo()
    }

    fn additional_pages(&self) -> Vec<(String, String, PathBuf)> {
        // (title, href, source path) – only .md files are used
        let mut out = Vec::new();
        for (title, path) in &self.cfg().build.additional_pages {
            if !path.ends_with(".md") {
                continue;
            }
            let stem = path.strip_suffix(".md").unwrap_or(path);
            let href = format!("{}/{}/", self.prefix, stem);
            out.push((title.clone(), href, self.root.join(path)));
        }
        out
    }

    fn has_nav(&self) -> bool {
        !self.additional_pages().is_empty()
            || self.artifacts_enabled()
            || self.mdbook_enabled()
            || self.funding_page()
            || self.changelog_page()
    }

    fn nav_html(&self) -> String {
        if !self.has_nav() {
            return String::new();
        }
        let pages: Vec<Value> = self
            .additional_pages()
            .iter()
            .map(|(t, h, _)| json!({"title": t, "href": h}))
            .collect();
        let ctx = json!({
            "prefix": self.prefix,
            "additional_pages": pages,
            "artifacts": self.artifacts_enabled(),
            "mdbook": self.mdbook_enabled(),
            "funding": self.funding_page(),
            "changelog": self.changelog_page(),
        });
        tmpl::render(templates::NAV, &ctx)
    }

    fn logo_file_name(&self) -> Option<String> {
        self.cfg()
            .styles
            .logo
            .as_ref()
            .map(|l| file_name_of(l))
    }

    fn layout_ctx(&self, content: &str, scripts: &str) -> Value {
        let cfg = self.cfg();
        let analytics = match &cfg.analytics {
            None => Value::Null,
            Some(AnalyticsConfig::Google(g)) => json!({"google": {"tracking_id": g.tracking_id}}),
            Some(AnalyticsConfig::Plausible(p)) => json!({"plausible": {
                "domain": p.domain,
                "script_url": p.script_url.clone().unwrap_or_else(|| "https://plausible.io/js/script.js".to_string())
            }}),
            Some(AnalyticsConfig::Fathom(f)) => json!({"fathom": {"site": f.site}}),
            Some(AnalyticsConfig::Umami(u)) => json!({"umami": {"website": u.website, "script_url": u.script_url}}),
        };
        json!({
            "theme": cfg.styles.theme.class(),
            "name": cfg.project.name,
            "homepage": cfg.project.homepage,
            "favicon": true,
            "prefix": self.prefix,
            "description": cfg.project.description,
            "social": {
                "image": cfg.social.image,
                "image_alt": cfg.social.image_alt,
                "twitter_account": cfg.social.twitter_account,
            },
            "additional_css": !cfg.styles.additional_css.is_empty(),
            "head": "",
            "repository": cfg.project.repository,
            "logo": self.logo_file_name(),
            "nav": self.nav_html(),
            "content": content,
            "license": cfg.project.license,
            "analytics": analytics,
            "scripts": scripts,
        })
    }

    fn render_page(&self, content: &str, scripts: &str) -> String {
        tmpl::render(templates::LAYOUT, &self.layout_ctx(content, scripts))
    }

    fn write(&self, rel: &str, contents: &[u8]) -> Result<()> {
        let path = self.dist.join(rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| OrandaError::other(format!("failed to create directory {}: {}", parent.display(), e)))?;
        }
        std::fs::write(&path, contents).map_err(|e| OrandaError::other(format!("failed to write {}: {}", path.display(), e)))?;
        Ok(())
    }

    fn read_asset(&self, path: &Path, display: &str) -> Result<Vec<u8>> {
        std::fs::read(path).map_err(|e| OrandaError::AssetRead {
            path: display.to_string(),
            source: e,
        })
    }

    pub fn build(&self, opts: &BuildOpts) -> Result<()> {
        let cfg = self.cfg();
        if let Some(css) = &self.css_override {
            message::warning(&format!("Overriding oranda_css path with {}", css));
        }

        // Releases (GitHub) – always fails offline.
        let mut github_repo = None;
        if let Some(repo_url) = &cfg.project.repository {
            match parse_github_repo(repo_url) {
                Some(repo) => {
                    let proxy = format!(
                        "https://octolotl.axodotdev.host/releases/{}/{}",
                        repo.owner, repo.name
                    );
                    let gh = format!(
                        "https://api.github.com/repos/{}/{}/releases",
                        repo.owner, repo.name
                    );
                    let chain = crate::net::fetch_with_proxy(&proxy, &gh);
                    let needs_releases = cfg.components.changelog.is_some()
                        || cfg.components.artifacts.as_ref().map(|a| a.cargo_dist).unwrap_or(false);
                    if needs_releases {
                        OrandaError::GithubReleases { causes: chain }.report().eprint();
                    } else {
                        Report::warning(format!(
                            "Failed checking for Github releases for repo, ({}/{}). Proceeding without releases...",
                            repo.owner, repo.name
                        ))
                        .eprint();
                    }
                    github_repo = Some(repo);
                }
                None => {
                    OrandaError::RepoParse {
                        url: repo_url.clone(),
                    }
                    .report()
                    .eprint();
                }
            }
        }
        let _ = github_repo;

        let components = self.components_list();
        if !components.is_empty() {
            message::info(&format!("Building components: {}", components.join(", ")));
        }
        if self.artifacts_enabled() {
            message::warning("You seem to have release automation set up, but we didn't detect any releases. The install page and associated widget will be empty. To disable this, set `artifacts: false`");
        }

        // Funding data (parsed before writing anything so errors abort early)
        let funding = if self.funding_page() { Some(self.load_funding()?) } else { None };

        // README
        let readme_path = self.root.join(&cfg.project.readme_path);
        let readme_html = if readme_path.is_file() {
            let md = std::fs::read_to_string(&readme_path).map_err(|e| OrandaError::AssetRead {
                path: cfg.project.readme_path.clone(),
                source: e,
            })?;
            Some(crate::markdown::to_html(&md, cfg.styles.syntax_theme))
        } else if Path::new(&cfg.project.readme_path).is_absolute() {
            return Err(OrandaError::AssetRead {
                path: cfg.project.readme_path.clone(),
                source: std::io::Error::new(std::io::ErrorKind::NotFound, "No such file or directory (os error 2)"),
            });
        } else {
            message::warning(&format!("{} could not be found on disk!", cfg.project.readme_path));
            None
        };

        if opts.json_only {
            std::fs::create_dir_all(&self.dist).ok();
            if self.artifacts_enabled() {
                self.write("artifacts.json", self.artifacts_json().as_bytes())?;
            }
            message::success(&format!("Your site build is located in `{}`.", cfg.build.dist_dir));
            return Ok(());
        }

        std::fs::create_dir_all(&self.dist).map_err(|e| OrandaError::other(format!("failed to create dist dir: {}", e)))?;

        // CSS
        match &self.css_override {
            Some(css) => {
                let data = self.read_asset(Path::new(css), css)?;
                let name = file_name_of(css);
                self.write(&name, &data)?;
            }
            None => {
                let version = cfg
                    .styles
                    .oranda_css_version
                    .clone()
                    .unwrap_or_else(|| ORANDA_CSS_VERSION.to_string());
                let proxy = format!(
                    "https://octolotl.axodotdev.host/downloads/axodotdev/oranda/{}/oranda.css",
                    version
                );
                let gh = format!(
                    "https://api.github.com/repos/axodotdev/oranda/releases/download/{}/oranda.css",
                    version
                );
                let chain = crate::net::fetch_with_proxy(&proxy, &gh);
                return Err(OrandaError::CssFetch { causes: chain });
            }
        }

        // Logo
        if let Some(logo) = &cfg.styles.logo {
            let data = self.read_asset(&self.root.join(logo), logo)?;
            self.write(&file_name_of(logo), &data)?;
        }
        // Favicon
        match &cfg.styles.favicon {
            Some(fav) => {
                let data = self.read_asset(&self.root.join(fav), fav)?;
                self.write(&file_name_of(fav), &data)?;
            }
            None => self.write("favicon.ico", FAVICON)?,
        }

        // Pages
        let artifacts_enabled = self.artifacts_enabled();
        let index_content = tmpl::render(
            templates::INDEX_CONTENT,
            &json!({"readme": readme_html}),
        );
        let index_scripts = tmpl::render(
            templates::INDEX_SCRIPTS,
            &json!({"artifacts": artifacts_enabled, "prefix": self.prefix}),
        );
        self.write("index.html", self.render_page(&index_content, &index_scripts).as_bytes())?;

        // Additional pages
        for (_title, _href, path) in self.additional_pages() {
            let rel = path.strip_prefix(&self.root).unwrap_or(&path).to_path_buf();
            if !path.is_file() {
                return Err(OrandaError::PathNotFound {
                    path: rel.display().to_string(),
                });
            }
            let md = std::fs::read_to_string(&path).map_err(|e| OrandaError::AssetRead {
                path: rel.display().to_string(),
                source: e,
            })?;
            let html = crate::markdown::to_html(&md, cfg.styles.syntax_theme);
            let content = tmpl::render(templates::PAGE_CONTENT, &json!({"content": html}));
            self.write(&rel.display().to_string(), self.render_page(&content, "").as_bytes())?;
        }

        if artifacts_enabled {
            let content = self.artifacts_content();
            let scripts = tmpl::render(templates::ARTIFACTS_SCRIPTS, &json!({"prefix": self.prefix}));
            self.write("artifacts/index.html", self.render_page(&content, &scripts).as_bytes())?;
            self.write("artifacts.json", self.artifacts_json().as_bytes())?;
        }

        if self.changelog_page() {
            let cl = cfg.components.changelog.as_ref().unwrap();
            let content = tmpl::render(
                templates::CHANGELOG_CONTENT,
                &json!({
                    "prefix": self.prefix,
                    "rss": cl.rss_feed,
                    "rss_svg": crate::svgs::RSS,
                    "has_prereleases": false,
                    "releases": [],
                }),
            );
            let scripts = tmpl::render(templates::ARTIFACTS_SCRIPTS, &json!({"prefix": self.prefix}));
            self.write("changelog/index.html", self.render_page(&content, &scripts).as_bytes())?;
            if cl.rss_feed {
                self.write("changelog.rss", self.rss().as_bytes())?;
            }
        }

        if let Some(funding) = funding {
            let content = tmpl::render(templates::FUNDING_CONTENT, &funding);
            self.write("funding/index.html", self.render_page(&content, "").as_bytes())?;
        }

        // static dir
        let static_dir = self.root.join(&cfg.build.static_dir);
        if static_dir.is_dir() {
            let dest = self.dist.join(&cfg.build.static_dir);
            copy_dir(&static_dir, &dest)?;
        }

        self.write("artifacts.js", ARTIFACTS_JS.as_bytes())?;

        // additional css
        if !cfg.styles.additional_css.is_empty() {
            let mut out = String::new();
            for css in &cfg.styles.additional_css {
                if css.starts_with("http://") || css.starts_with("https://") {
                    let chain = crate::net::request_error_chain(css);
                    return Err(OrandaError::RemoteFetch {
                        url: css.clone(),
                        causes: chain,
                    });
                }
                let data = std::fs::read_to_string(self.root.join(css)).map_err(|e| OrandaError::AssetRead {
                    path: css.clone(),
                    source: e,
                })?;
                out.push_str(&format!("/* {} */", css));
                out.push_str(&data);
            }
            self.write("custom.css", out.as_bytes())?;
        }

        message::success(&format!("Your site build is located in `{}`.", cfg.build.dist_dir));
        Ok(())
    }

    fn rss(&self) -> String {
        let cfg = self.cfg();
        let name = &cfg.project.name;
        let repo = cfg.project.repository.clone().unwrap_or_default();
        format!(
            "<?xml version=\"1.0\" encoding=\"utf-8\"?><rss version=\"2.0\" xmlns:atom=\"http://www.w3.org/2005/Atom\"><channel><title>{name} Changelog</title><link>http://127.0.0.1:7979{prefix}/changelog</link><description>Changelog information for {name}</description><category domain=\"{repo}\">{name} Changelog</category><atom:link href=\"http://127.0.0.1:7979{prefix}/changelog.rss\" rel=\"self\"/></channel></rss>",
            name = xml_escape(name),
            prefix = self.prefix,
            repo = xml_escape(&repo)
        )
    }

    fn installers(&self) -> Vec<(String, String)> {
        // sorted by label
        let mut v = Vec::new();
        if let Some(a) = &self.cfg().components.artifacts {
            if let Some(pm) = &a.package_managers {
                for (k, val) in pm.preferred.iter().chain(pm.additional.iter()) {
                    v.push((k.clone(), val.clone()));
                }
            }
        }
        v.sort_by(|a, b| a.0.cmp(&b.0));
        v
    }

    fn artifacts_content(&self) -> String {
        let installers: Vec<Value> = self
            .installers()
            .iter()
            .map(|(label, hint)| {
                let highlighted = crate::highlight::highlight_html(hint, Some("sh"), self.cfg().styles.syntax_theme);
                json!({"label": label, "run_hint": hint, "highlighted": highlighted})
            })
            .collect();
        tmpl::render(
            templates::ARTIFACTS_CONTENT,
            &json!({
                "installers": installers,
                "copy_svg": crate::svgs::COPY,
                "has_checksum_files": false,
                "files": [],
            }),
        )
    }

    fn artifacts_json(&self) -> String {
        let installers = self.installers();
        let n = installers.len();
        let idx: Vec<Value> = (0..n).rev().map(|i| Value::from(i)).collect();
        // installers in config order (preferred then additional), not sorted
        let mut ordered = Vec::new();
        if let Some(a) = &self.cfg().components.artifacts {
            if let Some(pm) = &a.package_managers {
                for (k, val) in pm.preferred.iter().chain(pm.additional.iter()) {
                    ordered.push(json!({"label": k, "description": "", "app_name": null, "method": {"type": "Run", "file": null, "run_hint": val}}));
                }
            }
        }
        let targets = [
            "aarch64-apple-darwin",
            "aarch64-pc-windows-msvc",
            "aarch64-unknown-linux-gnu",
            "aarch64-unknown-linux-musl",
            "i686-apple-darwin",
            "i686-pc-windows-msvc",
            "i686-unknown-linux-gnu",
            "i686-unknown-linux-musl",
            "x86_64-apple-darwin",
            "x86_64-pc-windows-msvc",
            "x86_64-unknown-linux-gnu",
            "x86_64-unknown-linux-musl",
        ];
        let mut targets_map = serde_json::Map::new();
        let mut platforms = Vec::new();
        if n > 0 {
            for t in targets {
                targets_map.insert(t.to_string(), Value::Array(idx.clone()));
            }
            for (t, name) in [
                ("aarch64-apple-darwin", "macOS Apple Silicon"),
                ("x86_64-apple-darwin", "macOS Intel"),
                ("x86_64-pc-windows-msvc", "Windows x64"),
                ("x86_64-unknown-linux-gnu", "Linux x64"),
            ] {
                platforms.push(json!({"target": [t], "display_name": name, "installers": idx.clone()}));
            }
        }
        let v = json!({
            "format_version": "0.6.5",
            "tag": "current",
            "formatted_date": null,
            "platforms_with_downloads": platforms,
            "downloadable_files": [],
            "release": {"artifacts": {"files": [], "installers": ordered, "targets": targets_map}},
            "os_script": format!("{}/artifacts.js", self.prefix),
            "has_checksum_files": false,
        });
        serde_json::to_string(&v).unwrap()
    }

    fn load_funding(&self) -> Result<Value> {
        let cfg = self.cfg();
        let fcfg = cfg.components.funding.as_ref().unwrap();
        let yml_path = self.funding_yml_path().unwrap();
        let md_path = self.funding_md_path().unwrap();
        let mut items: Vec<(FundingType, String, String, String, Option<&'static str>)> = Vec::new();
        if yml_path.is_file() {
            let contents = std::fs::read_to_string(&yml_path).map_err(|_| OrandaError::FundingYml)?;
            let parsed: serde_yaml::Value = serde_yaml::from_str(&contents).map_err(|_| OrandaError::FundingYml)?;
            let map = match parsed {
                serde_yaml::Value::Mapping(m) => m,
                serde_yaml::Value::Null => serde_yaml::Mapping::new(),
                _ => return Err(OrandaError::FundingYml),
            };
            for (k, v) in map {
                let key = k.as_str().ok_or(OrandaError::FundingYml)?.to_string();
                let values: Vec<String> = match v {
                    serde_yaml::Value::String(s) => vec![s],
                    serde_yaml::Value::Sequence(seq) => seq
                        .into_iter()
                        .map(|x| match x {
                            serde_yaml::Value::String(s) => Ok(s),
                            serde_yaml::Value::Number(n) => Ok(n.to_string()),
                            _ => Err(OrandaError::FundingYml),
                        })
                        .collect::<Result<Vec<_>>>()?,
                    serde_yaml::Value::Null => vec![],
                    serde_yaml::Value::Number(n) => vec![n.to_string()],
                    _ => return Err(OrandaError::FundingYml),
                };
                let (ftype, title, href_fn, svg): (FundingType, &str, Box<dyn Fn(&str) -> String>, Option<&'static str>) = match key.as_str() {
                    "github" => (FundingType::Github, "GitHub", Box::new(|v| format!("https://github.com/sponsors/{}", v)), Some(crate::svgs::GITHUB)),
                    "patreon" => (FundingType::Patreon, "Patreon", Box::new(|v| format!("https://patreon.com/{}", v)), Some(crate::svgs::PATREON)),
                    "open_collective" => (FundingType::OpenCollective, "OpenCollective", Box::new(|v| format!("https://opencollective.com/{}", v)), Some(crate::svgs::OPEN_COLLECTIVE)),
                    "ko_fi" => (FundingType::KoFi, "Ko-fi", Box::new(|v| format!("https://ko-fi.com/{}", v)), Some(crate::svgs::KO_FI)),
                    "tidelift" => (FundingType::Tidelift, "Tidelift", Box::new(|v| format!("https://tidelift.com/subscription/pkg/{}", v)), Some(crate::svgs::TIDELIFT)),
                    "community_bridge" => (FundingType::CommunityBridge, "CommunityBridge", Box::new(|v| format!("https://crowdfunding.lfx.linuxfoundation.org/projects/{}", v)), Some(crate::svgs::GENERIC)),
                    "liberapay" => (FundingType::Liberapay, "Liberapay", Box::new(|v| format!("https://liberapay.com/{}", v)), Some(crate::svgs::LIBERAPAY)),
                    "issuehunt" => (FundingType::Issuehunt, "IssueHunt", Box::new(|v| format!("https://issuehunt.com/r/{}", v)), Some(crate::svgs::GENERIC)),
                    "custom" => (FundingType::Custom, "", Box::new(|v| v.to_string()), Some(crate::svgs::GENERIC)),
                    _ => return Err(OrandaError::FundingYml),
                };
                for v in values {
                    let t = if title.is_empty() { v.clone() } else { title.to_string() };
                    items.push((ftype, t, href_fn(&v), key.clone(), svg));
                }
            }
        }
        let content = if md_path.is_file() {
            let md = std::fs::read_to_string(&md_path).map_err(|e| OrandaError::AssetRead {
                path: md_path.display().to_string(),
                source: e,
            })?;
            Some(crate::markdown::to_html(&md, cfg.styles.syntax_theme))
        } else {
            None
        };
        let mut preferred = Value::Null;
        if let Some(pref) = fcfg.preferred_funding {
            if let Some(pos) = items.iter().position(|i| i.0 == pref) {
                let it = items.remove(pos);
                preferred = json!({"title": it.1, "href": it.2, "svg": it.4});
            }
        }
        let items_v: Vec<Value> = items
            .iter()
            .map(|i| json!({"title": i.1, "href": i.2, "svg": i.4}))
            .collect();
        Ok(json!({
            "preferred": preferred,
            "content": content,
            "items": items_v,
        }))
    }
}

pub fn file_name_of(p: &str) -> String {
    Path::new(p)
        .file_name()
        .map(|f| f.to_string_lossy().to_string())
        .unwrap_or_else(|| p.to_string())
}

fn xml_escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;")
}

pub fn copy_dir(src: &Path, dest: &Path) -> Result<()> {
    std::fs::create_dir_all(dest).map_err(|e| OrandaError::other(format!("failed to create {}: {}", dest.display(), e)))?;
    for entry in std::fs::read_dir(src).map_err(|e| OrandaError::other(format!("failed to read {}: {}", src.display(), e)))? {
        let entry = entry.map_err(|e| OrandaError::other(e.to_string()))?;
        let path = entry.path();
        let target = dest.join(entry.file_name());
        if path.is_dir() {
            copy_dir(&path, &target)?;
        } else {
            std::fs::copy(&path, &target).map_err(|e| OrandaError::other(format!("failed to copy {}: {}", path.display(), e)))?;
        }
    }
    Ok(())
}
