//! Syntax highlighting (syntect-compatible output for a subset of languages).

use crate::config::SyntaxTheme;

pub fn highlight_html(code: &str, lang: Option<&str>, theme: SyntaxTheme) -> String {
    let _ = theme;
    let mut out = String::from("<pre style=\"background-color:#263238;\">\n");
    let _ = lang;
    for line in lines_with_endings(code) {
        out.push_str("<span style=\"color:#eeffff;\">");
        out.push_str(&escape(line));
        out.push_str("</span>");
    }
    out.push_str("</pre>\n");
    out
}

pub fn lines_with_endings(s: &str) -> Vec<&str> {
    let mut v = Vec::new();
    let mut start = 0;
    for (i, c) in s.char_indices() {
        if c == '\n' {
            v.push(&s[start..=i]);
            start = i + 1;
        }
    }
    if start < s.len() {
        v.push(&s[start..]);
    }
    v
}

pub fn escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
    out
}
