fn bin_name() -> String {
    std::env::args()
        .next()
        .and_then(|a| {
            Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
        })
        .unwrap_or_else(|| "oranda".to_string())
}

fn print_help(path: &[&str], long: bool) {
    let text = match (path, long) {
        ([], true) => help_text::ROOT_LONG,
        ([], false) => help_text::ROOT_SHORT,
        (["build"], true) => help_text::BUILD_LONG,
        (["build"], false) => help_text::BUILD_SHORT,
        (["dev"], true) => help_text::DEV_LONG,
        (["dev"], false) => help_text::DEV_SHORT,
        (["serve"], true) => help_text::SERVE_LONG,
        (["serve"], false) => help_text::SERVE_SHORT,
        (["generate"], true) => help_text::GENERATE_LONG,
        (["generate"], false) => help_text::GENERATE_SHORT,
        (["generate", "ci"], true) => help_text::GENERATE_CI_LONG,
        (["generate", "ci"], false) => help_text::GENERATE_CI_SHORT,
        _ => help_text::ROOT_LONG,
    };
    print!("{}", text.replace("{bin}", &bin_name()));
}

fn usage_for(path: &[&str]) -> String {
    let bin = bin_name();
    match path {
        [] => format!("Usage: {} [OPTIONS] <COMMAND>", bin),
        ["generate"] => format!("Usage: {} generate [OPTIONS] <COMMAND>", bin),
        _ => format!("Usage: {} {} [OPTIONS]", bin, path.join(" ")),
    }
}

fn help_subcommand(args: &[String]) -> ! {
    // Resolve the path of subcommands.
    let mut path: Vec<&str> = Vec::new();
    for a in args {
        let valid = match path.as_slice() {
            [] => matches!(a.as_str(), "build" | "dev" | "serve" | "generate" | "help"),
            ["generate"] => matches!(a.as_str(), "ci" | "help"),
            _ => false,
        };
        if !valid {
            eprintln!(
                "error: unrecognized subcommand '{}'\n\n{}\n\nFor more information, try '--help'.",
                a,
                usage_for(&path)
            );
            std::process::exit(2);
        }
        if a == "help" {
            // `help help` prints the help of the help command; approximate with root help
            break;
        }
        path.push(a.as_str());
    }
    print_help(&path, true);
    std::process::exit(0);
}

fn main() {
    message::init();
    let matches = match build_cli().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            // Mirror clap's exit behaviour
            e.exit();
        }
    };

    // Determine subcommand path and help requests.
    let mut path: Vec<&str> = Vec::new();
    let mut cur = &matches;
    let mut help_short = matches.get_flag("help-short");
    let mut help_long = matches.get_flag("help-long");
    while let Some((name, sub)) = cur.subcommand() {
        path.push(name);
        cur = sub;
        help_short |= sub.get_flag("help-short");
        help_long |= sub.get_flag("help-long");
    }
    if path.first() == Some(&"help") {
        let args: Vec<String> = cur
            .get_many::<String>("args")
            .map(|v| v.cloned().collect())
            .unwrap_or_default();
        help_subcommand(&args);
    }
    if help_long || help_short {
        print_help(&path, help_long);
        std::process::exit(0);
    }

    let json_output = matches.get_one::<String>("output-format").map(|s| s == "json").unwrap_or(false);

    let result: errors::Result<()> = match path.as_slice() {
        ["build"] => {
            let json_only = cur.get_flag("json-only");
            commands::build(site::BuildOpts { json_only })
        }
        ["dev"] => {
            let port = cur.get_one::<u16>("port").copied();
            let no_first_build = cur.get_flag("no-first-build");
            let include: Vec<String> = cur
                .get_many::<String>("include-paths")
                .map(|v| v.cloned().collect())
                .unwrap_or_default();
            commands::dev(port, no_first_build, include)
        }
        ["serve"] => {
            let port = cur.get_one::<u16>("port").copied().unwrap_or(7979);
            commands::serve(port)
        }
        ["generate", "ci"] => {
            let gen_matches = matches.subcommand().unwrap().1;
            let output_path = cur
                .get_one::<String>("output-path")
                .or_else(|| gen_matches.get_one::<String>("output-path"))
                .cloned();
            let site_path = cur
                .get_one::<String>("site-path")
                .or_else(|| gen_matches.get_one::<String>("site-path"))
                .cloned();
            commands::generate_ci(output_path, site_path)
        }
        _ => Ok(()),
    };

    if let Err(e) = result {
        let report = e.report();
        if json_output {
            println!("{}", report.to_json());
        }
        report.eprint();
        std::process::exit(255);
    }
}

