        }
        if let Some(sn) = &self.snippet {
            s.push_str(&format!("\"filename\": \"{}\",", json_escape(&sn.filename)));
            s.push_str(&format!(
                "\"labels\": [{{\"span\": {{\"offset\": {},\"length\": {}}}}}],",
                sn.offset, sn.length
            ));
        }
        s.push_str("\"related\": []}");
        format!("{{\"diagnostic\": {}}}", s)
    }
