fn prompt(question: &str, hint: Option<&str>, default: bool) -> Result<bool> {
    if !std::io::stdin().is_terminal() || !std::io::stdout().is_terminal() {
        return Err(OrandaError::Panic {
            location: "src/generate.rs:56:14".to_string(),
            message: "Error while prompting!: NotTTY".to_string(),
        });
    }
    let yn = if default { "(Y/n)" } else { "(y/N)" };
    let color = crate::message::colors_enabled();
    let mut out = std::io::stdout();
    if color {
        print!("\x1b[38;5;2m? >o_o<\x1b[39m {} {}", question, yn);
    } else {
        print!("? >o_o< {} {}", question, yn);
    }
    if let Some(h) = hint {
        if color {
            print!("\n\x1b[38;5;14m[{}]\x1b[39m", h);
        } else {
            print!("\n[{}]", h);
        }
    }
    out.flush().ok();
    let mut answer = default;
    loop {
        let mut line = String::new();
        if std::io::stdin().read_line(&mut line).unwrap_or(0) == 0 {
            break;
        }
        let t = line.trim().to_ascii_lowercase();
        if t.is_empty() {
            break;
        }
        if t == "y" || t == "yes" {
            answer = true;
            break;
        }
        if t == "n" || t == "no" {
            answer = false;
            break;
        }
    }
    // Rewrite the prompt line like dialoguer does.
    let lines_up = if hint.is_some() { 2 } else { 1 };
    print!("\x1b[{}A\r\x1b[J", lines_up);
    let ans = if answer { "Yes" } else { "No" };
    if color {
        println!("\x1b[38;5;2m>\x1b[39m {} \x1b[38;5;2m{}\x1b[39m", question, ans);
    } else {
        println!("> {} {}", question, ans);
    }
    Ok(answer)
}

pub fn ci(output_path: Option<String>, site_path: Option<String>) -> Result<()> {
    message::info("Generating a CI deploy workflow for your site...");
    let site_root = match &site_path {
        Some(p) => Path::new(p).to_path_buf(),
        None => Path::new(".").to_path_buf(),
    };
    let dist_dir = {
        let cfg_path = site_root.join("oranda.json");
        if cfg_path.is_file() {
            match crate::config::parse_layer(&cfg_path) {
                Ok(l) => l
                    .build
                    .and_then(|b| b.dist_dir)
                    .unwrap_or_else(|| "public".to_string()),
                Err(e) => return Err(e),
            }
        } else {
            "public".to_string()
        }
    };
    let hyperlink = prompt(
        "Do you want to include a tool for checking generated hyperlinks?",
        Some("Read more about the link checker tool: https://github.com/untitaker/hyperlink"),
        true,
    )?;
    let latest = prompt(
        "Do you want to always use the latest version of oranda?",
        Some("Using the latest version means you don't have to rerun this command when oranda updates, but it may also break your site if you use a lot of configuration!"),
        false,
    )?;
    let gitignore = prompt(
        &format!(
            "Would you like to append the default destination directory (`{}`) to your .gitignore file?",
            dist_dir
        ),
        None,
        false,
    )?;

    let installer_url = if latest {
        "https://github.com/axodotdev/oranda/releases/latest/download/oranda-installer.sh".to_string()
    } else {
        format!(
            "https://github.com/axodotdev/oranda/releases/download/{}/oranda-installer.sh",
            crate::site::ORANDA_CSS_VERSION
        )
    };
    let cd_line = match &site_path {
        Some(p) => format!("          cd {}\n", p),
        None => String::new(),
    };
    let contents = WORKFLOW_HEAD
        .replace("{installer_url}", &installer_url)
        .replace("{cd_line}", &cd_line)
        .replace("{hyperlink}", if hyperlink { HYPERLINK } else { "" })
        .replace("{dist_dir}", &dist_dir);
    let out_path = output_path.unwrap_or_else(|| ".github/workflows/web.yml".to_string());
    let out = Path::new(&out_path);
    if let Some(parent) = out.parent() {
        if !parent.as_os_str().is_empty() {
            std::fs::create_dir_all(parent).map_err(|e| OrandaError::other(e.to_string()))?;
        }
    }
    std::fs::write(out, contents).map_err(|e| OrandaError::other(e.to_string()))?;
    if gitignore {
        let gi = site_root.join(".gitignore");
        let mut existing = std::fs::read_to_string(&gi).unwrap_or_default();
        existing.push_str(&format!("\n# Generated by `oranda generate ci`\n{}/", dist_dir));
        std::fs::write(&gi, existing).map_err(|e| OrandaError::other(e.to_string()))?;
    }
    message::success(&format!("Wrote CI file to {:?}", out_path));
    Ok(())
}
