        .and_then(|e| e.to_str())
        .map(|e| e.to_ascii_lowercase())
        .as_deref()
    {
        Some("html") | Some("htm") => "text/html",
        Some("css") => "text/css",
        Some("js") | Some("mjs") => "application/javascript",
        Some("json") => "application/json",
        Some("ico") => "image/x-icon",
        Some("rss") => "application/rss+xml",
        Some("png") => "image/png",
        Some("jpg") | Some("jpeg") => "image/jpeg",
        Some("gif") => "image/gif",
        Some("svg") => "image/svg+xml",
        Some("webp") => "image/webp",
        Some("txt") => "text/plain",
        Some("md") | Some("markdown") => "text/markdown",
        Some("xml") => "text/xml",
        Some("woff") => "font/woff",
        Some("woff2") => "font/woff2",
        Some("ttf") => "font/ttf",
        Some("otf") => "font/otf",
        Some("eot") => "application/vnd.ms-fontobject",
        Some("pdf") => "application/pdf",
        Some("wasm") => "application/wasm",
        Some("yml") | Some("yaml") => "text/x-yaml",
        Some("toml") => "text/x-toml",
        Some("csv") => "text/csv",
        Some("zip") => "application/zip",
        Some("gz") => "application/gzip",
        Some("mp4") => "video/mp4",
        Some("webm") => "video/webm",
        Some("mp3") => "audio/mpeg",
        Some("map") => "application/json",
        _ => "application/octet-stream",
    }
}

fn http_date(t: SystemTime) -> String {
    let dt: chrono::DateTime<chrono::Utc> = t.into();
    dt.format("%a, %d %b %Y %H:%M:%S GMT").to_string()
}

fn percent_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() + 0 && i + 2 <= bytes.len() - 1 {
            if let Ok(v) = u8::from_str_radix(&s[i + 1..i + 3], 16) {
                out.push(v);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).to_string()
}

struct Response {
    status: u16,
    reason: &'static str,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

fn respond(dist: &Path, prefix: &str, method: &str, raw_path: &str) -> Response {
    let now = http_date(SystemTime::now());
    let path_only = raw_path.split('?').next().unwrap_or("");
    let mk = |status, reason, headers: Vec<(String, String)>, body: Vec<u8>| Response {
        status,
        reason,
        headers,
        body,
    };
    if method != "GET" && method != "HEAD" {
        return mk(
            405,
            "Method Not Allowed",
            vec![
                ("allow".into(), "GET,HEAD".into()),
                ("content-length".into(), "0".into()),
                ("date".into(), now),
            ],
            vec![],
        );
    }
    let not_found = || Response {
        status: 404,
        reason: "Not Found",
        headers: vec![("content-length".into(), "0".into()), ("date".into(), http_date(SystemTime::now()))],
        body: vec![],
    };
    // Strip prefix
    let rel = if prefix.is_empty() {
        path_only.to_string()
    } else {
        if path_only == prefix {
            "/".to_string()
        } else if let Some(r) = path_only.strip_prefix(&format!("{}/", prefix)) {
            format!("/{}", r)
        } else {
            return not_found();
        }
    };
    let decoded = percent_decode(&rel);
    // Reject path traversal
    let mut fs_path = dist.to_path_buf();
    for seg in decoded.split('/') {
        if seg.is_empty() || seg == "." {
            continue;
        }
        if seg == ".." {
            return not_found();
        }
        fs_path.push(seg);
    }
    let meta = match std::fs::metadata(&fs_path) {
        Ok(m) => m,
        Err(_) => return not_found(),
    };
    if meta.is_dir() {
        if !decoded.ends_with('/') {
            let loc = format!("{}/", path_only);
            return mk(
                307,
                "Temporary Redirect",
                vec![
                    ("location".into(), loc),
                    ("content-length".into(), "0".into()),
                    ("date".into(), now),
                ],
                vec![],
            );
        }
        fs_path.push("index.html");
    }
    let meta = match std::fs::metadata(&fs_path) {
        Ok(m) if m.is_file() => m,
        _ => return not_found(),
    };
    let body = match std::fs::read(&fs_path) {
        Ok(b) => b,
        Err(_) => return not_found(),
    };
    let modified = meta.modified().unwrap_or(SystemTime::now());
    let headers = vec![
        ("content-type".into(), mime_for(&fs_path).to_string()),
        ("accept-ranges".into(), "bytes".into()),
        ("last-modified".into(), http_date(modified)),
        ("content-length".into(), body.len().to_string()),
        ("date".into(), now),
    ];
    let body = if method == "HEAD" { vec![] } else { body };
    mk(200, "OK", headers, body)
}

fn handle_conn(mut stream: TcpStream, dist: PathBuf, prefix: String) {
    stream.set_read_timeout(Some(Duration::from_secs(30))).ok();
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    loop {
        let mut request_line = String::new();
        match reader.read_line(&mut request_line) {
            Ok(0) | Err(_) => return,
            Ok(_) => {}
        }
        let mut headers: HashMap<String, String> = HashMap::new();
        loop {
            let mut line = String::new();
            match reader.read_line(&mut line) {
                Ok(0) | Err(_) => return,
                Ok(_) => {}
            }
            let l = line.trim_end_matches(['\r', '\n']);
            if l.is_empty() {
                break;
            }
            if let Some(idx) = l.find(':') {
                headers.insert(l[..idx].trim().to_ascii_lowercase(), l[idx + 1..].trim().to_string());
            }
        }
        // consume body if any
        if let Some(len) = headers.get("content-length").and_then(|v| v.parse::<usize>().ok()) {
            let mut buf = vec![0u8; len];
            if reader.read_exact(&mut buf).is_err() {
                return;
            }
        }
        let mut parts = request_line.split_whitespace();
        let method = parts.next().unwrap_or("GET").to_string();
        let path = parts.next().unwrap_or("/").to_string();
        let resp = respond(&dist, &prefix, &method, &path);
        let mut out = format!("HTTP/1.1 {} {}\r\n", resp.status, resp.reason);
        for (k, v) in &resp.headers {
            out.push_str(&format!("{}: {}\r\n", k, v));
        }
        out.push_str("\r\n");
        let mut bytes = out.into_bytes();
        bytes.extend_from_slice(&resp.body);
        if stream.write_all(&bytes).is_err() {
            return;
        }
        stream.flush().ok();
        let close = headers
            .get("connection")
            .map(|c| c.eq_ignore_ascii_case("close"))
            .unwrap_or(false);
        if close {
            return;
        }
    }
}

fn run_server(dist: PathBuf, prefix: String, port: u16) -> Result<()> {
    let listener = TcpListener::bind(("127.0.0.1", port)).map_err(|e| OrandaError::Panic {
        location: "src/serve.rs:1:1".to_string(),
        message: format!("failed to bind to port {}: {}", port, e),
    })?;
    for stream in listener.incoming() {
        match stream {
            Ok(s) => {
                let d = dist.clone();
                let p = prefix.clone();
                std::thread::spawn(move || handle_conn(s, d, p));
            }
            Err(_) => continue,
        }
    }
    Ok(())
}

fn site_info() -> Result<(PathBuf, String)> {
    let root = Path::new(".");
    let cfg = crate::site::load_config_display(root, "./oranda.json")?;
    let dist = root.join(&cfg.build.dist_dir);
    let prefix = match &cfg.build.path_prefix {
        Some(p) if !p.is_empty() => format!("/{}", p.trim_matches('/')),
        _ => String::new(),
    };
    Ok((dist, prefix))
}

pub fn serve(port: u16) -> Result<()> {
    let (dist, prefix) = site_info()?;
    let url = if prefix.is_empty() {
        format!("http://127.0.0.1:{}/", port)
    } else {
        format!("http://127.0.0.1:{}{}", port, prefix)
    };
    message::success(&format!("Your project is available at: {}", url));
    run_server(dist, prefix, port)
}

fn watch_paths(include: &[String]) -> Vec<PathBuf> {
    let root = Path::new(".");
    let mut paths: Vec<PathBuf> = Vec::new();
    let cfg = crate::site::load_config(root).ok();
    if let Some(cfg) = &cfg {
        for (_, p) in &cfg.build.additional_pages {
            let pb = root.join(p);
            if pb.exists() {
                paths.push(pb);
            }
        }
        let readme = root.join(&cfg.project.readme_path);
        if readme.exists() {
            paths.push(readme);
        }
        if let Some(f) = &cfg.components.funding {
            let md = root.join(f.md_path.clone().unwrap_or_else(|| "funding.md".to_string()));
            if md.exists() {
                paths.push(md);
            }
            let yml = root.join(f.yml_path.clone().unwrap_or_else(|| ".github/FUNDING.yml".to_string()));
            if yml.exists() {
                paths.push(yml);
            }
        }
        if let Some(m) = &cfg.components.mdbook {
            let cands: Vec<String> = match &m.path {
                Some(p) => vec![p.clone()],
                None => vec!["book".to_string(), "docs".to_string()],
            };
            for c in cands {
                let d = root.join(&c);
                if d.join("book.toml").is_file() {
                    paths.push(d);
                    break;
                }
            }
        }
    }
    if root.join("oranda.json").exists() {
        paths.push(root.join("oranda.json"));
    }
    if root.join("oranda-workspace.json").exists() {
        paths.push(root.join("oranda-workspace.json"));
    }
    for i in include {
        paths.push(root.join(i));
    }
    paths
}

fn snapshot(paths: &[PathBuf]) -> HashMap<PathBuf, Option<(SystemTime, u64)>> {
    let mut map = HashMap::new();
    for p in paths {
        if p.is_dir() {
            for entry in walkdir::WalkDir::new(p).into_iter().flatten() {
                let ep = entry.path().to_path_buf();
                let m = std::fs::metadata(&ep).ok().map(|m| (m.modified().unwrap_or(SystemTime::UNIX_EPOCH), m.len()));
                map.insert(ep, m);
            }
        } else {
            let m = std::fs::metadata(p).ok().map(|m| (m.modified().unwrap_or(SystemTime::UNIX_EPOCH), m.len()));
            map.insert(p.clone(), m);
        }
    }
    map
}

pub fn dev(port: Option<u16>, no_first_build: bool, include: Vec<String>) -> Result<()> {
    let port = port.unwrap_or(7979);
    let paths = watch_paths(&include);
    message::info(&format!("Found {} paths to watch, starting watch...", paths.len()));
    let opts = crate::site::BuildOpts { json_only: false };
    if !no_first_build {
        if let Err(e) = crate::workspace::build_or_workspace(Path::new("."), &opts) {
            e.report().eprint();
        }
    }
    let (dist, prefix) = site_info()?;
    let url = if prefix.is_empty() {
        format!("http://127.0.0.1:{}", port)
    } else {
        format!("http://127.0.0.1:{}{}", port, prefix)
    };
    message::success(&format!("Your project is available at: {}", url));
    let d = dist.clone();
    let p = prefix.clone();
    std::thread::spawn(move || {
        let _ = run_server(d, p, port);
    });
    let mut last = snapshot(&paths);
    loop {
        std::thread::sleep(Duration::from_millis(500));
        let cur = snapshot(&paths);
        let mut changed: Vec<PathBuf> = Vec::new();
        for (k, v) in &cur {
            if last.get(k) != Some(v) {
                changed.push(k.clone());
            }
        }
        for k in last.keys() {
            if !cur.contains_key(k) {
                changed.push(k.clone());
            }
        }
        if !changed.is_empty() {
            changed.sort();
            let shown: Vec<String> = changed
                .iter()
                .map(|c| std::fs::canonicalize(c).unwrap_or(c.clone()).display().to_string())
                .collect();
            message::info(&format!("Path(s) {:?} changed, rebuilding...", shown));
            if let Err(e) = crate::workspace::build_or_workspace(Path::new("."), &opts) {
                e.report().eprint();
            }
            last = cur;
        }
    }
}
