    pub refmap: HashMap<String, RefDef>,
}

fn is_space_or_tab(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

fn is_line_end_char(c: u8) -> bool {
    c == b'\n' || c == b'\r'
}

fn peek(line: &[u8], i: usize) -> u8 {
    if i < line.len() {
        line[i]
    } else {
        0
    }
}

impl Parser {
    pub fn new() -> Parser {
        let root = Node {
            kind: Kind::Document,
            parent: None,
            children: vec![],
            open: true,
            last_line_blank: false,
            start_line: 1,
            end_line: 0,
            internal_offset: 0,
            content: String::new(),
            task: None,
        };
        Parser {
            nodes: vec![root],
            root: 0,
            current: 0,
            line_number: 0,
            offset: 0,
            column: 0,
            first_nonspace: 0,
            first_nonspace_column: 0,
            indent: 0,
            blank: false,
            partially_consumed_tab: false,
            last_line_length: 0,
            refmap: HashMap::new(),
        }
    }

    pub fn parse(&mut self, text: &str) {
        let mut text = text.replace('\0', "\u{FFFD}");
        if !text.ends_with('\n') {
            text.push('\n');
        }
        let bytes = text.as_bytes();
        let mut start = 0;
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == b'\n' || bytes[i] == b'\r' {
                let mut end = i + 1;
                if bytes[i] == b'\r' && i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                    end = i + 2;
                }
                let line = &text[start..end];
                self.process_line(line);
                start = end;
                i = end;
            } else {
                i += 1;
            }
        }
        self.finalize_document();
    }

    fn add_child(&mut self, mut parent: usize, kind: Kind, start_column: usize) -> usize {
        while !self.can_contain(parent, &kind) {
            parent = self.finalize(parent);
        }
        let node = Node {
            kind,
            parent: Some(parent),
            children: vec![],
            open: true,
            last_line_blank: false,
            start_line: self.line_number,
            end_line: self.line_number,
            internal_offset: start_column,
            content: String::new(),
            task: None,
        };
        self.nodes.push(node);
        let idx = self.nodes.len() - 1;
        self.nodes[parent].children.push(idx);
        idx
    }

    fn can_contain(&self, parent: usize, child: &Kind) -> bool {
        match &self.nodes[parent].kind {
            Kind::Document | Kind::BlockQuote | Kind::Item(_) | Kind::FootnoteDefinition { .. } => {
                !matches!(child, Kind::Item(_) | Kind::TableRow { .. } | Kind::TableCell)
            }
            Kind::List(_) => matches!(child, Kind::Item(_)),
            Kind::Table { .. } => matches!(child, Kind::TableRow { .. }),
            Kind::TableRow { .. } => matches!(child, Kind::TableCell),
            _ => false,
        }
    }

    fn accepts_lines(&self, idx: usize) -> bool {
        matches!(
            self.nodes[idx].kind,
            Kind::Paragraph | Kind::Heading { .. } | Kind::CodeBlock { .. } | Kind::HtmlBlock { .. }
        )
    }

    fn finalize(&mut self, idx: usize) -> usize {
        let parent = self.nodes[idx].parent.unwrap_or(self.root);
        if !self.nodes[idx].open {
            return parent;
        }
        self.nodes[idx].open = false;
        if self.line_number > self.nodes[idx].start_line {
            self.nodes[idx].end_line = self.line_number - 1;
        } else {
            self.nodes[idx].end_line = self.line_number;
        }
        match self.nodes[idx].kind.clone() {
            Kind::Paragraph => {
                // Extract reference definitions
                loop {
                    let content = self.nodes[idx].content.clone();
                    if !content.starts_with('[') {
                        break;
                    }
                    match crate::markdown::inline::parse_reference_definition(&content, &mut self.refmap) {
                        Some(consumed) => {
                            self.nodes[idx].content = content[consumed..].to_string();
                        }
                        None => break,
                    }
                }
                if self.nodes[idx].content.trim().is_empty() {
                    // remove paragraph
                    let p = self.nodes[idx].parent.unwrap();
                    self.nodes[p].children.retain(|&c| c != idx);
                }
            }
            Kind::CodeBlock { fenced, .. } => {
                if !fenced {
                    // strip trailing blank lines
                    let content = &self.nodes[idx].content;
                    let mut end = content.len();
                    let b = content.as_bytes();
                    loop {
                        // find last line
                        let line_start = match content[..end].rfind('\n') {
                            Some(p) if p + 1 < end => p + 1,
                            Some(p) => {
