                                let ls = content[..p].rfind('\n').map(|q| q + 1).unwrap_or(0);
                                if content[ls..p].trim().is_empty() && ls < p + 1 {
                                    if ls == 0 && content[ls..p].trim().is_empty() && p + 1 == end {
                                        end = ls;
                                        break;
                                    }
                                    end = p + 1;
                                    // check again
                                    let ls2 = ls;
                                    if content[ls2..p].trim().is_empty() {
                                        end = ls2;
                                        continue;
                                    }
                                }
                                break;
                            }
                            None => {
                                if content[..end].trim().is_empty() {
                                    end = 0;
                                }
                                break;
                            }
                        };
                        let _ = b;
                        if content[line_start..end].trim().is_empty() {
                            end = line_start;
                        } else {
                            break;
                        }
                    }
                    self.nodes[idx].content.truncate(end);
                } else {
                    // first line is the info string
                    let content = self.nodes[idx].content.clone();
                    let (first, rest) = match content.find('\n') {
                        Some(p) => (&content[..p], &content[p + 1..]),
                        None => (&content[..], ""),
                    };
                    let info = crate::markdown::inline::unescape_info(first.trim());
                    if let Kind::CodeBlock { info: ref mut i, .. } = self.nodes[idx].kind {
                        *i = info;
                    }
                    self.nodes[idx].content = rest.to_string();
                }
            }
            Kind::HtmlBlock { .. } => {}
            Kind::List(mut data) => {
                // determine tightness
                let items = self.nodes[idx].children.clone();
                let mut tight = true;
                for (i, &item) in items.iter().enumerate() {
                    if self.nodes[item].last_line_blank && i + 1 < items.len() {
                        tight = false;
                        break;
                    }
                    let subs = self.nodes[item].children.clone();
                    for (j, &sub) in subs.iter().enumerate() {
                        if self.ends_with_blank_line(sub) && (i + 1 < items.len() || j + 1 < subs.len()) {
                            tight = false;
                            break;
                        }
                    }
                    if !tight {
                        break;
                    }
                }
                data.tight = tight;
                self.nodes[idx].kind = Kind::List(data);
                for &item in &items {
                    if let Kind::Item(ref mut d) = self.nodes[item].kind {
                        d.tight = tight;
                    }
                }
            }
            _ => {}
        }
        parent
    }

    fn ends_with_blank_line(&self, mut idx: usize) -> bool {
        loop {
            if self.nodes[idx].last_line_blank {
                return true;
            }
            match self.nodes[idx].kind {
                Kind::List(_) | Kind::Item(_) => {
                    if let Some(&last) = self.nodes[idx].children.last() {
                        idx = last;
                        continue;
                    }
                    return false;
                }
                _ => return false,
            }
        }
    }

    fn finalize_document(&mut self) {
        while self.current != self.root {
            self.current = self.finalize(self.current);
        }
        self.finalize(self.root);
    }

    // ----- line processing -----

    fn find_first_nonspace(&mut self, line: &[u8]) {
        let mut chars_to_tab = 4 - (self.column % 4);
        if self.first_nonspace <= self.offset {
            self.first_nonspace = self.offset;
            self.first_nonspace_column = self.column;
            loop {
                let c = peek(line, self.first_nonspace);
                if c == b' ' {
                    self.first_nonspace += 1;
                    self.first_nonspace_column += 1;
                    chars_to_tab -= 1;
                    if chars_to_tab == 0 {
                        chars_to_tab = 4;
                    }
                } else if c == b'\t' {
                    self.first_nonspace += 1;
                    self.first_nonspace_column += chars_to_tab;
                    chars_to_tab = 4;
                } else {
                    break;
                }
            }
        }
        self.indent = self.first_nonspace_column - self.column;
        let c = peek(line, self.first_nonspace);
        self.blank = is_line_end_char(c) || c == 0;
    }

    fn advance_offset(&mut self, line: &[u8], mut count: usize, columns: bool) {
        while count > 0 {
            let c = peek(line, self.offset);
            if c == 0 {
                break;
            }
            if c == b'\t' {
                let chars_to_tab = 4 - (self.column % 4);
                if columns {
                    self.partially_consumed_tab = chars_to_tab > count;
                    let chars_to_advance = chars_to_tab.min(count);
                    self.column += chars_to_advance;
                    self.offset += if self.partially_consumed_tab { 0 } else { 1 };
                    count -= chars_to_advance;
                } else {
                    self.partially_consumed_tab = false;
                    self.column += chars_to_tab;
                    self.offset += 1;
                    count -= 1;
                }
            } else {
                self.partially_consumed_tab = false;
                self.offset += 1;
                self.column += 1;
                count -= 1;
            }
        }
    }

    fn process_line(&mut self, line_str: &str) {
        let line = line_str.as_bytes();
        self.offset = 0;
        self.column = 0;
        self.blank = false;
        self.partially_consumed_tab = false;
        self.line_number += 1;

        let mut all_matched = true;
        let last_matched_container = self.check_open_blocks(line, &mut all_matched);
        let mut container = match last_matched_container {
            Some(c) => c,
            None => return,
        };
        let current = self.current;
        self.open_new_blocks(&mut container, line, all_matched);
        self.add_text_to_container(container, current, line, line_str);
        self.last_line_length = line.len();
    }

    fn check_open_blocks(&mut self, line: &[u8], all_matched: &mut bool) -> Option<usize> {
        let mut container = self.root;
        *all_matched = false;
        loop {
            let last_child = self.nodes[container].children.last().copied();
            let next = match last_child {
                Some(c) if self.nodes[c].open => c,
                _ => break,
            };
            container = next;
            self.find_first_nonspace(line);
            match self.nodes[container].kind.clone() {
                Kind::BlockQuote => {
                    if !self.parse_block_quote_prefix(line) {
                        return self.fail_match(container, all_matched);
                    }
                }
                Kind::Item(data) => {
                    if !self.parse_node_item_prefix(line, container, &data) {
                        return self.fail_match(container, all_matched);
                    }
                }
                Kind::CodeBlock { .. } => {
                    if !self.parse_code_block_prefix(line, container) {
                        return self.fail_match(container, all_matched);
                    }
                }
                Kind::Heading { .. } => {
                    return self.fail_match(container, all_matched);
                }
                Kind::HtmlBlock { kind } => {
                    if !self.parse_html_block_prefix(kind) {
                        return self.fail_match(container, all_matched);
                    }
                }
                Kind::Paragraph => {
                    if self.blank {
                        return self.fail_match(container, all_matched);
                    }
                }
                Kind::Table { .. } => {
                    if !self.parse_table_prefix(line) {
                        return self.fail_match(container, all_matched);
                    }
                }
                Kind::FootnoteDefinition { .. } => {
                    if !self.parse_footnote_definition_prefix(line, container) {
                        return self.fail_match(container, all_matched);
                    }
                }
                _ => {}
            }
        }
        *all_matched = true;
        Some(container)
    }

    fn fail_match(&mut self, container: usize, all_matched: &mut bool) -> Option<usize> {
        *all_matched = false;
        Some(self.nodes[container].parent.unwrap_or(self.root))
    }

    fn parse_block_quote_prefix(&mut self, line: &[u8]) -> bool {
        let indent = self.indent;
        if indent <= 3 && peek(line, self.first_nonspace) == b'>' {
            self.advance_offset(line, indent + 1, true);
            if is_space_or_tab(peek(line, self.offset)) {
                self.advance_offset(line, 1, true);
            }
            return true;
        }
        false
    }

    fn parse_node_item_prefix(&mut self, line: &[u8], container: usize, data: &ListData) -> bool {
        if self.indent >= data.marker_offset + data.padding {
            self.advance_offset(line, data.marker_offset + data.padding, true);
            true
        } else if self.blank && !self.nodes[container].children.is_empty() {
            self.advance_offset(line, self.first_nonspace - self.offset, false);
            true
        } else {
            false
        }
    }

    fn parse_code_block_prefix(&mut self, line: &[u8], container: usize) -> bool {
        let (fenced, fence_char, fence_length, fence_offset) = match &self.nodes[container].kind {
            Kind::CodeBlock { fenced, fence_char, fence_length, fence_offset, .. } => {
                (*fenced, *fence_char, *fence_length, *fence_offset)
            }
            _ => unreachable!(),
        };
        if !fenced {
            if self.indent >= 4 {
                self.advance_offset(line, 4, true);
                return true;
            } else if self.blank {
                self.advance_offset(line, self.first_nonspace - self.offset, false);
                return true;
            }
            return false;
        }
        // fenced
        let matched = if self.indent <= 3 && peek(line, self.first_nonspace) == fence_char {
            scan_close_code_fence(line, self.first_nonspace, fence_char, fence_length)
        } else {
            0
        };
        if matched > 0 {
            // closing fence
            self.advance_offset(line, matched, false);
            self.current = self.finalize(container);
            return false;
        }
        // skip opt. spaces of fence offset
        let mut i = fence_offset;
        while i > 0 && is_space_or_tab(peek(line, self.offset)) {
            self.advance_offset(line, 1, true);
            i -= 1;
        }
        true
    }

    fn parse_html_block_prefix(&mut self, kind: u8) -> bool {
        match kind {
            1..=5 => true,
            6 | 7 => !self.blank,
            _ => false,
        }
    }

    fn parse_table_prefix(&mut self, _line: &[u8]) -> bool {
        // A table continues as long as the line is not blank; rows are parsed later.
        !self.blank
    }

    fn parse_footnote_definition_prefix(&mut self, line: &[u8], container: usize) -> bool {
        if self.indent >= 4 {
            self.advance_offset(line, 4, true);
            true
        } else if self.blank && !self.nodes[container].children.is_empty() {
            true
        } else {
            self.blank
        }
    }

    fn open_new_blocks(&mut self, container: &mut usize, line: &[u8], all_matched: bool) {
        let mut maybe_lazy = matches!(self.nodes[self.current].kind, Kind::Paragraph);
        loop {
            let cont_kind = self.nodes[*container].kind.clone();
            if matches!(cont_kind, Kind::CodeBlock { .. } | Kind::HtmlBlock { .. }) {
                break;
            }
            self.find_first_nonspace(line);
            let indented = self.indent >= 4;
            let fnc = peek(line, self.first_nonspace);

            if !indented && fnc == b'>' {
                let blockquote_startpos = self.first_nonspace;
                self.advance_offset(line, self.first_nonspace + 1 - self.offset, false);
                if is_space_or_tab(peek(line, self.offset)) {
                    self.advance_offset(line, 1, true);
                }
                *container = self.add_child(*container, Kind::BlockQuote, blockquote_startpos + 1);
            } else if !indented && fnc == b'#' && {
                let (lvl, len) = scan_atx_heading_start(line, self.first_nonspace);
                if len > 0 {
                    let heading_startpos = self.first_nonspace;
                    self.advance_offset(line, heading_startpos + len - self.offset, false);
                    *container = self.add_child(*container, Kind::Heading { level: lvl, setext: false }, heading_startpos + 1);
                    // consume content up to closing sequence
                    let mut hashpos = line.len();
                    // find end: strip trailing spaces, then trailing #s preceded by space
                    let mut end = line.len();
                    while end > 0 && is_line_end_char(line[end - 1]) {
                        end -= 1;
                    }
                    while end > 0 && is_space_or_tab(line[end - 1]) {
                        end -= 1;
                    }
                    let mut p = end;
                    while p > 0 && line[p - 1] == b'#' {
                        p -= 1;
                    }
                    if p < end && (p == 0 || is_space_or_tab(line[p - 1]) || p <= self.offset) {
                        if p <= self.offset {
                            hashpos = self.offset.max(p);
                        } else {
                            hashpos = p;
                        }
                        end = hashpos;
                        while end > 0 && is_space_or_tab(line[end - 1]) {
                            end -= 1;
                        }
                    }
                    let start = self.offset.min(end);
                    let text = String::from_utf8_lossy(&line[start..end]).to_string();
                    self.nodes[*container].content = text;
                    // mark heading as fully consumed
                    self.offset = line.len();
                    true
                } else {
                    false
                }
            } {
                break;
            } else if !indented && (fnc == b'`' || fnc == b'~') && {
                let (fl, ok) = scan_open_code_fence(line, self.first_nonspace);
                if ok {
                    let first_nonspace = self.first_nonspace;
                    let offset = self.offset;
                    *container = self.add_child(
                        *container,
                        Kind::CodeBlock {
                            fenced: true,
                            fence_char: fnc,
                            fence_length: fl,
                            fence_offset: first_nonspace - offset,
                            info: String::new(),
                        },
                        first_nonspace + 1,
                    );
                    self.advance_offset(line, first_nonspace + fl - offset, false);
                    true
                } else {
                    false
                }
            } {
                // info string is added as the first content line
                break;
            } else if !indented && fnc == b'<' && {
                let kind = scan_html_block_start(line, self.first_nonspace, matches!(cont_kind, Kind::Paragraph) || (maybe_lazy && !all_matched));
                if kind > 0 {
                    *container = self.add_child(*container, Kind::HtmlBlock { kind }, self.first_nonspace + 1);
                    true
                } else {
                    false
                }
            } {
                // no offset change
                break;
            } else if !indented && matches!(cont_kind, Kind::Paragraph) && {
                let lvl = scan_setext_heading_line(line, self.first_nonspace);
                if lvl > 0 && all_matched {
                    // Try table first? comrak: setext takes precedence over table? (table check happens before)
                    let content = self.nodes[*container].content.clone();
                    // Only if paragraph has content (reference definitions excluded)
                    let mut tmp_refmap_ok = true;
                    let _ = &mut tmp_refmap_ok;
                    if !content.trim().is_empty() {
                        self.nodes[*container].kind = Kind::Heading { level: lvl, setext: true };
                        // strip trailing newline from content
                        let mut c = content;
                        while c.ends_with('\n') || c.ends_with('\r') {
                            c.pop();
                        }
                        self.nodes[*container].content = c;
                        self.advance_offset(line, line.len() - 1 - self.offset, false);
                        true
                    } else {
                        false
                    }
                } else {
                    false
                }
            } {
                break;
            } else if !indented && !(matches!(cont_kind, Kind::Paragraph) && !all_matched) && {
                let n = scan_thematic_break(line, self.first_nonspace);
                if n > 0 {
                    *container = self.add_child(*container, Kind::ThematicBreak, self.first_nonspace + 1);
                    self.advance_offset(line, line.len() - 1 - self.offset, false);
                    true
                } else {
                    false
                }
            } {
                break;
            } else if !indented && fnc == b'[' && line.get(self.first_nonspace + 1) == Some(&b'^') && {
                match scan_footnote_definition(line, self.first_nonspace) {
                    Some((label, len)) => {
                        self.advance_offset(line, self.first_nonspace + len - self.offset, false);
                        *container = self.add_child(*container, Kind::FootnoteDefinition { label }, self.first_nonspace + 1);
                        true
                    }
                    None => false,
                }
            } {
                // continue parsing the rest of the line as content of the footnote
                continue;
            } else if (!indented || matches!(cont_kind, Kind::List(_))) && {
                let interrupts_paragraph = matches!(cont_kind, Kind::Paragraph);
                match parse_list_marker(line, self.first_nonspace, interrupts_paragraph) {
                    Some((mut data, matched)) => {
                        let first_nonspace = self.first_nonspace;
                        let offset = self.offset;
                        let column = self.column;
                        self.advance_offset(line, first_nonspace + matched - offset, false);
                        let save_partially_consumed_tab = self.partially_consumed_tab;
                        let save_offset = self.offset;
                        let save_column = self.column;
                        while self.column - save_column <= 5 && is_space_or_tab(peek(line, self.offset)) {
                            self.advance_offset(line, 1, true);
                        }
                        let i = self.column - save_column;
                        if !(1..=4).contains(&i) || is_line_end_char(peek(line, self.offset)) || peek(line, self.offset) == 0 {
                            data.padding = matched + 1;
                            self.offset = save_offset;
                            self.column = save_column;
                            self.partially_consumed_tab = save_partially_consumed_tab;
                            if is_space_or_tab(peek(line, self.offset)) {
                                self.advance_offset(line, 1, true);
                            }
                        } else {
                            data.padding = matched + i;
                        }
                        data.marker_offset = self.indent;
                        let _ = column;
                        // add list if needed
                        let needs_list = match &cont_kind {
                            Kind::List(existing) => !lists_match(existing, &data),
                            _ => true,
                        };
                        if needs_list {
                            *container = self.add_child(*container, Kind::List(data), first_nonspace + 1);
                        }
                        *container = self.add_child(*container, Kind::Item(data), first_nonspace + 1);
                        true
                    }
                    None => false,
                }
            } {
                continue;
            } else if indented && !maybe_lazy && !self.blank {
                self.advance_offset(line, 4, true);
                *container = self.add_child(
                    *container,
                    Kind::CodeBlock { fenced: false, fence_char: 0, fence_length: 0, fence_offset: 0, info: String::new() },
                    self.offset + 1,
                );
                break;
            } else if !indented && matches!(cont_kind, Kind::Paragraph) && all_matched && {
                // GFM table: try to interpret this line as a delimiter row for the paragraph's last line
                self.try_open_table(*container, line)
            } {
                // container now is the table
                let last = self.nodes[*container].children.last().copied();
                let _ = last;
                break;
            } else {
                break;
            }
            if self.accepts_lines(*container) {
                break;
            }
            maybe_lazy = false;
        }
    }

    fn try_open_table(&mut self, container: usize, line: &[u8]) -> bool {
        let content = self.nodes[container].content.clone();
        // header is the last line of the paragraph content
        let trimmed = content.trim_end_matches(['\n', '\r']);
        let (prefix, header_line) = match trimmed.rfind('\n') {
            Some(p) => (&trimmed[..p + 1], &trimmed[p + 1..]),
            None => ("", trimmed),
        };
        let header_cells = match crate::markdown::table::split_row(header_line) {
            Some(c) => c,
            None => return false,
        };
        let delim_line = String::from_utf8_lossy(&line[self.offset..]).to_string();
        let delim_line = delim_line.trim_end_matches(['\n', '\r']).to_string();
        let alignments = match crate::markdown::table::parse_delimiter_row(&delim_line) {
            Some(a) => a,
            None => return false,
        };
        if alignments.len() != header_cells.len() {
            return false;
        }
        // Convert: paragraph keeps prefix (if any), table added after.
        let parent = self.nodes[container].parent.unwrap();
        if prefix.trim().is_empty() {
            // replace paragraph node with table
            self.nodes[container].kind = Kind::Table { alignments: alignments.clone() };
            self.nodes[container].content = String::new();
            let table = container;
            self.add_table_row(table, &header_cells, true);
        } else {
            self.nodes[container].content = prefix.to_string();
            self.finalize(container);
            let table = self.add_child(parent, Kind::Table { alignments: alignments.clone() }, 0);
            self.add_table_row(table, &header_cells, true);
            self.current = table;
            // note: `container` variable in caller stays the paragraph, so fix up
            self.pending_table = Some(table);
        }
        self.offset = line.len();
        true
    }

    fn add_table_row(&mut self, table: usize, cells: &[String], header: bool) {
        let row = self.add_child(table, Kind::TableRow { header }, 0);
        for c in cells {
            let cell = self.add_child(row, Kind::TableCell, 0);
            self.nodes[cell].content = c.clone();
            self.nodes[cell].open = false;
        }
        self.nodes[row].open = false;
    }

    fn add_text_to_container(&mut self, mut container: usize, last_matched_container: usize, line: &[u8], line_str: &str) {
        if let Some(t) = self.pending_table.take() {
            container = t;
        }
        self.find_first_nonspace(line);
        if self.blank {
            if let Some(&last) = self.nodes[container].children.last() {
                self.nodes[last].last_line_blank = true;
            }
        }
        let cont_kind = self.nodes[container].kind.clone();
        let last_line_blank = self.blank
            && !matches!(cont_kind, Kind::BlockQuote | Kind::Heading { .. } | Kind::ThematicBreak)
            && !(matches!(cont_kind, Kind::CodeBlock { fenced: true, .. }))
            && !(matches!(cont_kind, Kind::Item(_)) && self.nodes[container].children.is_empty() && self.nodes[container].start_line == self.line_number);
        self.nodes[container].last_line_blank = last_line_blank;
        // propagate up to parents while the container is the last child
        let mut tmp = container;
        while let Some(p) = self.nodes[tmp].parent {
            self.nodes[p].last_line_blank = false;
            tmp = p;
        }

        let current = self.current;
        if matches!(self.nodes[current].kind, Kind::Paragraph)
            && last_matched_container == current
            && container != current
            && !self.blank
            && false
        {
            // unreachable placeholder
        }

        if current != last_matched_container
            && container == last_matched_container
            && !self.blank
            && matches!(self.nodes[current].kind, Kind::Paragraph)
        {
            // lazy paragraph continuation
            self.add_line(current, line, line_str);
        } else {
            // finalize any blocks that were not matched
            let mut cur = current;
            while cur != last_matched_container && cur != self.root {
                cur = self.finalize(cur);
            }
            // if cur != last_matched_container it means the structure was changed by table; ok
            let kind = self.nodes[container].kind.clone();
            match kind {
                Kind::CodeBlock { .. } => {
                    self.add_line(container, line, line_str);
                }
                Kind::HtmlBlock { kind } => {
                    self.add_line(container, line, line_str);
                    let matches_end = match kind {
                        1 => contains_ci(&line[self.first_nonspace..], b"</script>") || contains_ci(&line[self.first_nonspace..], b"</pre>") || contains_ci(&line[self.first_nonspace..], b"</style>") || contains_ci(&line[self.first_nonspace..], b"</textarea>"),
                        2 => contains(&line[self.first_nonspace..], b"-->"),
                        3 => contains(&line[self.first_nonspace..], b"?>"),
                        4 => contains(&line[self.first_nonspace..], b">"),
                        5 => contains(&line[self.first_nonspace..], b"]]>"),
                        _ => false,
                    };
                    if matches_end {
                        self.current = self.finalize(container);
                        return;
                    }
                }
                Kind::Heading { setext: false, .. } => {
                    // content already set
                }
                Kind::Heading { setext: true, .. } => {}
                Kind::ThematicBreak => {}
                Kind::Table { .. } => {
                    if !self.blank && self.offset < line.len() {
                        let row_str = String::from_utf8_lossy(&line[self.offset..]).to_string();
                        let row_str = row_str.trim_end_matches(['\n', '\r']).to_string();
                        let ncols = match &self.nodes[container].kind {
                            Kind::Table { alignments } => alignments.len(),
                            _ => 0,
                        };
                        match crate::markdown::table::split_row(&row_str) {
                            Some(mut cells) => {
                                cells.truncate(ncols);
                                while cells.len() < ncols {
                                    cells.push(String::new());
                                }
                                self.add_table_row(container, &cells, false);
                            }
                            None => {
                                // not a row: close table and start paragraph
                                let parent = self.finalize(container);
                                let p = self.add_child(parent, Kind::Paragraph, self.first_nonspace + 1);
                                self.add_line(p, line, line_str);
                                self.current = p;
                                return;
                            }
                        }
                    }
                }
                _ => {
                    if self.accepts_lines(container) {
                        self.add_line(container, line, line_str);
                    } else if self.blank {
                        // do nothing
                    } else {
                        // create paragraph container
                        let p = self.add_child(container, Kind::Paragraph, self.first_nonspace + 1);
                        self.advance_offset(line, self.first_nonspace - self.offset, false);
                        self.add_line(p, line, line_str);
                        container = p;
                    }
                }
            }
            self.current = container;
        }
    }

    fn add_line(&mut self, idx: usize, line: &[u8], line_str: &str) {
        let content = &mut self.nodes[idx].content;
        if self.partially_consumed_tab {
            self.offset += 1;
            let chars_to_tab = 4 - (self.column % 4);
            for _ in 0..chars_to_tab {
                content.push(' ');
            }
        }
        if self.offset < line.len() {
            // ensure offset is at a char boundary
            let mut off = self.offset;
            while off < line.len() && !line_str.is_char_boundary(off) {
                off += 1;
            }
            content.push_str(&line_str[off..]);
        }
    }
}

// Extra field via trait hack: we keep pending_table in a thread local to avoid changing struct above.
impl Parser {
    #[allow(non_upper_case_globals)]
    const _dummy: () = ();
}

fn lists_match(a: &ListData, b: &ListData) -> bool {
    a.ordered == b.ordered && a.delimiter == b.delimiter && a.bullet_char == b.bullet_char
}

fn contains(hay: &[u8], needle: &[u8]) -> bool {
    hay.windows(needle.len()).any(|w| w == needle)
}

fn contains_ci(hay: &[u8], needle: &[u8]) -> bool {
    hay.windows(needle.len()).any(|w| w.eq_ignore_ascii_case(needle))
}

pub fn scan_atx_heading_start(line: &[u8], pos: usize) -> (u8, usize) {
    let mut i = pos;
    let mut level = 0;
    while peek(line, i) == b'#' {
        level += 1;
        i += 1;
    }
    if level == 0 || level > 6 {
        return (0, 0);
    }
    let c = peek(line, i);
    if is_space_or_tab(c) || is_line_end_char(c) || c == 0 {
        // consume following spaces
        let mut j = i;
        while is_space_or_tab(peek(line, j)) {
            j += 1;
        }
        return (level as u8, j - pos);
    }
    (0, 0)
}

pub fn scan_setext_heading_line(line: &[u8], pos: usize) -> u8 {
    let c = peek(line, pos);
    if c != b'=' && c != b'-' {
        return 0;
    }
    let mut i = pos;
    while peek(line, i) == c {
        i += 1;
    }
    while is_space_or_tab(peek(line, i)) {
        i += 1;
    }
    let e = peek(line, i);
    if is_line_end_char(e) || e == 0 {
        if c == b'=' {
            1
        } else {
            2
        }
    } else {
        0
    }
}

pub fn scan_thematic_break(line: &[u8], pos: usize) -> usize {
    let c = peek(line, pos);
    if c != b'*' && c != b'-' && c != b'_' {
        return 0;
    }
    let mut count = 0;
    let mut i = pos;
    loop {
        let x = peek(line, i);
        if x == c {
            count += 1;
        } else if is_space_or_tab(x) {
        } else if is_line_end_char(x) || x == 0 {
            break;
        } else {
            return 0;
        }
        i += 1;
    }
    if count >= 3 {
        i - pos
    } else {
        0
    }
}

pub fn scan_open_code_fence(line: &[u8], pos: usize) -> (usize, bool) {
    let c = peek(line, pos);
    let mut i = pos;
    while peek(line, i) == c {
        i += 1;
    }
    let len = i - pos;
    if len < 3 {
        return (0, false);
    }
    if c == b'`' {
        // no backticks in info string
        let mut j = i;
        while j < line.len() && !is_line_end_char(line[j]) {
            if line[j] == b'`' {
                return (0, false);
            }
            j += 1;
        }
    }
    (len, true)
}

pub fn scan_close_code_fence(line: &[u8], pos: usize, fence_char: u8, fence_length: usize) -> usize {
    let mut i = pos;
    while peek(line, i) == fence_char {
        i += 1;
    }
    if i - pos < fence_length {
        return 0;
    }
    let mut j = i;
    while is_space_or_tab(peek(line, j)) {
        j += 1;
    }
    let e = peek(line, j);
    if is_line_end_char(e) || e == 0 {
        i - pos
    } else {
        0
    }
}

const BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center", "col",
    "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
    "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header", "hr",
    "html", "iframe", "legend", "li", "link", "main", "menu", "menuitem", "nav", "noframes", "ol",
    "optgroup", "option", "p", "param", "section", "source", "summary", "table", "tbody", "td",
    "tfoot", "th", "thead", "title", "tr", "track", "ul",
];

pub fn scan_html_block_start(line: &[u8], pos: usize, in_paragraph_or_lazy: bool) -> u8 {
    let rest = &line[pos..];
    let rest_str = String::from_utf8_lossy(rest).to_string();
    let lower = rest_str.to_ascii_lowercase();
    // type 1
    for tag in ["<script", "<pre", "<style", "<textarea"] {
        if lower.starts_with(tag) {
            let after = lower.as_bytes().get(tag.len()).copied().unwrap_or(b'\n');
            if is_space_or_tab(after) || is_line_end_char(after) || after == b'>' {
                return 1;
            }
        }
    }
    if lower.starts_with("<!--") {
        return 2;
    }
    if lower.starts_with("<?") {
        return 3;
    }
    if rest.len() > 2 && rest[1] == b'!' && rest[2].is_ascii_alphabetic() {
        return 4;
    }
    if lower.starts_with("<![cdata[") {
        return 5;
    }
    // type 6: block tag
    {
        let mut i = 1;
        if peek(rest, i) == b'/' {
            i += 1;
        }
        let start = i;
        while i < rest.len() && rest[i].is_ascii_alphanumeric() {
            i += 1;
        }
        let name = lower[start..i].to_string();
        if BLOCK_TAGS.contains(&name.as_str()) {
            let after = peek(rest, i);
            if is_space_or_tab(after) || is_line_end_char(after) || after == b'>' || after == 0 || (after == b'/' && peek(rest, i + 1) == b'>') {
                return 6;
            }
        }
    }
    // type 7: complete open or closing tag alone on the line
    if !in_paragraph_or_lazy {
        if let Some(end) = crate::markdown::inline::scan_html_tag(rest) {
            // must be an open tag or closing tag (not comment etc)
            let tagb = &rest[..end];
            if (tagb.len() > 2 && tagb[1].is_ascii_alphabetic()) || (tagb.len() > 3 && tagb[1] == b'/' && tagb[2].is_ascii_alphabetic()) {
                let mut j = end;
                while is_space_or_tab(peek(rest, j)) {
                    j += 1;
                }
                let e = peek(rest, j);
                if is_line_end_char(e) || e == 0 {
                    return 7;
                }
            }
        }
    }
    0
}

pub fn parse_list_marker(line: &[u8], pos: usize, interrupts_paragraph: bool) -> Option<(ListData, usize)> {
    let c = peek(line, pos);
    let mut i = pos;
    if c == b'*' || c == b'-' || c == b'+' {
        i += 1;
        let n = peek(line, i);
        if !(is_space_or_tab(n) || is_line_end_char(n) || n == 0) {
            return None;
        }
        if interrupts_paragraph {
            // must not be blank item
            let mut j = i;
            while is_space_or_tab(peek(line, j)) {
                j += 1;
            }
            let e = peek(line, j);
            if is_line_end_char(e) || e == 0 {
                return None;
            }
        }
        return Some((
            ListData { ordered: false, start: 1, bullet_char: c, delimiter: 0, marker_offset: 0, padding: 0, tight: false },
            i - pos,
        ));
    }
    if c.is_ascii_digit() {
        let mut start: u32 = 0;
        let mut digits = 0;
        while peek(line, i).is_ascii_digit() {
            start = start.saturating_mul(10).saturating_add((peek(line, i) - b'0') as u32);
            digits += 1;
            i += 1;
            if digits > 9 {
                return None;
            }
        }
        let d = peek(line, i);
        if d != b'.' && d != b')' {
            return None;
        }
        i += 1;
        let n = peek(line, i);
        if !(is_space_or_tab(n) || is_line_end_char(n) || n == 0) {
            return None;
        }
        if interrupts_paragraph {
            if start != 1 {
                return None;
            }
            let mut j = i;
            while is_space_or_tab(peek(line, j)) {
                j += 1;
            }
            let e = peek(line, j);
            if is_line_end_char(e) || e == 0 {
                return None;
            }
        }
        return Some((
            ListData { ordered: true, start, bullet_char: 0, delimiter: d, marker_offset: 0, padding: 0, tight: false },
            i - pos,
        ));
    }
    None
}

pub fn scan_footnote_definition(line: &[u8], pos: usize) -> Option<(String, usize)> {
    // [^label]:
    if peek(line, pos) != b'[' || peek(line, pos + 1) != b'^' {
        return None;
    }
    let mut i = pos + 2;
    let start = i;
    while i < line.len() && line[i] != b']' && !is_space_or_tab(line[i]) && !is_line_end_char(line[i]) {
        i += 1;
    }
    if i == start || peek(line, i) != b']' || peek(line, i + 1) != b':' {
        return None;
    }
    let label = String::from_utf8_lossy(&line[start..i]).to_string();
    i += 2;
    while is_space_or_tab(peek(line, i)) {
        i += 1;
    }
    Some((label, i - pos))
}
