//! GFM table helpers.

use super::block::Align;

/// Split a table row into cell strings (unescaping `\|`). Returns None if the
/// line contains no pipe at all.
pub fn split_row(line: &str) -> Option<Vec<String>> {
    let trimmed = line.trim();
    if !trimmed.contains('|') {
        return None;
    }
    let mut cells = Vec::new();
    let mut cur = String::new();
    let chars: Vec<char> = trimmed.chars().collect();
    let mut i = 0;
    // skip leading pipe
    if chars.first() == Some(&'|') {
        i = 1;
    }
    let mut saw_pipe_end = false;
    let mut in_code = 0usize;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() && chars[i + 1] == '|' {
            cur.push('|');
            i += 2;
            continue;
        }
        if c == '\\' && i + 1 < chars.len() {
            cur.push(c);
            cur.push(chars[i + 1]);
            i += 2;
            continue;
        }
        if c == '`' {
            let mut n = 0;
            while i < chars.len() && chars[i] == '`' {
                n += 1;
                cur.push('`');
                i += 1;
            }
            if in_code == 0 {
                in_code = n;
            } else if in_code == n {
                in_code = 0;
            }
            continue;
        }
        if c == '|' && in_code == 0 {
            cells.push(cur.trim().to_string());
            cur = String::new();
            i += 1;
            if i == chars.len() {
                saw_pipe_end = true;
            }
            continue;
        }
        cur.push(c);
        i += 1;
    }
    if !saw_pipe_end {
        cells.push(cur.trim().to_string());
    }
    Some(cells)
}

pub fn parse_delimiter_row(line: &str) -> Option<Vec<Align>> {
    let cells = split_row(line)?;
    let mut out = Vec::new();
    for c in cells {
        let c = c.trim();
        if c.is_empty() {
            return None;
        }
        let left = c.starts_with(':');
        let right = c.ends_with(':');
        let inner = c.trim_start_matches(':').trim_end_matches(':');
        if inner.is_empty() || !inner.chars().all(|ch| ch == '-') {
            return None;
        }
        out.push(match (left, right) {
            (true, true) => Align::Center,
            (true, false) => Align::Left,
            (false, true) => Align::Right,
            (false, false) => Align::None,
        });
    }
    if out.is_empty() {
        return None;
    }
    Some(out)
}
