//! CommonMark inline parsing (+ GFM strikethrough, autolinks, footnote refs).

use super::block::RefDef;
use super::entities::parse_entity;
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub enum Inline {
    Text(String),
    Code(String),
    Emph(Vec<Inline>),
    Strong(Vec<Inline>),
    Strike(Vec<Inline>),
    Link { url: String, title: String, children: Vec<Inline> },
    Image { url: String, title: String, children: Vec<Inline> },
    Html(String),
    SoftBreak,
    HardBreak,
    FootnoteRef(String),
}

fn is_punct(c: char) -> bool {
    c.is_ascii_punctuation()
        || matches!(
            unicode_category(c),
            Some(PunctCat::Punct) | Some(PunctCat::Symbol)
        )
}

#[derive(PartialEq)]
enum PunctCat {
    Punct,
    Symbol,
}

fn unicode_category(c: char) -> Option<PunctCat> {
    let cp = c as u32;
    if cp < 128 {
        return None;
    }
    // General punctuation, CJK punctuation, dashes, quotes
    if (0x2000..=0x206F).contains(&cp)
        || (0x3000..=0x303F).contains(&cp)
        || (0xFF00..=0xFF0F).contains(&cp)
        || (0xFF1A..=0xFF20).contains(&cp)
        || (0xFF3B..=0xFF40).contains(&cp)
        || (0xFF5B..=0xFF65).contains(&cp)
        || matches!(cp, 0xA1 | 0xA7 | 0xAB | 0xB6 | 0xB7 | 0xBB | 0xBF)
    {
        return Some(PunctCat::Punct);
    }
    if (0x2190..=0x23FF).contains(&cp) || (0x2500..=0x27BF).contains(&cp) || (0x2900..=0x2BFF).contains(&cp)
        || (0x1F300..=0x1FAFF).contains(&cp) || matches!(cp, 0xA2..=0xA6 | 0xA8 | 0xA9 | 0xAC | 0xAE..=0xB1 | 0xB4 | 0xB8 | 0xD7 | 0xF7)
    {
        return Some(PunctCat::Symbol);
    }
    None
}

fn is_whitespace(c: char) -> bool {
    c.is_whitespace()
}

struct Delim {
    ch: char,
    count: usize,
    orig_count: usize,
    can_open: bool,
    can_close: bool,
    /// index into `nodes` of the text node holding the delimiter run
    node: usize,
    active: bool,
}

struct Bracket {
    node: usize, // index of text node "[" or "!["
    image: bool,
    active: bool,
    bracket_after: bool,
    delim_len: usize, // number of delimiters at time of push
    pos: usize,       // position after the bracket in source
}

pub struct InlineParser<'a> {
    src: &'a str,
    pos: usize,
    refmap: &'a HashMap<String, RefDef>,
    nodes: Vec<Inline>,
    delims: Vec<Delim>,
    brackets: Vec<Bracket>,
    footnotes_enabled: bool,
}

pub fn parse_inlines(src: &str, refmap: &HashMap<String, RefDef>) -> Vec<Inline> {
    let mut p = InlineParser {
        src,
        pos: 0,
        refmap,
        nodes: Vec::new(),
        delims: Vec::new(),
        brackets: Vec::new(),
        footnotes_enabled: true,
    };
    while p.pos < p.src.len() {
        p.parse_one();
    }
    p.process_emphasis(0);
    let nodes = std::mem::take(&mut p.nodes);
    postprocess(merge_text(nodes))
}

fn merge_text(nodes: Vec<Inline>) -> Vec<Inline> {
    let mut out: Vec<Inline> = Vec::new();
    for n in nodes {
        match n {
            Inline::Text(t) => {
                if let Some(Inline::Text(prev)) = out.last_mut() {
                    prev.push_str(&t);
                } else {
                    out.push(Inline::Text(t));
                }
            }
            Inline::Emph(c) => out.push(Inline::Emph(merge_text(c))),
            Inline::Strong(c) => out.push(Inline::Strong(merge_text(c))),
            Inline::Strike(c) => out.push(Inline::Strike(merge_text(c))),
            Inline::Link { url, title, children } => out.push(Inline::Link { url, title, children: merge_text(children) }),
            Inline::Image { url, title, children } => out.push(Inline::Image { url, title, children: merge_text(children) }),
            other => out.push(other),
        }
    }
    out
}

/// GFM autolink extension applied on text nodes (not inside links).
fn postprocess(nodes: Vec<Inline>) -> Vec<Inline> {
    let mut out = Vec::new();
    for n in nodes {
        match n {
            Inline::Text(t) => out.extend(super::autolink::autolink_text(&t)),
            Inline::Emph(c) => out.push(Inline::Emph(postprocess(c))),
            Inline::Strong(c) => out.push(Inline::Strong(postprocess(c))),
            Inline::Strike(c) => out.push(Inline::Strike(postprocess(c))),
            other => out.push(other),
        }
    }
    out
}

impl<'a> InlineParser<'a> {
    fn peek_char(&self) -> Option<char> {
        self.src[self.pos..].chars().next()
    }

    fn char_before(&self, pos: usize) -> Option<char> {
        self.src[..pos].chars().next_back()
    }

    fn push_text(&mut self, s: &str) -> usize {
        self.nodes.push(Inline::Text(s.to_string()));
        self.nodes.len() - 1
    }

    fn parse_one(&mut self) {
        let c = match self.peek_char() {
            Some(c) => c,
            None => return,
        };
        match c {
            '\n' | '\r' => self.handle_newline(),
            '`' => self.handle_backticks(),
            '\\' => self.handle_backslash(),
            '&' => self.handle_entity(),
            '<' => self.handle_pointy_brace(),
            '*' | '_' | '~' => self.handle_delim(c),
            '[' => {
                self.pos += 1;
                let node = self.push_text("[");
                self.brackets.push(Bracket { node, image: false, active: true, bracket_after: false, delim_len: self.delims.len(), pos: self.pos });
            }
            ']' => self.handle_close_bracket(),
            '!' => {
                if self.src[self.pos + 1..].starts_with('[') {
                    self.pos += 2;
                    let node = self.push_text("![");
                    self.brackets.push(Bracket { node, image: true, active: true, bracket_after: false, delim_len: self.delims.len(), pos: self.pos });
                } else {
                    self.pos += 1;
                    self.push_text("!");
                }
            }
            _ => {
                // regular text run up to next special char
                let start = self.pos;
                let mut end = start;
                for (i, ch) in self.src[start..].char_indices() {
                    if matches!(ch, '\n' | '\r' | '`' | '\\' | '&' | '<' | '*' | '_' | '~' | '[' | ']' | '!') {
                        end = start + i;
                        break;
                    }
                    end = start + i + ch.len_utf8();
                }
                if end == start {
                    end = start + c.len_utf8();
                }
                self.pos = end;
                self.push_text(&self.src[start..end]);
            }
        }
    }

    fn handle_newline(&mut self) {
        // check hard break: two or more spaces before newline, or backslash (handled elsewhere)
        let c = self.peek_char().unwrap();
        self.pos += 1;
        if c == '\r' && self.src[self.pos..].starts_with('\n') {
            self.pos += 1;
        }
        // strip trailing spaces of previous text node
        let mut hard = false;
        if let Some(Inline::Text(t)) = self.nodes.last_mut() {
            let trimmed_len = t.trim_end_matches(' ').len();
            if t.len() - trimmed_len >= 2 {
                hard = true;
            }
            t.truncate(trimmed_len);
            if t.is_empty() {
                self.nodes.pop();
            }
        }
        self.nodes.push(if hard { Inline::HardBreak } else { Inline::SoftBreak });
        // skip leading spaces on next line
        while self.src[self.pos..].starts_with(' ') {
            self.pos += 1;
        }
    }

    fn handle_backticks(&mut self) {
        let start = self.pos;
        let mut n = 0;
        while self.src[self.pos..].starts_with('`') {
            n += 1;
            self.pos += 1;
        }
        // find closing run of exactly n backticks
        let mut search = self.pos;
        loop {
            match self.src[search..].find('`') {
                None => {
                    // no closer: literal backticks
                    self.push_text(&self.src[start..start + n]);
                    self.pos = start + n;
                    return;
                }
                Some(off) => {
                    let run_start = search + off;
                    let mut run_end = run_start;
                    while self.src[run_end..].starts_with('`') {
                        run_end += 1;
                    }
                    if run_end - run_start == n {
                        let content = &self.src[self.pos..run_start];
                        let mut s = content.replace("\r\n", " ").replace(['\n', '\r'], " ");
                        if s.len() >= 2 && s.starts_with(' ') && s.ends_with(' ') && !s.chars().all(|c| c == ' ') {
                            s = s[1..s.len() - 1].to_string();
                        }
                        self.nodes.push(Inline::Code(s));
                        self.pos = run_end;
                        return;
                    }
                    search = run_end;
                }
            }
        }
    }

    fn handle_backslash(&mut self) {
        self.pos += 1;
        match self.peek_char() {
            Some(c) if c.is_ascii_punctuation() => {
                self.pos += c.len_utf8();
                self.push_text(&c.to_string());
            }
            Some('\n') | Some('\r') => {
                // hard line break
                if let Some(Inline::Text(t)) = self.nodes.last_mut() {
                    let l = t.trim_end_matches(' ').len();
                    t.truncate(l);
                    if t.is_empty() {
                        self.nodes.pop();
                    }
                }
                let c = self.peek_char().unwrap();
                self.pos += 1;
                if c == '\r' && self.src[self.pos..].starts_with('\n') {
                    self.pos += 1;
                }
                self.nodes.push(Inline::HardBreak);
                while self.src[self.pos..].starts_with(' ') {
                    self.pos += 1;
                }
            }
            _ => {
                self.push_text("\\");
            }
        }
    }

    fn handle_entity(&mut self) {
        match parse_entity(&self.src[self.pos..]) {
            Some((decoded, len)) => {
                self.pos += len;
                self.push_text(&decoded);
            }
            None => {
                self.pos += 1;
                self.push_text("&");
            }
        }
    }

    fn handle_pointy_brace(&mut self) {
        let rest = &self.src[self.pos..];
        // autolink: URI
        if let Some(len) = scan_autolink_uri(rest) {
            let url = &rest[1..len - 1];
            self.nodes.push(Inline::Link { url: url.to_string(), title: String::new(), children: vec![Inline::Text(url.to_string())] });
            self.pos += len;
            return;
        }
        if let Some(len) = scan_autolink_email(rest) {
            let addr = &rest[1..len - 1];
            self.nodes.push(Inline::Link { url: format!("mailto:{}", addr), title: String::new(), children: vec![Inline::Text(addr.to_string())] });
            self.pos += len;
            return;
        }
        if let Some(len) = scan_html_tag(rest.as_bytes()) {
            self.nodes.push(Inline::Html(rest[..len].to_string()));
            self.pos += len;
            return;
        }
        self.pos += 1;
        self.push_text("<");
    }

    fn handle_delim(&mut self, c: char) {
        let start = self.pos;
        let mut n = 0;
        while self.src[self.pos..].starts_with(c) {
            n += 1;
            self.pos += c.len_utf8();
        }
        let before = self.char_before(start).unwrap_or('\n');
        let after = self.peek_char().unwrap_or('\n');
        let left_flanking = !is_whitespace(after) && (!is_punct(after) || is_whitespace(before) || is_punct(before));
        let right_flanking = !is_whitespace(before) && (!is_punct(before) || is_whitespace(after) || is_punct(after));
        let (can_open, can_close) = match c {
            '_' => (
                left_flanking && (!right_flanking || is_punct(before)),
                right_flanking && (!left_flanking || is_punct(after)),
            ),
            '~' => {
                // comrak strikethrough: 1 or 2 tildes
                if n > 2 {
                    (false, false)
                } else {
                    (left_flanking, right_flanking)
                }
            }
            _ => (left_flanking, right_flanking),
        };
        let node = self.push_text(&self.src[start..self.pos]);
        if (can_open || can_close) && !(c == '~' && n > 2) {
            self.delims.push(Delim { ch: c, count: n, orig_count: n, can_open, can_close, node, active: true });
        }
    }

    fn handle_close_bracket(&mut self) {
        self.pos += 1;
        // find last active bracket
        let bidx = match self.brackets.len() {
            0 => {
                self.push_text("]");
                return;
            }
            n => n - 1,
        };
        if !self.brackets[bidx].active {
            self.brackets.pop();
            self.push_text("]");
            return;
        }
        let is_image = self.brackets[bidx].image;
        let open_node = self.brackets[bidx].node;
        let after_open = self.brackets[bidx].pos;
        let label_text = &self.src[after_open..self.pos - 1];

        // footnote reference?
        if self.footnotes_enabled && !is_image && label_text.starts_with('^') && label_text.len() > 1 && !label_text[1..].contains(|c: char| c.is_whitespace() || c == '[' || c == ']') {
            let label = label_text[1..].to_string();
            // remove nodes from open_node onwards
            self.nodes.truncate(open_node);
            self.delims.retain(|d| d.node < open_node);
            self.brackets.pop();
            self.nodes.push(Inline::FootnoteRef(label));
            return;
        }

        // Try inline link: (dest "title")
        let mut matched: Option<(String, String, usize)> = None; // url, title, new pos
        if self.src[self.pos..].starts_with('(') {
            if let Some((url, title, len)) = scan_inline_link(&self.src[self.pos..]) {
                matched = Some((url, title, self.pos + len));
            }
        }
        if matched.is_none() {
            // reference link: full [label][ref], collapsed [label][], shortcut [label]
            let mut ref_label: Option<String> = None;
            let mut consumed = 0;
            if self.src[self.pos..].starts_with('[') {
                if let Some((lbl, len)) = scan_link_label(&self.src[self.pos..]) {
                    if lbl.trim().is_empty() {
                        ref_label = Some(label_text.to_string());
                    } else {
                        ref_label = Some(lbl);
                    }
                    consumed = len;
                } else {
                    // "[" that isn't a label: shortcut
                    ref_label = Some(label_text.to_string());
                }
            } else {
                ref_label = Some(label_text.to_string());
            }
            if let Some(lbl) = ref_label {
                if !self.brackets[bidx].bracket_after || consumed > 0 {
                    let norm = normalize_label(&lbl);
                    if !norm.is_empty() {
                        if let Some(def) = self.refmap.get(&norm) {
                            matched = Some((def.url.clone(), def.title.clone(), self.pos + consumed));
                        }
                    }
                }
            }
        }

        match matched {
            Some((url, title, newpos)) => {
                self.pos = newpos;
                // children = nodes after open_node
                let children: Vec<Inline> = self.nodes.drain(open_node + 1..).collect();
                self.nodes.pop(); // remove the "[" text node
                // process emphasis within children
                let delim_len = self.brackets[bidx].delim_len;
                let mut sub = InlineParser {
                    src: self.src,
                    pos: 0,
                    refmap: self.refmap,
                    nodes: children,
                    delims: self.delims.drain(delim_len..).map(|mut d| { d.node -= open_node + 1; d }).collect(),
                    brackets: Vec::new(),
                    footnotes_enabled: self.footnotes_enabled,
                };
                sub.process_emphasis(0);
                let children = sub.nodes;
                self.brackets.pop();
                if is_image {
                    self.nodes.push(Inline::Image { url, title, children });
                } else {
                    self.nodes.push(Inline::Link { url, title, children });
                    // deactivate earlier non-image brackets
                    for b in &mut self.brackets {
                        if !b.image {
                            b.active = false;
                        }
                    }
                }
            }
            None => {
                self.brackets.pop();
                if let Some(b) = self.brackets.last_mut() {
                    b.bracket_after = true;
                }
                self.push_text("]");
            }
        }
    }

    fn process_emphasis(&mut self, stack_bottom: usize) {
        // openers_bottom per delimiter type
        let mut openers_bottom: HashMap<(char, usize, bool), usize> = HashMap::new();
        let mut closer_idx = stack_bottom;
        while closer_idx < self.delims.len() {
            let d = &self.delims[closer_idx];
            if !d.can_close || !d.active || d.count == 0 {
                closer_idx += 1;
                continue;
            }
            let ch = d.ch;
            let key = (ch, d.orig_count % 3, d.can_open);
            let bottom = *openers_bottom.get(&key).unwrap_or(&stack_bottom);
            // look back for opener
            let mut opener_idx: Option<usize> = None;
            let mut j = closer_idx;
            while j > bottom {
                j -= 1;
                let o = &self.delims[j];
                if o.ch == ch && o.can_open && o.active && o.count > 0 {
                    // rule of 3
                    let closer = &self.delims[closer_idx];
                    let odd_match = (closer.can_open || o.can_close) && closer.orig_count % 3 != 0 && (o.orig_count + closer.orig_count) % 3 == 0;
                    if !odd_match {
                        if ch == '~' && o.count != closer.count {
                            continue;
                        }
                        opener_idx = Some(j);
                        break;
                    }
                }
            }
            match opener_idx {
                Some(oi) => {
                    let use_delims = if ch == '~' {
                        self.delims[oi].count
                    } else if self.delims[closer_idx].count >= 2 && self.delims[oi].count >= 2 {
                        2
                    } else {
                        1
                    };
                    let onode = self.delims[oi].node;
                    let cnode = self.delims[closer_idx].node;
                    // remove delims from text nodes
                    if let Inline::Text(t) = &mut self.nodes[onode] {
                        let l = t.len() - use_delims * ch.len_utf8();
                        t.truncate(l);
                    }
                    if let Inline::Text(t) = &mut self.nodes[cnode] {
                        let l = t.len() - use_delims * ch.len_utf8();
                        t.truncate(l);
                    }
                    self.delims[oi].count -= use_delims;
                    self.delims[closer_idx].count -= use_delims;
                    // wrap nodes between onode and cnode
                    let inner: Vec<Inline> = self.nodes.drain(onode + 1..cnode).collect();
                    let wrapped = match ch {
                        '~' => Inline::Strike(inner),
                        _ => {
                            if use_delims == 2 {
                                Inline::Strong(inner)
                            } else {
                                Inline::Emph(inner)
                            }
                        }
                    };
                    self.nodes.insert(onode + 1, wrapped);
                    // adjust node indices: nodes between were removed (cnode - onode - 1 nodes) and one inserted
                    let removed = (cnode - onode - 1) as isize - 1;
                    for d in self.delims.iter_mut() {
                        if d.node > onode && d.node < cnode {
                            d.active = false;
                        } else if d.node >= cnode {
                            d.node = (d.node as isize - removed) as usize;
                        }
                    }
                    for b in self.brackets.iter_mut() {
                        if b.node > onode && b.node < cnode {
                            b.active = false;
                        } else if b.node >= cnode {
                            b.node = (b.node as isize - removed) as usize;
                        }
                    }
                    // deactivate delimiters between
                    for k in oi + 1..closer_idx {
                        self.delims[k].active = false;
                    }
                    if self.delims[oi].count == 0 {
                        self.delims[oi].active = false;
                    }
                    if self.delims[closer_idx].count == 0 {
                        self.delims[closer_idx].active = false;
                        closer_idx += 1;
                    }
                }
                None => {
                    openers_bottom.insert(key, closer_idx);
                    if !self.delims[closer_idx].can_open {
                        self.delims[closer_idx].active = false;
                    }
                    closer_idx += 1;
                }
            }
        }
        // remove empty text nodes
        let mut i = 0;
        while i < self.nodes.len() {
            if let Inline::Text(t) = &self.nodes[i] {
                if t.is_empty() {
                    self.nodes.remove(i);
                    for d in self.delims.iter_mut() {
                        if d.node > i {
                            d.node -= 1;
                        }
                    }
                    for b in self.brackets.iter_mut() {
                        if b.node > i {
                            b.node -= 1;
                        }
                    }
                    continue;
                }
            }
            i += 1;
        }
        self.delims.truncate(stack_bottom);
    }
}

pub fn normalize_label(s: &str) -> String {
    let collapsed: Vec<&str> = s.split_whitespace().collect();
    collapsed.join(" ").to_lowercase()
}

/// Scan a link label `[...]` at the start of `s`; returns (label content, consumed length).
pub fn scan_link_label(s: &str) -> Option<(String, usize)> {
    if !s.starts_with('[') {
        return None;
    }
    let mut i = 1;
    let bytes = s.as_bytes();
    let mut len = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => {
                i += 2;
                len += 2;
                continue;
            }
            b'[' => return None,
            b']' => {
                let label = &s[1..i.min(s.len())];
                return Some((label.to_string(), i + 1));
            }
            _ => {}
        }
        i += 1;
        len += 1;
        if len > 999 {
            return None;
        }
    }
    None
}

fn scan_link_destination(s: &str) -> Option<(String, usize)> {
    if s.starts_with('<') {
        let mut i = 1;
        let b = s.as_bytes();
        while i < b.len() {
            match b[i] {
                b'\\' if i + 1 < b.len() => i += 2,
                b'>' => return Some((unescape(&s[1..i]), i + 1)),
                b'<' | b'\n' => return None,
                _ => i += 1,
            }
        }
        return None;
    }
    let mut depth = 0i32;
    let mut i = 0;
    let b = s.as_bytes();
    while i < b.len() {
        let c = b[i];
        if c == b'\\' && i + 1 < b.len() && b[i + 1].is_ascii_punctuation() {
            i += 2;
            continue;
        }
        if c == b'(' {
            depth += 1;
            if depth > 32 {
                return None;
            }
        } else if c == b')' {
            if depth == 0 {
                break;
            }
            depth -= 1;
        } else if c <= 0x20 {
            break;
        }
        i += 1;
    }
    if depth != 0 {
        return None;
    }
    Some((unescape(&s[..i]), i))
}

fn scan_link_title(s: &str) -> Option<(String, usize)> {
    let open = s.chars().next()?;
    let close = match open {
        '"' => '"',
        '\'' => '\'',
        '(' => ')',
        _ => return None,
    };
    let b = s.as_bytes();
    let mut i = 1;
    while i < b.len() {
        let c = b[i];
        if c == b'\\' && i + 1 < b.len() && b[i + 1].is_ascii_punctuation() {
            i += 2;
            continue;
        }
        if c == close as u8 {
            return Some((unescape(&s[1..i]), i + 1));
        }
        if open == '(' && c == b'(' {
            return None;
        }
        i += 1;
    }
    None
}

fn skip_spaces(s: &str, mut i: usize) -> usize {
    while i < s.len() && matches!(s.as_bytes()[i], b' ' | b'\t' | b'\n' | b'\r') {
        i += 1;
    }
    i
}

/// Scan `(dest "title")` returning (url, title, consumed)
fn scan_inline_link(s: &str) -> Option<(String, String, usize)> {
    if !s.starts_with('(') {
        return None;
    }
    let mut i = skip_spaces(s, 1);
    let (url, dlen) = if s[i..].starts_with(')') {
        (String::new(), 0)
    } else {
        scan_link_destination(&s[i..])?
    };
    i += dlen;
    let after_dest = i;
    i = skip_spaces(s, i);
    let mut title = String::new();
    if i < s.len() && i > after_dest {
        if let Some((t, tlen)) = scan_link_title(&s[i..]) {
            title = t;
            i += tlen;
            i = skip_spaces(s, i);
        }
    }
    if s[i..].starts_with(')') {
        Some((clean_url(&url), title, i + 1))
    } else {
        None
    }
}

pub fn clean_url(url: &str) -> String {
    url.trim().to_string()
}

pub fn unescape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&n) = chars.peek() {
                if n.is_ascii_punctuation() {
                    out.push(n);
                    chars.next();
                    continue;
                }
            }
            out.push(c);
        } else if c == '&' {
            let rest: String = std::iter::once(c).chain(chars.clone()).collect();
            if let Some((decoded, len)) = parse_entity(&rest) {
                out.push_str(&decoded);
                for _ in 0..len - 1 {
                    chars.next();
                }
            } else {
                out.push(c);
            }
        } else {
            out.push(c);
        }
    }
    out
}

pub fn unescape_info(s: &str) -> String {
    unescape(s)
}

/// Parse a link reference definition at the start of `content`. Returns bytes consumed.
pub fn parse_reference_definition(content: &str, refmap: &mut HashMap<String, RefDef>) -> Option<usize> {
    let (label, mut i) = scan_link_label(content)?;
    if label.trim().is_empty() {
        return None;
    }
    if !content[i..].starts_with(':') {
        return None;
    }
    i += 1;
    i = skip_spaces(content, i);
    let (url, dlen) = scan_link_destination(&content[i..])?;
    if dlen == 0 && !content[i..].starts_with('<') {
        return None;
    }
    i += dlen;
    let before_title = i;
    // optional title (may be on next line)
    let mut j = i;
    while j < content.len() && matches!(content.as_bytes()[j], b' ' | b'\t') {
        j += 1;
    }
    let mut newline_seen = false;
    if j < content.len() && matches!(content.as_bytes()[j], b'\n' | b'\r') {
        newline_seen = true;
        j += 1;
        if content[j..].starts_with('\n') {
            j += 1;
        }
        while j < content.len() && matches!(content.as_bytes()[j], b' ' | b'\t') {
            j += 1;
        }
    }
    let mut title = String::new();
    let mut end;
    if j > i {
        if let Some((t, tlen)) = scan_link_title(&content[j..]) {
            // title must be followed by end of line
            let mut k = j + tlen;
            while k < content.len() && matches!(content.as_bytes()[k], b' ' | b'\t') {
                k += 1;
            }
            if k >= content.len() || matches!(content.as_bytes()[k], b'\n' | b'\r') {
                title = t;
                end = k;
                if end < content.len() {
                    end += 1;
                    if content[end..].starts_with('\n') && content.as_bytes()[end - 1] == b'\r' {
                        end += 1;
                    }
                }
                let norm = normalize_label(&label);
                refmap.entry(norm).or_insert(RefDef { url: clean_url(&url), title });
                return Some(end);
            }
        }
    }
    // no title: destination must be followed by end of line
    let mut k = before_title;
    while k < content.len() && matches!(content.as_bytes()[k], b' ' | b'\t') {
        k += 1;
    }
    if k < content.len() && !matches!(content.as_bytes()[k], b'\n' | b'\r') {
        return None;
    }
    let _ = newline_seen;
    end = k;
    if end < content.len() {
        end += 1;
        if end < content.len() && content.as_bytes()[end - 1] == b'\r' && content[end..].starts_with('\n') {
            end += 1;
        }
    }
    let _ = &mut title;
    let norm = normalize_label(&label);
    refmap.entry(norm).or_insert(RefDef { url: clean_url(&url), title: String::new() });
    Some(end)
}

fn scan_autolink_uri(s: &str) -> Option<usize> {
    // <scheme:...>
    let b = s.as_bytes();
    if b.first() != Some(&b'<') {
        return None;
    }
    let mut i = 1;
    if i >= b.len() || !b[i].is_ascii_alphabetic() {
        return None;
    }
    i += 1;
    while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'+' || b[i] == b'.' || b[i] == b'-') {
        i += 1;
    }
    let scheme_len = i - 1;
    if !(2..=32).contains(&scheme_len) || b.get(i) != Some(&b':') {
        return None;
    }
    i += 1;
    while i < b.len() {
        let c = b[i];
        if c == b'>' {
            return Some(i + 1);
        }
        if c <= 0x20 || c == b'<' {
            return None;
        }
        i += 1;
    }
    None
}

fn scan_autolink_email(s: &str) -> Option<usize> {
    let b = s.as_bytes();
    if b.first() != Some(&b'<') {
        return None;
    }
    let mut i = 1;
    let start = i;
    while i < b.len() && (b[i].is_ascii_alphanumeric() || b".!#$%&'*+/=?^_`{|}~-".contains(&b[i])) {
        i += 1;
    }
    if i == start || b.get(i) != Some(&b'@') {
        return None;
    }
    i += 1;
    // domain labels
    loop {
        let ls = i;
        while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'-') {
            i += 1;
        }
        if i == ls || i - ls > 63 || b[i - 1] == b'-' {
            return None;
        }
        match b.get(i) {
            Some(b'.') => i += 1,
            Some(b'>') => return Some(i + 1),
            _ => return None,
        }
    }
}

/// Scan an HTML tag (open, close, comment, PI, declaration, CDATA) at the start. Returns length.
pub fn scan_html_tag(s: &[u8]) -> Option<usize> {
    if s.first() != Some(&b'<') {
        return None;
    }
    let n = s.len();
    if n < 3 {
        return None;
    }
    // comment
    if s.starts_with(b"<!--") {
        let mut i = 4;
        if s[i..].starts_with(b">") || s[i..].starts_with(b"->") {
            return None;
        }
        while i + 2 < n {
            if s[i] == b'-' && s[i + 1] == b'-' {
                if s[i + 2] == b'>' {
                    return Some(i + 3);
                }
                return None;
            }
            i += 1;
        }
        return None;
    }
    if s.starts_with(b"<?") {
        let mut i = 2;
        while i + 1 < n {
            if s[i] == b'?' && s[i + 1] == b'>' {
                return Some(i + 2);
            }
            i += 1;
        }
        return None;
    }
    if s.starts_with(b"<![CDATA[") {
        let mut i = 9;
        while i + 2 < n {
            if s[i] == b']' && s[i + 1] == b']' && s[i + 2] == b'>' {
                return Some(i + 3);
            }
            i += 1;
        }
        return None;
    }
    if s[1] == b'!' && n > 2 && s[2].is_ascii_alphabetic() {
        let mut i = 2;
        while i < n && s[i] != b'>' {
            i += 1;
        }
        if i < n {
            return Some(i + 1);
        }
        return None;
    }
    // closing tag
    if s[1] == b'/' {
        let mut i = 2;
        if i >= n || !s[i].is_ascii_alphabetic() {
            return None;
        }
        while i < n && (s[i].is_ascii_alphanumeric() || s[i] == b'-') {
            i += 1;
        }
        while i < n && matches!(s[i], b' ' | b'\t' | b'\n' | b'\r') {
            i += 1;
        }
        if i < n && s[i] == b'>' {
            return Some(i + 1);
        }
        return None;
    }
    // open tag
    let mut i = 1;
    if !s[i].is_ascii_alphabetic() {
        return None;
    }
    while i < n && (s[i].is_ascii_alphanumeric() || s[i] == b'-') {
        i += 1;
    }
    loop {
        // attributes
        let mut ws = 0;
        while i < n && matches!(s[i], b' ' | b'\t' | b'\n' | b'\r') {
            i += 1;
            ws += 1;
        }
        if i >= n {
            return None;
        }
        if s[i] == b'>' {
            return Some(i + 1);
        }
        if s[i] == b'/' {
            if i + 1 < n && s[i + 1] == b'>' {
                return Some(i + 2);
            }
            return None;
        }
        if ws == 0 {
            return None;
        }
        // attribute name
        if !(s[i].is_ascii_alphabetic() || s[i] == b'_' || s[i] == b':') {
            return None;
        }
        while i < n && (s[i].is_ascii_alphanumeric() || matches!(s[i], b'_' | b':' | b'.' | b'-')) {
            i += 1;
        }
        // optional value
        let mut j = i;
        while j < n && matches!(s[j], b' ' | b'\t' | b'\n' | b'\r') {
            j += 1;
        }
        if j < n && s[j] == b'=' {
            j += 1;
            while j < n && matches!(s[j], b' ' | b'\t' | b'\n' | b'\r') {
                j += 1;
            }
            if j >= n {
                return None;
            }
            if s[j] == b'"' || s[j] == b'\'' {
                let q = s[j];
                j += 1;
                while j < n && s[j] != q {
                    j += 1;
                }
                if j >= n {
                    return None;
                }
                j += 1;
            } else {
                let vs = j;
                while j < n && !matches!(s[j], b' ' | b'\t' | b'\n' | b'\r' | b'"' | b'\'' | b'=' | b'<' | b'>' | b'`') {
                    j += 1;
                }
                if j == vs {
                    return None;
                }
            }
            i = j;
        }
    }
}
