fn autolink_delim(s: &str) -> usize {
    // trim trailing punctuation, handle parens, entities. Returns new length.
    let mut link_end = s.len();
    let bytes = s.as_bytes();
    // stop at '<'
    if let Some(p) = s.find('<') {
        link_end = p;
    }
    loop {
        if link_end == 0 {
            break;
        }
        let c = bytes[link_end - 1];
        match c {
            b'?' | b'!' | b'.' | b',' | b':' | b'*' | b'_' | b'~' | b'\'' | b'"' => {
                link_end -= 1;
            }
            b')' => {
                let mut opening = 0;
                let mut closing = 0;
                for &b in &bytes[..link_end] {
                    if b == b'(' {
                        opening += 1;
                    } else if b == b')' {
                        closing += 1;
                    }
                }
                if closing <= opening {
                    break;
                }
                link_end -= 1;
            }
            b';' => {
                // possible entity
                let mut new_end = link_end - 1;
                while new_end > 0 && bytes[new_end - 1].is_ascii_alphanumeric() {
                    new_end -= 1;
                }
                if new_end > 0 && bytes[new_end - 1] == b'&' && new_end < link_end - 1 {
                    link_end = new_end - 1;
                } else {
                    break;
                }
            }
            _ => break,
        }
    }
    link_end
}

fn www_match(text: &str, pos: usize) -> Option<(usize, usize, String)> {
    // returns (start, end, url)
    if pos > 0 {
        let prev = text[..pos].chars().next_back().unwrap();
        if !(prev.is_whitespace() || matches!(prev, '*' | '_' | '~' | '(')) {
            return None;
        }
    }
    let rest = &text[pos..];
    if !rest.starts_with("www.") {
        return None;
    }
    let domain_len = check_domain(rest, false)?;
    let mut link_end = domain_len;
    let rb = rest.as_bytes();
    while link_end < rb.len() && !(rb[link_end] as char).is_whitespace() && rb[link_end] != b'<' {
        link_end += 1;
    }
    // ensure char boundary
    while !rest.is_char_boundary(link_end) {
        link_end += 1;
    }
    let link_end = autolink_delim(&rest[..link_end]);
    let url = format!("http://{}", &rest[..link_end]);
    Some((pos, pos + link_end, url))
}

fn url_match(text: &str, pos: usize) -> Option<(usize, usize, String)> {
    // pos points at ':' of "://"
    let rest = &text[pos..];
    if !rest.starts_with("://") {
        return None;
    }
    let before = &text[..pos];
    let scheme_start = before
        .char_indices()
        .rev()
        .take_while(|(_, c)| c.is_ascii_alphabetic())
        .last()
        .map(|(i, _)| i)
        .unwrap_or(pos);
    let scheme = &before[scheme_start..];
    if !["http", "https", "ftp"].contains(&scheme.to_ascii_lowercase().as_str()) {
        return None;
    }
    if scheme_start > 0 {
        let prev = text[..scheme_start].chars().next_back().unwrap();
        if prev.is_alphanumeric() {
            return None;
        }
    }
    let after = &text[pos + 3..];
    let domain_len = check_domain(after, true)?;
    let _ = domain_len;
    let ab = after.as_bytes();
    let mut link_end = 0;
    while link_end < ab.len() && !(ab[link_end] as char).is_whitespace() && ab[link_end] != b'<' {
        link_end += 1;
    }
    while !after.is_char_boundary(link_end) {
        link_end += 1;
    }
    let link_end = autolink_delim(&after[..link_end]);
    if link_end == 0 {
        return None;
    }
    let end = pos + 3 + link_end;
    let url = text[scheme_start..end].to_string();
    Some((scheme_start, end, url))
}

fn email_match(text: &str, pos: usize) -> Option<(usize, usize, String)> {
    // pos points at '@'
    let before = &text[..pos];
    let mut start = pos;
    for (i, c) in before.char_indices().rev() {
        if c.is_ascii_alphanumeric() || matches!(c, '.' | '+' | '-' | '_') {
            start = i;
        } else {
            break;
        }
    }
    if start == pos {
        return None;
    }
    let after = &text[pos + 1..];
    let ab = after.as_bytes();
    let mut i = 0;
    let mut np = 0;
    while i < ab.len() {
        let c = ab[i];
        if c.is_ascii_alphanumeric() || c == b'-' || c == b'_' {
            i += 1;
        } else if c == b'.' && i > 0 && i + 1 < ab.len() && (ab[i + 1].is_ascii_alphanumeric()) {
            np += 1;
            i += 1;
        } else {
            break;
        }
    }
    if np == 0 || i == 0 {
        return None;
    }
    // last char must not be - or _
    while i > 0 && (ab[i - 1] == b'-' || ab[i - 1] == b'_') {
        return None;
    }
    let end = pos + 1 + i;
    let addr = &text[start..end];
    Some((start, end, format!("mailto:{}", addr)))
}

pub fn autolink_text(text: &str) -> Vec<Inline> {
    let mut out = Vec::new();
    let mut cur = 0;
    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        let m = match c {
            b'w' => www_match(text, i),
            b':' => url_match(text, i),
            b'@' => email_match(text, i),
            _ => None,
        };
        match m {
            Some((start, end, url)) if start >= cur => {
                if start > cur {
                    out.push(Inline::Text(text[cur..start].to_string()));
                }
                out.push(Inline::Link { url, title: String::new(), children: vec![Inline::Text(text[start..end].to_string())] });
                cur = end;
                i = end;
            }
            _ => {
                i += 1;
                while i < bytes.len() && !text.is_char_boundary(i) {
                    i += 1;
                }
            }
        }
    }
    if cur < text.len() {
        out.push(Inline::Text(text[cur..].to_string()));
    }
    out
}
