                b'&' => out.push_str("&amp;"),
                b'\'' => out.push_str("&#x27;"),
                _ => out.push(b as char),
            }
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
}

impl<'a> Renderer<'a> {
    pub fn new(parser: &'a Parser, theme: SyntaxTheme) -> Renderer<'a> {
        let mut r = Renderer {
            parser,
            out: String::new(),
            theme,
            footnote_ix: HashMap::new(),
            footnote_order: Vec::new(),
            footnote_defs: HashMap::new(),
        };
        // collect footnote definitions
        for (i, n) in parser.nodes.iter().enumerate() {
            if let Kind::FootnoteDefinition { label } = &n.kind {
                r.footnote_defs.entry(label.clone()).or_insert(i);
            }
        }
        r
    }

    fn cr(&mut self) {
        if !self.out.is_empty() && !self.out.ends_with('\n') {
            self.out.push('\n');
        }
    }

    pub fn render_document(&mut self) {
        let root = self.parser.root;
        self.render_children(root, false);
        // footnotes section
        if !self.footnote_order.is_empty() {
            self.cr();
            self.out.push_str("<section class=\"footnotes\" data-footnotes>\n<ol>\n");
            let order = self.footnote_order.clone();
            for (i, label) in order.iter().enumerate() {
                let def = self.footnote_defs[label];
                self.out.push_str(&format!("<li id=\"fn-{}\">\n", i + 1));
                // render children; append backref to the last paragraph
                let children = self.parser.nodes[def].children.clone();
                let n = children.len();
                for (ci, &child) in children.iter().enumerate() {
                    let last = ci + 1 == n;
                    if last && matches!(self.parser.nodes[child].kind, Kind::Paragraph) {
                        self.out.push_str("<p>");
                        self.render_inlines_of(child);
                        self.out.push_str(&format!(" <a href=\"#fnref-{}\" class=\"footnote-backref\">↩</a></p>\n", i + 1));
                    } else {
                        self.render_block(child, false);
                        if last {
                            self.out.push_str(&format!("<a href=\"#fnref-{}\" class=\"footnote-backref\">↩</a>\n", i + 1));
                        }
                    }
                }
                self.out.push_str("</li>\n");
            }
            self.out.push_str("</ol>\n</section>\n");
        }
    }

    fn render_children(&mut self, idx: usize, tight: bool) {
        let children = self.parser.nodes[idx].children.clone();
        for c in children {
            self.render_block(c, tight);
        }
    }

    fn render_inlines_of(&mut self, idx: usize) {
        let content = &self.parser.nodes[idx].content;
        let text = content.trim_end_matches(['\n', '\r']);
        let inlines = parse_inlines(text, &self.parser.refmap);
        self.render_inlines(&inlines);
    }

    fn render_block(&mut self, idx: usize, tight: bool) {
        let node = &self.parser.nodes[idx];
        match node.kind.clone() {
            Kind::Document => self.render_children(idx, false),
            Kind::BlockQuote => {
                self.cr();
                self.out.push_str("<blockquote>\n");
                self.render_children(idx, false);
                self.cr();
                self.out.push_str("</blockquote>\n");
            }
            Kind::List(data) => {
                self.cr();
                if data.ordered {
                    if data.start == 1 {
                        self.out.push_str("<ol>\n");
                    } else {
                        self.out.push_str(&format!("<ol start=\"{}\">\n", data.start));
                    }
                } else {
                    self.out.push_str("<ul>\n");
                }
                self.render_children(idx, data.tight);
                self.cr();
                if data.ordered {
                    self.out.push_str("</ol>\n");
                } else {
                    self.out.push_str("</ul>\n");
                }
            }
            Kind::Item(_) => {
                self.cr();
                self.out.push_str("<li>");
                if let Some(checked) = node.task {
                    if checked {
                        self.out.push_str("<input type=\"checkbox\" checked=\"\" disabled=\"\" /> ");
                    } else {
                        self.out.push_str("<input type=\"checkbox\" disabled=\"\" /> ");
                    }
                }
                self.render_children(idx, tight);
                self.out.push_str("</li>\n");
            }
            Kind::Paragraph => {
                if tight {
                    self.render_inlines_of(idx);
                } else {
                    self.cr();
                    self.out.push_str("<p>");
                    self.render_inlines_of(idx);
                    self.out.push_str("</p>\n");
                }
            }
            Kind::Heading { level, .. } => {
                self.cr();
                self.out.push_str(&format!("<h{}>", level));
                self.render_inlines_of(idx);
                self.out.push_str(&format!("</h{}>\n", level));
            }
            Kind::ThematicBreak => {
                self.cr();
                self.out.push_str("<hr />\n");
            }
            Kind::CodeBlock { info, .. } => {
                self.cr();
                let lang = info.split_whitespace().next().filter(|s| !s.is_empty());
                let html = crate::highlight::highlight_html(&node.content, lang, self.theme);
                self.out.push_str(&html);
                self.out.push('\n');
            }
            Kind::HtmlBlock { .. } => {
                self.cr();
                self.out.push_str(&node.content);
                self.cr();
            }
            Kind::Table { alignments } => {
                self.cr();
                self.out.push_str("<table>\n");
                let rows = node.children.clone();
                let mut in_body = false;
                for (ri, row) in rows.iter().enumerate() {
                    let header = ri == 0;
                    if header {
                        self.out.push_str("<thead>\n");
                    } else if !in_body {
                        self.out.push_str("<tbody>\n");
                        in_body = true;
                    }
                    self.out.push_str("<tr>\n");
                    let cells = self.parser.nodes[*row].children.clone();
                    for (ci, cell) in cells.iter().enumerate() {
                        let tag = if header { "th" } else { "td" };
                        let align = alignments.get(ci).copied().unwrap_or(Align::None);
                        match align {
                            Align::None => self.out.push_str(&format!("<{}>", tag)),
                            Align::Left => self.out.push_str(&format!("<{} align=\"left\">", tag)),
                            Align::Center => self.out.push_str(&format!("<{} align=\"center\">", tag)),
                            Align::Right => self.out.push_str(&format!("<{} align=\"right\">", tag)),
                        }
                        self.render_inlines_of(*cell);
                        self.out.push_str(&format!("</{}>\n", tag));
                    }
                    self.out.push_str("</tr>\n");
                    if header {
                        self.out.push_str("</thead>\n");
                    }
                }
                if in_body {
                    self.out.push_str("</tbody>\n");
                }
                self.out.push_str("</table>\n");
            }
            Kind::TableRow { .. } | Kind::TableCell => {}
            Kind::FootnoteDefinition { .. } => {
                // rendered at the end
            }
        }
    }

    pub fn render_inlines(&mut self, inlines: &[Inline]) {
        for inl in inlines {
            match inl {
                Inline::Text(t) => escape_html(t, &mut self.out),
                Inline::Code(c) => {
                    self.out.push_str("<code>");
                    escape_html(c, &mut self.out);
                    self.out.push_str("</code>");
                }
                Inline::Emph(c) => {
                    self.out.push_str("<em>");
                    self.render_inlines(c);
                    self.out.push_str("</em>");
                }
                Inline::Strong(c) => {
                    self.out.push_str("<strong>");
                    self.render_inlines(c);
                    self.out.push_str("</strong>");
                }
                Inline::Strike(c) => {
                    self.out.push_str("<del>");
                    self.render_inlines(c);
                    self.out.push_str("</del>");
                }
                Inline::Link { url, title, children } => {
                    self.out.push_str("<a href=\"");
                    escape_href(url, &mut self.out);
                    self.out.push('"');
                    if !title.is_empty() {
                        self.out.push_str(" title=\"");
                        escape_html(title, &mut self.out);
                        self.out.push('"');
                    }
                    self.out.push('>');
                    self.render_inlines(children);
                    self.out.push_str("</a>");
                }
                Inline::Image { url, title, children } => {
                    self.out.push_str("<img src=\"");
                    escape_href(url, &mut self.out);
                    self.out.push_str("\" alt=\"");
                    let mut alt = String::new();
                    collect_text(children, &mut alt);
                    escape_html(&alt, &mut self.out);
                    self.out.push('"');
                    if !title.is_empty() {
                        self.out.push_str(" title=\"");
                        escape_html(title, &mut self.out);
                        self.out.push('"');
                    }
                    self.out.push_str(" />");
                }
                Inline::Html(h) => self.out.push_str(h),
                Inline::SoftBreak => self.out.push('\n'),
                Inline::HardBreak => self.out.push_str("<br />\n"),
                Inline::FootnoteRef(label) => {
                    if self.footnote_defs.contains_key(label) {
                        let ix = match self.footnote_ix.get(label) {
                            Some(&i) => i,
                            None => {
                                self.footnote_order.push(label.clone());
                                let i = self.footnote_order.len();
                                self.footnote_ix.insert(label.clone(), i);
                                i
                            }
                        };
                        self.out.push_str(&format!(
                            "<sup class=\"footnote-ref\"><a href=\"#fn-{}\" id=\"fnref-{}\">{}</a></sup>",
                            ix, ix, ix
                        ));
                    } else {
                        self.out.push_str("[^");
                        escape_html(label, &mut self.out);
                        self.out.push(']');
                    }
                }
            }
        }
    }
}

pub fn collect_text(inlines: &[Inline], out: &mut String) {
    for i in inlines {
        match i {
            Inline::Text(t) | Inline::Code(t) => out.push_str(t),
            Inline::Emph(c) | Inline::Strong(c) | Inline::Strike(c) => collect_text(c, out),
            Inline::Link { children, .. } | Inline::Image { children, .. } => collect_text(children, out),
            Inline::SoftBreak | Inline::HardBreak => out.push('\n'),
            Inline::Html(_) => {}
            Inline::FootnoteRef(l) => {
                out.push_str("[^");
                out.push_str(l);
                out.push(']');
            }
        }
    }
}
