//! Markdown → sanitized HTML, mimicking comrak + ammonia.

pub mod autolink;
pub mod block;
pub mod entities;
pub mod inline;
pub mod render;
pub mod table;

use crate::config::SyntaxTheme;

pub fn to_html_unsanitized(md: &str, theme: SyntaxTheme) -> String {
    let mut parser = block::Parser::new();
    parser.parse(md);
    // task list items: detect "[ ] " / "[x] " at the start of the first paragraph of list items
    let n = parser.nodes.len();
    for i in 0..n {
        if let block::Kind::Item(_) = parser.nodes[i].kind {
            if let Some(&first) = parser.nodes[i].children.first() {
                if let block::Kind::Paragraph = parser.nodes[first].kind {
                    let content = parser.nodes[first].content.clone();
                    let (checked, rest) = if let Some(r) = content.strip_prefix("[ ] ") {
                        (Some(false), r)
                    } else if let Some(r) = content.strip_prefix("[x] ").or_else(|| content.strip_prefix("[X] ")) {
                        (Some(true), r)
                    } else {
                        (None, "")
                    };
                    if let Some(c) = checked {
                        parser.nodes[i].task = Some(c);
                        parser.nodes[first].content = rest.to_string();
                    }
                }
            }
        }
    }
    let mut r = render::Renderer::new(&parser, theme);
    r.render_document();
    r.out
}

pub fn to_html(md: &str, theme: SyntaxTheme) -> String {
    let html = to_html_unsanitized(md, theme);
    crate::sanitize::sanitize(&html)
}
