// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

#[derive(Debug)]
enum Token {
    Start { name: String, attrs: Vec<(String, String)>, self_closing: bool },
    End(String),
    Text(String),
    Comment,
}

struct Tokenizer<'a> {
    s: &'a str,
    pos: usize,
}

fn decode_entities(s: &str, in_attr: bool) -> String {
    if !s.contains('&') {
        return s.to_string();
    }
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if s.as_bytes()[i] == b'&' {
            if let Some((decoded, len)) = crate::markdown::entities::parse_entity(&s[i..]) {
                out.push_str(&decoded);
                i += len;
                continue;
            }
            // HTML allows some entities without ';' – handle a few common ones
            let rest = &s[i + 1..];
            let mut matched = false;
            for (name, val) in [("amp", "&"), ("lt", "<"), ("gt", ">"), ("quot", "\""), ("nbsp", "\u{a0}"), ("copy", "©"), ("reg", "®")] {
                if rest.starts_with(name) {
                    let after = rest[name.len()..].chars().next();
                    if in_attr && matches!(after, Some(c) if c.is_ascii_alphanumeric() || c == '=') {
                        continue;
                    }
                    out.push_str(val);
                    i += 1 + name.len();
                    matched = true;
                    break;
                }
            }
            if matched {
                continue;
            }
            out.push('&');
            i += 1;
        } else {
            let c = s[i..].chars().next().unwrap();
            out.push(c);
            i += c.len_utf8();
        }
    }
    out
}

impl<'a> Tokenizer<'a> {
    fn tokens(mut self) -> Vec<Token> {
        let mut toks = Vec::new();
        let mut text = String::new();
        while self.pos < self.s.len() {
            let rest = &self.s[self.pos..];
            if rest.starts_with('<') {
                if let Some(tok) = self.try_tag() {
                    if !text.is_empty() {
                        toks.push(Token::Text(decode_entities(&text, false)));
                        text.clear();
                    }
                    // raw text elements
                    if let Token::Start { name, .. } = &tok {
                        if matches!(name.as_str(), "script" | "style" | "textarea" | "title" | "xmp" | "iframe" | "noembed" | "noframes" | "plaintext") {
                            let close = format!("</{}", name);
                            let lower = self.s[self.pos..].to_ascii_lowercase();
                            let end = lower.find(&close);
                            let nm = name.clone();
                            toks.push(tok);
                            match end {
                                Some(e) => {
                                    let content = &self.s[self.pos..self.pos + e];
                                    toks.push(Token::Text(content.to_string()));
                                    // skip to '>'
                                    let after = self.pos + e;
                                    let gt = self.s[after..].find('>').map(|g| after + g + 1).unwrap_or(self.s.len());
                                    self.pos = gt;
                                    toks.push(Token::End(nm));
                                }
                                None => {
                                    toks.push(Token::Text(self.s[self.pos..].to_string()));
                                    self.pos = self.s.len();
                                }
                            }
                            continue;
                        }
                    }
                    toks.push(tok);
                    continue;
                }
            }
            let c = rest.chars().next().unwrap();
            text.push(c);
            self.pos += c.len_utf8();
        }
        if !text.is_empty() {
            toks.push(Token::Text(decode_entities(&text, false)));
        }
        toks
    }

    fn try_tag(&mut self) -> Option<Token> {
        let rest = &self.s[self.pos..];
        let b = rest.as_bytes();
        if rest.starts_with("<!--") {
            let end = rest[4..].find("-->").map(|e| 4 + e + 3).unwrap_or(rest.len());
            self.pos += end;
            return Some(Token::Comment);
        }
        if rest.starts_with("<!") || rest.starts_with("<?") {
            let end = rest.find('>').map(|e| e + 1).unwrap_or(rest.len());
            self.pos += end;
            return Some(Token::Comment);
        }
        if rest.starts_with("</") {
            let mut i = 2;
            if i >= b.len() || !b[i].is_ascii_alphabetic() {
                // "</" followed by non-alpha: bogus comment or text
                if i < b.len() && b[i] == b'>' {
                    self.pos += 3;
                    return Some(Token::Comment);
                }
                let end = rest.find('>').map(|e| e + 1).unwrap_or(rest.len());
                self.pos += end;
                return Some(Token::Comment);
            }
            let ns = i;
            while i < b.len() && !matches!(b[i], b' ' | b'\t' | b'\n' | b'\r' | b'/' | b'>') {
                i += 1;
            }
            let name = rest[ns..i].to_ascii_lowercase();
            let end = rest[i..].find('>').map(|e| i + e + 1).unwrap_or(rest.len());
            self.pos += end;
            return Some(Token::End(name));
        }
        let mut i = 1;
        if i >= b.len() || !b[i].is_ascii_alphabetic() {
            return None;
        }
        let ns = i;
        while i < b.len() && !matches!(b[i], b' ' | b'\t' | b'\n' | b'\r' | b'/' | b'>') {
            i += 1;
        }
        let name = rest[ns..i].to_ascii_lowercase();
        let mut attrs: Vec<(String, String)> = Vec::new();
        let mut self_closing = false;
        loop {
            while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | b'\r' | b'/') {
                if b[i] == b'/' && i + 1 < b.len() && b[i + 1] == b'>' {
                    self_closing = true;
                }
                i += 1;
            }
            if i >= b.len() {
                // EOF in tag
                self.pos = self.s.len();
                return Some(Token::Start { name, attrs, self_closing });
            }
            if b[i] == b'>' {
                i += 1;
                break;
            }
            // attribute name
            let an = i;
            while i < b.len() && !matches!(b[i], b' ' | b'\t' | b'\n' | b'\r' | b'/' | b'>' | b'=') {
                i += 1;
            }
            let aname = rest[an..i].to_ascii_lowercase();
            let mut j = i;
            while j < b.len() && matches!(b[j], b' ' | b'\t' | b'\n' | b'\r') {
                j += 1;
            }
            let mut value = String::new();
            if j < b.len() && b[j] == b'=' {
                j += 1;
                while j < b.len() && matches!(b[j], b' ' | b'\t' | b'\n' | b'\r') {
                    j += 1;
                }
                if j < b.len() && (b[j] == b'"' || b[j] == b'\'') {
                    let q = b[j];
                    j += 1;
                    let vs = j;
                    while j < b.len() && b[j] != q {
                        j += 1;
                    }
                    value = decode_entities(&rest[vs..j], true);
                    if j < b.len() {
                        j += 1;
                    }
                } else {
                    let vs = j;
                    while j < b.len() && !matches!(b[j], b' ' | b'\t' | b'\n' | b'\r' | b'>') {
                        j += 1;
                    }
                    value = decode_entities(&rest[vs..j], true);
                }
                i = j;
            }
            if !aname.is_empty() && !attrs.iter().any(|(n, _)| *n == aname) {
                attrs.push((aname, value));
            }
        }
        self.pos += i;
        Some(Token::Start { name, attrs, self_closing })
    }
}

// ---------------------------------------------------------------------------
// Tree builder (simplified HTML5 "in body" + table handling)
// ---------------------------------------------------------------------------

struct Builder {
    // stack of open elements, each with its children built so far
    stack: Vec<(String, Vec<(String, String)>, Vec<Node>)>,
    skip_newline: bool,
}

const P_CLOSERS: &[&str] = &[
    "address", "article", "aside", "blockquote", "center", "details", "dialog", "dir", "div", "dl", "fieldset",
    "figcaption", "figure", "footer", "header", "hgroup", "main", "menu", "nav", "ol", "p", "search", "section",
    "summary", "ul", "h1", "h2", "h3", "h4", "h5", "h6", "pre", "listing", "form", "table", "hr", "xmp", "plaintext",
];

const SPECIAL_IGNORED: &[&str] = &["html", "head", "body", "frameset", "frame"];

impl Builder {
    fn current(&self) -> &str {
        &self.stack.last().unwrap().0
    }

    fn append(&mut self, node: Node) {
        let top = self.stack.last_mut().unwrap();
        if let Node::Text(t) = &node {
            if let Some(Node::Text(prev)) = top.2.last_mut() {
                prev.push_str(t);
                return;
            }
        }
        top.2.push(node);
    }

    fn open(&mut self, name: String, attrs: Vec<(String, String)>) {
        self.stack.push((name, attrs, Vec::new()));
    }

    fn close_top(&mut self) {
        if self.stack.len() <= 1 {
            return;
        }
        let (name, attrs, children) = self.stack.pop().unwrap();
        self.append(Node::Element { name, attrs, children });
    }

    fn has_in_scope(&self, name: &str, barriers: &[&str]) -> bool {
        for (n, _, _) in self.stack.iter().rev().skip(0) {
            if n == name {
                return true;
            }
            if barriers.contains(&n.as_str()) {
                return false;
            }
        }
        false
    }

    fn close_until(&mut self, name: &str) {
        while self.stack.len() > 1 {
            let top = self.current().to_string();
            self.close_top();
            if top == name {
                break;
            }
        }
    }

    fn close_p_if_open(&mut self) {
        if self.has_in_scope("p", &["button", "table", "td", "th", "caption", "html", "#root"]) {
            self.close_until("p");
        }
    }

    fn in_table_scope(&self, name: &str) -> bool {
        self.has_in_scope(name, &["table", "html", "#root"])
    }

    fn handle_start(&mut self, name: String, attrs: Vec<(String, String)>, self_closing: bool) {
        let n = name.as_str();
        if SPECIAL_IGNORED.contains(&n) {
            return;
        }
        // Table-related start tags
        match n {
            "caption" | "colgroup" | "col" | "thead" | "tbody" | "tfoot" | "tr" | "td" | "th" => {
                let in_table = self.stack.iter().any(|(nm, _, _)| nm == "table");
                if !in_table {
                    // in body: ignore
                    return;
                }
                match n {
                    "tr" => {
                        // close to tbody/thead/tfoot; insert tbody if directly in table
                        while self.stack.len() > 1 && !matches!(self.current(), "tbody" | "thead" | "tfoot" | "table") {
                            self.close_top();
                        }
                        if self.current() == "table" {
                            self.open("tbody".into(), vec![]);
                        }
                        self.open(name, attrs);
                    }
                    "td" | "th" => {
                        while self.stack.len() > 1 && !matches!(self.current(), "tr" | "tbody" | "thead" | "tfoot" | "table") {
                            self.close_top();
                        }
                        if self.current() == "table" {
                            self.open("tbody".into(), vec![]);
                        }
                        if matches!(self.current(), "tbody" | "thead" | "tfoot") {
                            self.open("tr".into(), vec![]);
                        }
                        self.open(name, attrs);
                    }
                    "thead" | "tbody" | "tfoot" | "caption" | "colgroup" => {
                        while self.stack.len() > 1 && self.current() != "table" {
                            self.close_top();
                        }
                        self.open(name, attrs);
                    }
                    "col" => {
                        while self.stack.len() > 1 && !matches!(self.current(), "colgroup" | "table") {
                            self.close_top();
                        }
                        if self.current() == "table" {
                            self.open("colgroup".into(), vec![]);
                        }
                        self.open(name, attrs);
                        self.close_top();
                    }
                    _ => {}
                }
                return;
            }
            _ => {}
        }
        if P_CLOSERS.contains(&n) {
            self.close_p_if_open();
        }
        match n {
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if matches!(self.current(), "h1" | "h2" | "h3" | "h4" | "h5" | "h6") {
                    self.close_top();
                }
            }
            "li" => {
                // close an open li (up to a list container)
                let mut idx = self.stack.len();
                while idx > 1 {
                    idx -= 1;
                    let nm = self.stack[idx].0.as_str();
                    if nm == "li" {
                        while self.stack.len() > idx {
                            self.close_top();
                        }
                        break;
                    }
                    if matches!(nm, "ul" | "ol" | "div" | "address" | "p" | "table" | "td" | "th" | "button" | "blockquote" | "section" | "article") {
                        if nm == "p" {
                            continue;
                        }
                        break;
                    }
                }
                self.close_p_if_open();
            }
            "dd" | "dt" => {
                let mut idx = self.stack.len();
                while idx > 1 {
                    idx -= 1;
                    let nm = self.stack[idx].0.as_str();
                    if nm == "dd" || nm == "dt" {
                        while self.stack.len() > idx {
                            self.close_top();
                        }
                        break;
                    }
                    if matches!(nm, "dl" | "div" | "address" | "table" | "td" | "th") {
                        break;
                    }
                }
                self.close_p_if_open();
            }
            "a" => {
                if self.stack.iter().any(|(nm, _, _)| nm == "a") {
                    self.close_until("a");
                }
            }
            "option" | "optgroup" => {
                if matches!(self.current(), "option" | "optgroup") {
                    self.close_top();
                }
            }
            "button" => {
                if self.stack.iter().any(|(nm, _, _)| nm == "button") {
                    self.close_until("button");
                }
            }
            "image" => {
                return self.handle_start("img".to_string(), attrs, self_closing);
            }
            _ => {}
        }
        if VOID.contains(&n) {
            self.append(Node::Element { name, attrs, children: vec![] });
            return;
        }
        if n == "pre" || n == "listing" || n == "textarea" {
            self.skip_newline = true;
        }
        self.open(name, attrs);
    }

    fn handle_end(&mut self, name: String) {
        let n = name.as_str();
        if n == "br" {
            self.append(Node::Element { name: "br".into(), attrs: vec![], children: vec![] });
            return;
        }
        if n == "p" {
            if !self.has_in_scope("p", &["button", "table", "td", "th", "caption", "#root"]) {
                self.append(Node::Element { name: "p".into(), attrs: vec![], children: vec![] });
                return;
            }
            self.close_until("p");
            return;
        }
        if SPECIAL_IGNORED.contains(&n) || VOID.contains(&n) {
            return;
        }
        match n {
            "table" => {
                if self.in_table_scope("table") {
                    self.close_until("table");
                }
                return;
            }
            "tr" | "td" | "th" | "tbody" | "thead" | "tfoot" | "caption" | "colgroup" => {
                if self.in_table_scope(n) {
                    self.close_until(n);
                }
                return;
            }
            "li" => {
                if self.has_in_scope("li", &["ul", "ol", "table", "td", "th", "#root"]) {
                    self.close_until("li");
                }
                return;
            }
            "dd" | "dt" => {
                if self.has_in_scope(n, &["dl", "table", "td", "th", "#root"]) {
                    self.close_until(n);
                }
                return;
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                // close any heading
                if let Some(idx) = self.stack.iter().rposition(|(nm, _, _)| matches!(nm.as_str(), "h1" | "h2" | "h3" | "h4" | "h5" | "h6")) {
                    let barrier = self.stack[idx + 1..].iter().any(|(nm, _, _)| matches!(nm.as_str(), "table" | "td" | "th" | "button"));
                    if !barrier {
                        while self.stack.len() > idx {
                            self.close_top();
                        }
                    }
                }
                return;
            }
            _ => {}
        }
        // generic: find in stack (not crossing table cells / scope barriers)
        if let Some(idx) = self.stack.iter().rposition(|(nm, _, _)| nm == n) {
            if idx == 0 {
                return;
            }
            let barrier = self.stack[idx + 1..].iter().any(|(nm, _, _)| matches!(nm.as_str(), "table" | "td" | "th" | "caption" | "button" | "html" | "#root"));
            if barrier {
                return;
            }
            while self.stack.len() > idx {
                self.close_top();
            }
        }
    }

    fn handle_text(&mut self, text: String) {
        let mut t = text;
        if self.skip_newline {
            self.skip_newline = false;
            if let Some(rest) = t.strip_prefix('\n') {
                t = rest.to_string();
            }
            if t.is_empty() {
                return;
            }
        }
        // text in table context (not in a cell) is foster-parented before the table
        let in_table_ctx = matches!(self.current(), "table" | "tbody" | "thead" | "tfoot" | "tr");
        if in_table_ctx {
            if t.trim().is_empty() {
                // whitespace is allowed inside tables
                self.append(Node::Text(t));
                return;
            }
            // foster parent: insert before the table element in its parent
            let tidx = self.stack.iter().rposition(|(nm, _, _)| nm == "table").unwrap();
            if tidx >= 1 {
                // we need to insert the text as a sibling before the table in stack[tidx-1]'s children,
                // but the table is still open; we record it as a pending pre-node
                let parent = &mut self.stack[tidx - 1].2;
                if let Some(Node::Text(prev)) = parent.last_mut() {
                    prev.push_str(&t);
                } else {
                    parent.push(Node::Text(t));
                }
            }
            return;
        }
        self.append(Node::Text(t));
    }
}

pub fn parse_fragment(html: &str) -> Vec<Node> {
    let toks = Tokenizer { s: html, pos: 0 }.tokens();
    let mut b = Builder {
        stack: vec![("#root".to_string(), vec![], vec![])],
        skip_newline: false,
    };
    for tok in toks {
        match tok {
            Token::Start { name, attrs, self_closing } => {
                b.skip_newline = false;
                b.handle_start(name, attrs, self_closing);
            }
            Token::End(name) => {
                b.skip_newline = false;
                b.handle_end(name);
            }
            Token::Text(t) => b.handle_text(t),
            Token::Comment => {
                b.skip_newline = false;
            }
        }
    }
    while b.stack.len() > 1 {
        b.close_top();
    }
    b.stack.pop().unwrap().2
}

// ---------------------------------------------------------------------------
// Sanitizing
// ---------------------------------------------------------------------------

fn clean_nodes(nodes: Vec<Node>) -> Vec<Node> {
    let mut out: Vec<Node> = Vec::new();
    for node in nodes {
        match node {
            Node::Text(t) => push_text(&mut out, t),
            Node::Element { name, attrs, children } => {
                if CLEAN_CONTENT_TAGS.contains(&name.as_str()) {
                    continue;
                }
                let cleaned_children = clean_nodes(children);
                if !ALLOWED_TAGS.contains(&name.as_str()) {
                    // unwrap: keep children
                    for c in cleaned_children {
                        match c {
                            Node::Text(t) => push_text(&mut out, t),
                            other => out.push(other),
                        }
                    }
                    continue;
                }
                let mut new_attrs: Vec<(String, String)> = Vec::new();
                for (k, v) in attrs {
                    let allowed = GENERIC_ATTRS.contains(&k.as_str()) || tag_attrs(&name).contains(&k.as_str());
                    if !allowed {
                        continue;
                    }
                    if is_url_attr(&name, &k) && !url_allowed(&v) {
                        continue;
                    }
                    new_attrs.push((k, v));
                }
                if name == "a" {
                    new_attrs.push(("rel".to_string(), "noopener noreferrer".to_string()));
                }
                out.push(Node::Element { name, attrs: new_attrs, children: cleaned_children });
            }
        }
    }
    out
}

fn push_text(out: &mut Vec<Node>, t: String) {
    if let Some(Node::Text(prev)) = out.last_mut() {
        prev.push_str(&t);
    } else {
        out.push(Node::Text(t));
    }
}

fn escape_text(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '\u{a0}' => out.push_str("&nbsp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
}

fn escape_attr(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '\u{a0}' => out.push_str("&nbsp;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
}

pub fn serialize(nodes: &[Node], out: &mut String) {
    for n in nodes {
        match n {
            Node::Text(t) => escape_text(t, out),
            Node::Element { name, attrs, children } => {
                out.push('<');
                out.push_str(name);
                for (k, v) in attrs {
                    out.push(' ');
                    out.push_str(k);
                    out.push_str("=\"");
                    escape_attr(v, out);
                    out.push('"');
                }
                out.push('>');
                if VOID.contains(&name.as_str()) {
                    continue;
                }
                serialize(children, out);
                out.push_str("</");
                out.push_str(name);
                out.push('>');
            }
        }
    }
}

pub fn sanitize(html: &str) -> String {
    let nodes = parse_fragment(html);
    let cleaned = clean_nodes(nodes);
    let mut out = String::new();
    serialize(&cleaned, &mut out);
    out
}

