fn shell_string(chars: &[char], start: usize, sp: &mut Spans) -> usize {
    let q = chars[start];
    let n = chars.len();
    let mut i = start + 1;
    sp.push(&q.to_string(), PUNCT);
    let mut buf = String::new();
    while i < n {
        let c = chars[i];
        if c == q {
            sp.push(&buf, STR);
            buf.clear();
            sp.push(&q.to_string(), PUNCT);
            return i + 1;
        }
        if q == '"' && c == '\\' && i + 1 < n {
            sp.push(&buf, STR);
            buf.clear();
            sp.push(&chars[i..i + 2].iter().collect::<String>(), PUNCT);
            i += 2;
            continue;
        }
        if q == '"' && c == '$' {
            sp.push(&buf, STR);
            buf.clear();
            i = shell_variable(chars, i, sp);
            continue;
        }
        buf.push(c);
        i += 1;
    }
    sp.push(&buf, STR);
    n
}

fn shell_variable(chars: &[char], start: usize, sp: &mut Spans) -> usize {
    let n = chars.len();
    let mut i = start + 1;
    if i >= n {
        sp.push("$", PUNCT);
        return i;
    }
    let c = chars[i];
    if c == '{' {
        sp.push("${", PUNCT);
        i += 1;
        let s = i;
        while i < n && chars[i] != '}' && chars[i] != '\n' {
            i += 1;
        }
        sp.push(&chars[s..i].iter().collect::<String>(), FG);
        if i < n && chars[i] == '}' {
            sp.push("}", PUNCT);
            i += 1;
        }
        return i;
    }
    if c == '(' {
        sp.push("$(", PUNCT);
        return i + 1;
    }
    if c.is_alphabetic() || c == '_' {
        sp.push("$", PUNCT);
        let s = i;
        while i < n && (chars[i].is_alphanumeric() || chars[i] == '_') {
            i += 1;
        }
        sp.push(&chars[s..i].iter().collect::<String>(), FG);
        return i;
    }
    if c.is_ascii_digit() {
        sp.push("$", PUNCT);
        sp.push(&c.to_string(), FG);
        return i + 1;
    }
    if matches!(c, '@' | '?' | '$' | '!' | '#' | '*' | '-') {
        sp.push("$", PUNCT);
        sp.push(&c.to_string(), LANG);
        return i + 1;
    }
    sp.push("$", PUNCT);
    i
}

