cat > /workspace/src/highlight.rs <<'EOF'
//! Syntax highlighting producing syntect-style HTML (MaterialTheme colours)
//! for a handful of common languages.

use crate::config::SyntaxTheme;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Style(&'static str);

const FG: Style = Style("color:#eeffff;");
const FUNC: Style = Style("color:#82aaff;");
const PUNCT: Style = Style("color:#89ddff;");
const PARAM: Style = Style("color:#f78c6c;");
const STR: Style = Style("color:#c3e88d;");
const KW: Style = Style("font-style:italic;color:#c792ea;");
const KW2: Style = Style("color:#c792ea;");
const COMMENT: Style = Style("font-style:italic;color:#546e7a;");
const LANG: Style = Style("font-style:italic;color:#ff5370;");
const KEY: Style = Style("color:#f07178;");
const TYPE: Style = Style("color:#ffcb6b;");

pub fn highlight_html(code: &str, lang: Option<&str>, theme: SyntaxTheme) -> String {
    let _ = theme;
    let mut out = String::from("<pre style=\"background-color:#263238;\">\n");
    let lang = lang.map(|l| l.to_ascii_lowercase());
    let kind = match lang.as_deref() {
        Some("sh") | Some("bash") | Some("shell") | Some("zsh") | Some("shellscript") | Some("bourne again shell") => Lang::Shell,
        Some("toml") => Lang::Toml,
        Some("json") => Lang::Json,
        Some("rust") | Some("rs") => Lang::Rust,
        _ => Lang::Plain,
    };
    let mut state = State::default();
    for line in lines_with_endings(code) {
        let spans = match kind {
            Lang::Plain => vec![(line.to_string(), FG)],
            Lang::Shell => shell_line(line),
            Lang::Toml => toml_line(line),
            Lang::Json => json_line(line, &mut state),
            Lang::Rust => rust_line(line, &mut state),
        };
        for (text, style) in merge(spans) {
            if text.is_empty() {
                continue;
            }
            out.push_str("<span style=\"");
            out.push_str(style.0);
            out.push_str("\">");
            out.push_str(&escape(&text));
            out.push_str("</span>");
        }
    }
    out.push_str("</pre>\n");
    out
}

#[derive(Clone, Copy)]
enum Lang {
    Plain,
    Shell,
    Toml,
    Json,
    Rust,
}

#[derive(Default)]
struct State {
    json_depth: usize,
    json_expect_key: Vec<bool>,
    rust_block_comment: bool,
}

fn merge(spans: Vec<(String, Style)>) -> Vec<(String, Style)> {
    let mut out: Vec<(String, Style)> = Vec::new();
    for (t, s) in spans {
        if t.is_empty() {
            continue;
        }
        if let Some(last) = out.last_mut() {
            if last.1 == s {
                last.0.push_str(&t);
                continue;
            }
        }
        out.push((t, s));
    }
    out
}

pub fn lines_with_endings(s: &str) -> Vec<&str> {
    let mut v = Vec::new();
    let mut start = 0;
    for (i, c) in s.char_indices() {
        if c == '\n' {
            v.push(&s[start..=i]);
            start = i + 1;
        }
    }
    if start < s.len() {
        v.push(&s[start..]);
    }
    v
}

pub fn escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Shell
// ---------------------------------------------------------------------------

struct Spans {
    spans: Vec<(String, Style)>,
    pending_ws: String,
}

impl Spans {
    fn new() -> Spans {
        Spans { spans: Vec::new(), pending_ws: String::new() }
    }
    fn last_style(&self) -> Option<Style> {
        self.spans.last().map(|s| s.1)
    }
    fn push(&mut self, text: &str, style: Style) {
        if text.is_empty() {
            return;
        }
        self.spans.push((text.to_string(), style));
    }
    /// Flush pending whitespace with the given style.
    fn flush_ws(&mut self, style: Style) {
        if !self.pending_ws.is_empty() {
            let ws = std::mem::take(&mut self.pending_ws);
            self.push(&ws, style);
        }
    }
    /// Flush pending whitespace attached to the preceding token (or default).
    fn flush_ws_prev(&mut self, default: Style) {
        let st = self.last_style().unwrap_or(default);
        self.flush_ws(st);
    }
}

const SH_KEYWORDS: &[&str] = &[
    "if", "then", "else", "elif", "fi", "for", "while", "until", "do", "done", "case", "esac", "select",
    "function", "in", "time", "break", "continue", "return",
];
const SH_DECL: &[&str] = &["export", "local", "declare", "readonly", "typeset", "unset", "set", "alias"];

fn is_word_char(c: char) -> bool {
    !c.is_whitespace() && !matches!(c, ';' | '&' | '|' | '<' | '>' | '(' | ')' | '$' | '"' | '\'' | '`' | '#' | '{' | '}' | '*' | '?' | '\\')
}

fn shell_line(line: &str) -> Vec<(String, Style)> {
    let mut sp = Spans::new();
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    let n = chars.len();
    // context
    let mut cmd_start = true; // at a position where a command word is expected
    let mut word_mode_fg = false; // after `for x in` / `case ... in`: words are plain
    let mut after_for = false;
    while i < n {
        let c = chars[i];
        // whitespace (not newline)
        if c == ' ' || c == '\t' {
            let s = i;
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                i += 1;
            }
            sp.pending_ws.push_str(&chars[s..i].iter().collect::<String>());
            continue;
        }
        if c == '\n' || c == '\r' {
            let rest: String = chars[i..].iter().collect();
            sp.flush_ws_prev(FG);
            let st = sp.last_style().unwrap_or(FG);
            sp.push(&rest, st);
            i = n;
            continue;
        }
        // comment
        if c == '#' && (i == 0 || chars[i - 1].is_whitespace() || !sp.pending_ws.is_empty() || sp.spans.is_empty()) {
            sp.flush_ws_prev(FG);
            let rest: String = chars[i..].iter().collect();
            sp.push(&rest, COMMENT);
            i = n;
            continue;
        }
        // line continuation
        if c == '\\' && i + 1 < n && (chars[i + 1] == '\n' || chars[i + 1] == '\r') {
            sp.flush_ws_prev(FG);
            let rest: String = chars[i..].iter().collect();
            sp.push(&rest, PUNCT);
            i = n;
            continue;
        }
        // operators that end a command (consume following whitespace as punct)
        let rest: String = chars[i..].iter().take(3).collect();
        let op_len = if rest.starts_with("&&") || rest.starts_with("||") || rest.starts_with(";;") {
            2
        } else if rest.starts_with(';') || rest.starts_with('|') || rest.starts_with('&') || rest.starts_with('{') || rest.starts_with('}') || rest.starts_with('(') || rest.starts_with(')') {
            1
        } else {
            0
        };
        if op_len > 0 {
            if c == '&' && i + 1 < n && chars[i + 1] == '>' {
                // &> redirect
            } else {
                sp.flush_ws_prev(FG);
                let op: String = chars[i..i + op_len].iter().collect();
                i += op_len;
                let mut text = op;
                while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                    text.push(chars[i]);
                    i += 1;
                }
                if c == ')' && word_mode_fg {
                    // case pattern terminator
                    sp.push(&text, KW);
                    cmd_start = true;
                    word_mode_fg = false;
                    continue;
                }
                sp.push(&text, PUNCT);
                cmd_start = true;
                if c == ';' {
                    word_mode_fg = false;
                }
                continue;
            }
        }
        // redirections
        if c == '>' || c == '<' || (c == '&' && i + 1 < n && chars[i + 1] == '>') {
            sp.flush_ws_prev(FG);
            let mut j = i;
            while j < n && matches!(chars[j], '>' | '<' | '&') {
                j += 1;
            }
            let op: String = chars[i..j].iter().collect();
            sp.push(&op, PUNCT);
            i = j;
            // fd number after >&
            if op.ends_with('&') {
                let s = i;
                while i < n && chars[i].is_ascii_digit() {
                    i += 1;
                }
                if i > s {
                    sp.push(&chars[s..i].iter().collect::<String>(), PARAM);
                }
            }
            continue;
        }
        // quotes
        if c == '"' || c == '\'' {
            sp.flush_ws_prev(FG);
            i = shell_string(&chars, i, &mut sp);
            cmd_start = false;
            continue;
        }
        if c == '`' {
            sp.flush_ws_prev(FG);
            sp.push("`", PUNCT);
            i += 1;
            cmd_start = true;
            continue;
        }
        // variables
        if c == '$' {
            // `$ ` prompt at line start: treat as a word
            if cmd_start && (i + 1 >= n || chars[i + 1] == ' ') && sp.spans.is_empty() {
                // fallthrough to word handling below
            } else {
                sp.flush_ws_prev(FG);
                i = shell_variable(&chars, i, &mut sp);
                cmd_start = false;
                continue;
            }
        }
        // options
        if c == '-' && !word_mode_fg && !cmd_start {
            let mut j = i;
            while j < n && chars[j] == '-' {
                j += 1;
            }
            if j - i <= 2 {
                sp.flush_ws(PUNCT);
                sp.push(&chars[i..j].iter().collect::<String>(), PUNCT);
                i = j;
                let s = i;
                while i < n && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-') {
                    i += 1;
                }
                if i > s {
                    let name: String = chars[s..i].iter().collect();
                    // trailing whitespace belongs to the option if followed by a quote
                    let mut k = i;
                    while k < n && (chars[k] == ' ' || chars[k] == '\t') {
                        k += 1;
                    }
                    sp.push(&name, PARAM);
                    if k > i && k < n && (chars[k] == '"' || chars[k] == '\'') {
                        sp.push(&chars[i..k].iter().collect::<String>(), PARAM);
                        i = k;
                    }
                }
                if i < n && chars[i] == '=' {
                    sp.push("=", PUNCT);
                    i += 1;
                }
                // remaining word chars (e.g. `.2`, or option value) as FUNC
                let s2 = i;
                while i < n && is_word_char(chars[i]) {
                    i += 1;
                }
                if i > s2 {
                    sp.push(&chars[s2..i].iter().collect::<String>(), FUNC);
                }
                continue;
            }
        }
        // glob
        if c == '*' || c == '?' {
            sp.flush_ws_prev(FG);
            sp.push(&c.to_string(), PUNCT);
            i += 1;
            continue;
        }
        // tilde at word start
        if c == '~' {
            sp.flush_ws(FUNC);
            sp.push("~", LANG);
            i += 1;
            let s = i;
            while i < n && is_word_char(chars[i]) && chars[i] != '~' {
                i += 1;
            }
            if i > s {
                sp.push(&chars[s..i].iter().collect::<String>(), FUNC);
            }
            cmd_start = false;
            continue;
        }
        // word
        let s = i;
        while i < n && is_word_char(chars[i]) && chars[i] != '~' {
            i += 1;
        }
        if i == s {
            // unknown single char
            sp.flush_ws_prev(FG);
            sp.push(&c.to_string(), FG);
            i += 1;
            continue;
        }
        let word: String = chars[s..i].iter().collect();
        if after_for {
            // loop variable
            sp.flush_ws(FG);
            sp.push(&word, FG);
            after_for = false;
            cmd_start = false;
            continue;
        }
        if cmd_start && SH_KEYWORDS.contains(&word.as_str()) {
            sp.flush_ws_prev(FG);
            let mut text = word.clone();
            if word != "for" {
                while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                    text.push(chars[i]);
                    i += 1;
                }
            }
            sp.push(&text, KW);
            after_for = word == "for";
            if word == "in" {
                word_mode_fg = true;
                cmd_start = false;
            } else {
                cmd_start = true;
            }
            continue;
        }
        if word == "in" && (word_mode_fg || sp.spans.iter().any(|s| s.1 == KW)) && !cmd_start {
            sp.flush_ws(FG);
            let mut text = word.clone();
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                text.push(chars[i]);
                i += 1;
            }
            sp.push(&text, KW);
            word_mode_fg = true;
            continue;
        }
        if cmd_start && SH_DECL.contains(&word.as_str()) {
            sp.flush_ws_prev(FG);
            let mut text = word.clone();
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                text.push(chars[i]);
                i += 1;
            }
            sp.push(&text, KW2);
            continue;
        }
        // assignment at command start: NAME=value
        if cmd_start || sp.last_style() == Some(KW2) {
            if let Some(eq) = word.find('=') {
                let name = &word[..eq];
                if !name.is_empty() && name.chars().all(|ch| ch.is_alphanumeric() || ch == '_') && name.chars().next().map(|ch| !ch.is_ascii_digit()).unwrap_or(false) {
                    sp.flush_ws_prev(FG);
                    sp.push(name, FG);
                    sp.push("=", PUNCT);
                    let value = &word[eq + 1..];
                    if !value.is_empty() {
                        let mut text = value.to_string();
                        while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                            text.push(chars[i]);
                            i += 1;
                        }
                        sp.push(&text, STR);
                    }
                    continue;
                }
            }
        }
        // function definition name()
        if word_mode_fg {
            sp.flush_ws(FG);
            sp.push(&word, FG);
            continue;
        }
        if matches!(word.as_str(), "[[" | "]]" | "[" | "]") {
            sp.flush_ws_prev(FG);
            sp.push(&word, FUNC);
            continue;
        }
        sp.flush_ws(FUNC);
        sp.push(&word, FUNC);
        cmd_start = false;
    }
    sp.flush_ws_prev(FG);
    sp.spans
}

fn shell_string(chars: &[char], start: usize, sp: &mut Spans) -> usize {
    let q = chars[start];
    let n = chars.len();
    let mut i = start + 1;
    sp.push(&q.to_string(), PUNCT);
    let mut buf = String::new();
    while i < n {
        let c = chars[i];
        if c == q {
            sp.push(&buf, STR);
            buf.clear();
            sp.push(&q.to_string(), PUNCT);
            return i + 1;
        }
        if q == '"' && c == '\\' && i + 1 < n {
            sp.push(&buf, STR);
            buf.clear();
            sp.push(&chars[i..i + 2].iter().collect::<String>(), PUNCT);
            i += 2;
            continue;
        }
        if q == '"' && c == '$' {
            sp.push(&buf, STR);
            buf.clear();
            i = shell_variable(chars, i, sp);
            continue;
        }
        buf.push(c);
        i += 1;
    }
    sp.push(&buf, STR);
    n
}

fn shell_variable(chars: &[char], start: usize, sp: &mut Spans) -> usize {
    let n = chars.len();
    let mut i = start + 1;
    if i >= n {
        sp.push("$", PUNCT);
        return i;
    }
    let c = chars[i];
    if c == '{' {
        sp.push("${", PUNCT);
        i += 1;
        let s = i;
        while i < n && chars[i] != '}' && chars[i] != '\n' {
            i += 1;
        }
        sp.push(&chars[s..i].iter().collect::<String>(), FG);
        if i < n && chars[i] == '}' {
            sp.push("}", PUNCT);
            i += 1;
        }
        return i;
    }
    if c == '(' {
        sp.push("$(", PUNCT);
        return i + 1;
    }
    if c.is_alphabetic() || c == '_' {
        sp.push("$", PUNCT);
        let s = i;
        while i < n && (chars[i].is_alphanumeric() || chars[i] == '_') {
            i += 1;
        }
        sp.push(&chars[s..i].iter().collect::<String>(), FG);
        return i;
    }
    if c.is_ascii_digit() {
        sp.push("$", PUNCT);
        sp.push(&c.to_string(), FG);
        return i + 1;
    }
    if matches!(c, '@' | '?' | '$' | '!' | '#' | '*' | '-') {
        sp.push("$", PUNCT);
        sp.push(&c.to_string(), LANG);
        return i + 1;
    }
    sp.push("$", PUNCT);
    i
}

