fn toml_line(line: &str) -> Vec<(String, Style)> {
    let chars: Vec<char> = line.chars().collect();
    let n = chars.len();
    let mut out: Vec<(String, Style)> = Vec::new();
    let trimmed = line.trim_start();
    let lead = line.len() - trimmed.len();
    if trimmed.starts_with('#') {
        out.push((line[..lead].to_string(), FG));
        out.push((trimmed.to_string(), COMMENT));
        return out;
    }
    if trimmed.starts_with('[') {
        out.push((line[..lead].to_string(), FG));
        out.push((trimmed.to_string(), PUNCT));
        return out;
    }
    if trimmed.trim().is_empty() {
        out.push((line.to_string(), FG));
        return out;
    }
    let mut i = 0;
    // key(s)
    let mut expect_key = true;
    let mut in_inline_table = 0;
    while i < n {
        let c = chars[i];
        if c == '\n' || c == '\r' {
            let st = out.last().map(|s| s.1).unwrap_or(FG);
            out.push((chars[i..].iter().collect(), st));
            break;
        }
        if c == '#' {
            out.push((chars[i..].iter().collect(), COMMENT));
            break;
        }
        if expect_key && (c.is_alphanumeric() || c == '_' || c == '-' || c == '"' || c == '\'') {
            let s = i;
            if c == '"' || c == '\'' {
                i += 1;
                while i < n && chars[i] != c {
                    i += 1;
                }
                i += 1;
            } else {
                while i < n && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-') {
                    i += 1;
                }
            }
            let mut text: String = chars[s..i.min(n)].iter().collect();
            if i < n && chars[i] == '.' {
                out.push((text, KEY));
                out.push((".".to_string(), PUNCT));
                i += 1;
                continue;
            }
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                text.push(chars[i]);
                i += 1;
            }
            out.push((text, KEY));
            expect_key = false;
            continue;
        }
        if c == '=' {
            let mut text = String::from("=");
            i += 1;
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                text.push(chars[i]);
                i += 1;
            }
            out.push((text, PUNCT));
            continue;
        }
        if c == '"' || c == '\'' {
            let q = c;
            i += 1;
            out.push((q.to_string(), PUNCT));
            let s = i;
            while i < n && chars[i] != q {
                if chars[i] == '\\' && q == '"' {
                    i += 1;
                }
                i += 1;
            }
            out.push((chars[s..i.min(n)].iter().collect(), STR));
            if i < n {
                out.push((q.to_string(), PUNCT));
                i += 1;
            }
            continue;
        }
        if matches!(c, '[' | ']' | ',' | '{' | '}') {
            if c == '{' {
                in_inline_table += 1;
                expect_key = true;
            } else if c == '}' {
                in_inline_table -= 1;
            } else if c == ',' && in_inline_table > 0 {
                expect_key = true;
            }
            let mut text = c.to_string();
            i += 1;
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                text.push(chars[i]);
                i += 1;
            }
            out.push((text, PUNCT));
            continue;
        }
        if c.is_ascii_digit() || c == '-' || c == '+' || c == 't' || c == 'f' || c == 'i' || c == 'n' {
            let s = i;
            while i < n && (chars[i].is_alphanumeric() || matches!(chars[i], '.' | '-' | '+' | ':' | '_')) {
                i += 1;
            }
            let mut text: String = chars[s..i].iter().collect();
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                text.push(chars[i]);
                i += 1;
            }
            out.push((text, PARAM));
            continue;
        }
        out.push((c.to_string(), FG));
        i += 1;
    }
    out
}

