// JSON
// ---------------------------------------------------------------------------

fn json_key_style(level: usize) -> Style {
    match level {
        0 => KW2,
        1 => TYPE,
        2 => KEY,
        3 => Style("color:#c17e70;"),
        4 => FUNC,
        5 => PARAM,
        6 => KW2,
        7 => STR,
        _ => LANG,
    }
}

fn json_line(line: &str, st: &mut State) -> Vec<(String, Style)> {
    let chars: Vec<char> = line.chars().collect();
    let n = chars.len();
    let mut out: Vec<(String, Style)> = Vec::new();
    let mut i = 0;
    // leading whitespace
    let s = i;
    while i < n && (chars[i] == ' ' || chars[i] == '\t') {
        i += 1;
    }
    if i > s {
        out.push((chars[s..i].iter().collect(), FG));
    }
    while i < n {
        let c = chars[i];
        if c == '\n' || c == '\r' {
            let style = out.last().map(|s| s.1).unwrap_or(FG);
            out.push((chars[i..].iter().collect(), style));
            break;
        }
        if matches!(c, '{' | '}' | '[' | ']' | ':' | ',') {
            match c {
                '{' => {
                    st.json_expect_key.push(true);
                    st.json_depth += 1;
                }
                '}' => {
                    st.json_expect_key.pop();
                    st.json_depth = st.json_depth.saturating_sub(1);
                }
                '[' => st.json_expect_key.push(false),
                ']' => {
                    st.json_expect_key.pop();
                }
                ':' => {
                    if let Some(last) = st.json_expect_key.last_mut() {
                        *last = false;
                    }
                }
                ',' => {
                    if let Some(last) = st.json_expect_key.last_mut() {
                        // inside an object, next is a key
                        *last = true;
                    }
                    // arrays: expect_key stays false; we fix below
                }
                _ => {}
            }
            let mut text = c.to_string();
            i += 1;
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                text.push(chars[i]);
                i += 1;
            }
            out.push((text, PUNCT));
            continue;
        }
        if c == '"' {
            // string: key or value
            let s = i;
            i += 1;
            let mut j = i;
            while j < n && chars[j] != '"' {
                if chars[j] == '\\' {
                    j += 1;
                }
                j += 1;
            }
            let end = (j + 1).min(n);
            // determine whether this string is a key: in object and expecting key
            let in_obj_key = st.json_expect_key.last().copied().unwrap_or(false) && is_object_context(st);
            if in_obj_key {
                let level = st.json_depth.saturating_sub(1);
                out.push((chars[s..end].iter().collect(), json_key_style(level)));
            } else {
                out.push(("\"".to_string(), PUNCT));
                let mut buf = String::new();
                let mut k = i;
                while k < j {
                    if chars[k] == '\\' && k + 1 < j {
                        out.push((std::mem::take(&mut buf), STR));
                        out.push((chars[k..k + 2].iter().collect(), PUNCT));
                        k += 2;
                        continue;
                    }
                    buf.push(chars[k]);
                    k += 1;
                }
                out.push((buf, STR));
                if j < n {
                    out.push(("\"".to_string(), PUNCT));
                }
            }
            i = end;
            continue;
        }
        if c.is_ascii_digit() || c == '-' || c == 't' || c == 'f' || c == 'n' {
            let s = i;
            while i < n && (chars[i].is_alphanumeric() || matches!(chars[i], '.' | '-' | '+')) {
                i += 1;
            }
            out.push((chars[s..i].iter().collect(), PARAM));
            continue;
        }
        if c == ' ' || c == '\t' {
            let s = i;
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                i += 1;
            }
            let style = out.last().map(|s| s.1).unwrap_or(FG);
            out.push((chars[s..i].iter().collect(), style));
            continue;
        }
        out.push((c.to_string(), FG));
        i += 1;
    }
    out
}

fn is_object_context(st: &State) -> bool {
    // The innermost container is an object if its expect_key flag is tracked as object.
    // We approximate: arrays push `false` and never set to true.
    match st.json_expect_key.last() {
        Some(true) => true,
        _ => false,
    }
}

