const RUST_KW_ITALIC: &[&str] = &[
    "fn", "let", "struct", "enum", "impl", "trait", "if", "else", "match", "for", "while", "loop", "return",
    "use", "mod", "as", "where", "type", "unsafe", "async", "await", "move", "dyn", "break", "continue",
    "static", "const", "extern", "crate", "super", "self", "Self", "u8", "u16", "u32", "u64", "u128", "usize",
    "i8", "i16", "i32", "i64", "i128", "isize", "f32", "f64", "bool", "char", "str", "in", "ref", "macro_rules",
];
const RUST_KW_PLAIN: &[&str] = &["pub", "mut", "use", "in"];

fn rust_line(line: &str, st: &mut State) -> Vec<(String, Style)> {
    let chars: Vec<char> = line.chars().collect();
    let n = chars.len();
    let mut out: Vec<(String, Style)> = Vec::new();
    let mut i = 0;
    let mut prev_word = String::new();
    while i < n {
        let c = chars[i];
        if st.rust_block_comment {
            let s = i;
            while i < n && !(chars[i] == '*' && i + 1 < n && chars[i + 1] == '/') {
                i += 1;
            }
            if i < n {
                i += 2;
                st.rust_block_comment = false;
            }
            out.push((chars[s..i].iter().collect(), COMMENT));
            continue;
        }
        if c == '\n' || c == '\r' {
            let style = out.last().map(|s| s.1).unwrap_or(FG);
            out.push((chars[i..].iter().collect(), style));
            break;
        }
        if c == '/' && i + 1 < n && chars[i + 1] == '/' {
            out.push((chars[i..].iter().collect(), COMMENT));
            break;
        }
        if c == '/' && i + 1 < n && chars[i + 1] == '*' {
            st.rust_block_comment = true;
            out.push(("/*".to_string(), COMMENT));
            i += 2;
            continue;
        }
        if c == ' ' || c == '\t' {
            let s = i;
            while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                i += 1;
            }
            let ws: String = chars[s..i].iter().collect();
            // whitespace attaches to previous token, unless at line start
            let style = if out.is_empty() { FG } else { out.last().unwrap().1 };
            out.push((ws, style));
            continue;
        }
        if c == '"' {
            out.push(("\"".to_string(), PUNCT));
            i += 1;
            let mut buf = String::new();
            let is_format = prev_word.ends_with('!');
            while i < n && chars[i] != '"' {
                if chars[i] == '\\' && i + 1 < n {
                    out.push((std::mem::take(&mut buf), if is_format { FG } else { STR }));
                    out.push((chars[i..i + 2].iter().collect(), PUNCT));
                    i += 2;
                    continue;
                }
                buf.push(chars[i]);
                i += 1;
            }
            out.push((buf, if is_format { FG } else { STR }));
            if i < n {
                out.push(("\"".to_string(), PUNCT));
                i += 1;
            }
            prev_word.clear();
            continue;
        }
        if c == '\'' && i + 2 < n && chars[i + 2] == '\'' {
            out.push(("'".to_string(), PUNCT));
            out.push((chars[i + 1].to_string(), STR));
            out.push(("'".to_string(), PUNCT));
            i += 3;
            continue;
        }
        if c.is_ascii_digit() {
            let s = i;
            while i < n && (chars[i].is_alphanumeric() || chars[i] == '_' || (chars[i] == '.' && i + 1 < n && chars[i + 1].is_ascii_digit())) {
                i += 1;
            }
            out.push((chars[s..i].iter().collect(), PARAM));
            prev_word.clear();
            continue;
        }
        if c.is_alphabetic() || c == '_' {
            let s = i;
            while i < n && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            let mut word: String = chars[s..i].iter().collect();
            if i < n && chars[i] == '!' {
                word.push('!');
                i += 1;
            }
            let next = chars.get(i).copied().unwrap_or('\n');
            let style = if word.ends_with('!') {
                FG
            } else if prev_word == "fn" {
                FUNC
            } else if RUST_KW_PLAIN.contains(&word.as_str()) && word != "use" && word != "in" {
                KW2
            } else if word == "use" {
                KW2
            } else if word == "in" {
                PUNCT
            } else if RUST_KW_ITALIC.contains(&word.as_str()) {
                KW
            } else if matches!(word.as_str(), "true" | "false") {
                PARAM
            } else if matches!(word.as_str(), "Some" | "None" | "Ok" | "Err") {
                TYPE
            } else if next == '(' && !(i >= 2 && chars[i - word.len() - 1..].iter().next() == Some(&':')) && prev_is_dot_or_start(&out) {
                FUNC
            } else {
                FG
            };
            // trailing whitespace handling: keywords absorb following space
            let mut text = word.clone();
            if matches!(style, KW | KW2) && !matches!(word.as_str(), "let" | "if" | "for" | "match" | "while") || (matches!(word.as_str(), "let" | "match") && next == ' ' && peek_word_is_kw(&chars, i)) {
                while i < n && (chars[i] == ' ' || chars[i] == '\t') {
                    text.push(chars[i]);
                    i += 1;
                }
            }
            out.push((text, style));
            prev_word = word;
            continue;
        }
        // punctuation/operators
        let s = i;
        while i < n && !chars[i].is_alphanumeric() && !matches!(chars[i], ' ' | '\t' | '\n' | '\r' | '"' | '\'' | '_') {
            if chars[i] == '/' && i + 1 < n && (chars[i + 1] == '/' || chars[i + 1] == '*') {
                break;
            }
            i += 1;
        }
        if i == s {
            i += 1;
        }
        let p: String = chars[s..i].iter().collect();
        if p == "." {
            out.push((p, FG));
        } else {
            out.push((p, PUNCT));
        }
        prev_word.clear();
    }
    out
}

fn prev_is_dot_or_start(out: &[(String, Style)]) -> bool {
    match out.last() {
        None => true,
        Some((t, _)) => !t.ends_with("::") || true,
    }
}

fn peek_word_is_kw(chars: &[char], mut i: usize) -> bool {
    while i < chars.len() && chars[i] == ' ' {
        i += 1;
    }
    let s = i;
    while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
        i += 1;
    }
    let w: String = chars[s..i].iter().collect();
    RUST_KW_PLAIN.contains(&w.as_str()) || RUST_KW_ITALIC.contains(&w.as_str())
}
