//! Workspace handling (oranda-workspace.json).

use crate::config::{self, OrandaLayer};
use crate::errors::{OrandaError, Result};
use crate::message;
use crate::site::{self, BuildOpts};
use serde_json::json;
use std::path::Path;

pub fn build_or_workspace(root: &Path, opts: &BuildOpts) -> Result<()> {
    let ws = root.join("oranda-workspace.json");
    if ws.is_file() {
        return build_workspace(root, &ws, opts);
    }
    let cfg = site::load_config_display(root, "./oranda.json")?;
    site::build(root, cfg, opts)
}

fn merge_layers(ws: &OrandaLayer, member: OrandaLayer) -> OrandaLayer {
    OrandaLayer {
        project: member.project,
        build: member.build.or_else(|| ws.build.clone()),
        marketing: member.marketing.or_else(|| ws.marketing.clone()),
        styles: member.styles.or_else(|| ws.styles.clone()),
        components: member.components.or_else(|| ws.components.clone()),
        workspace: None,
        schema: None,
    }
}

fn build_workspace(root: &Path, ws_path: &Path, opts: &BuildOpts) -> Result<()> {
    message::info("Workspace detected, gathering info...");
    let contents = std::fs::read_to_string(ws_path).map_err(|e| OrandaError::FileRead {
        path: "./oranda-workspace.json".to_string(),
        source: e,
    })?;
    let layer = config::parse_layer_str(&contents, "./oranda-workspace.json")?;
    let ws = layer.workspace.clone().unwrap_or_default();
    let mut members = ws.members.clone().unwrap_or_default();
    if ws.auto.unwrap_or(false) {
        // auto-detect: subdirectories containing an oranda.json or a project manifest
        if let Ok(rd) = std::fs::read_dir(root) {
            let mut found: Vec<_> = rd
                .flatten()
                .filter(|e| e.path().is_dir())
                .filter(|e| {
                    let p = e.path();
                    p.join("oranda.json").is_file() || p.join("Cargo.toml").is_file() || p.join("package.json").is_file()
                })
                .map(|e| e.file_name().to_string_lossy().to_string())
                .collect();
            found.sort();
            for f in found {
                if !members.iter().any(|m| m.path == f) {
                    members.push(config::WorkspaceMember { slug: f.clone(), path: f });
                }
            }
        }
    }
    let dist_dir = layer
        .build
        .as_ref()
        .and_then(|b| b.dist_dir.clone())
        .unwrap_or_else(|| "public".to_string());
    let dist = root.join(&dist_dir);
    message::info(&format!("Building {} workspace member(s)...", members.len()));

    let mut member_infos = Vec::new();
    for m in &members {
        message::set_prefix(Some(format!("{:>15} ", m.slug)));
        let member_root = root.join(&m.path);
        let cfg_path = member_root.join("oranda.json");
        let member_layer = if cfg_path.is_file() {
            config::parse_layer(&cfg_path)?
        } else {
            OrandaLayer::default()
        };
        let merged = merge_layers(&layer, member_layer);
        let detected = crate::project::detect(&member_root);
        let mut cfg = config::resolve(merged, detected, &member_root);
        cfg.build.dist_dir = dist.join(&m.slug).display().to_string();
        cfg.build.path_prefix = Some(m.slug.clone());
        member_infos.push(json!({
            "name": cfg.project.name,
            "description": cfg.project.description,
            "repository": cfg.project.repository,
            "logo": cfg.styles.logo.as_ref().map(|l| format!("/{}/{}", m.slug, site::file_name_of(l))),
            "href": format!("/{}", m.slug),
            "slug": m.slug,
        }));
        site::build(&member_root, cfg, opts)?;
    }
    message::set_prefix(None);

    if ws.generate_index.unwrap_or(true) {
        message::info("Building workspace index page...");
        let css_override = std::env::var("ORANDA_CSS").ok().filter(|s| !s.is_empty());
        if let Some(css) = &css_override {
            message::warning(&format!("Overriding oranda_css path with {}", css));
        }
        std::fs::create_dir_all(&dist).map_err(|e| OrandaError::other(e.to_string()))?;
        match &css_override {
            Some(css) => {
                let data = std::fs::read(css).map_err(|e| OrandaError::AssetRead {
                    path: css.clone(),
                    source: e,
                })?;
                std::fs::write(dist.join(site::file_name_of(css)), data).map_err(|e| OrandaError::other(e.to_string()))?;
            }
            None => {
                let version = layer
                    .styles
                    .as_ref()
                    .and_then(|s| s.oranda_css_version.clone())
                    .unwrap_or_else(|| site::ORANDA_CSS_VERSION.to_string());
                let proxy = format!("https://octolotl.axodotdev.host/downloads/axodotdev/oranda/{}/oranda.css", version);
                let gh = format!("https://api.github.com/repos/axodotdev/oranda/releases/download/{}/oranda.css", version);
                let chain = crate::net::fetch_with_proxy(&proxy, &gh);
                return Err(OrandaError::CssFetch { causes: chain });
            }
        }
        std::fs::write(dist.join("favicon.ico"), site::FAVICON).map_err(|e| OrandaError::other(e.to_string()))?;
        let theme = layer
            .styles
            .as_ref()
            .and_then(|s| s.theme)
            .unwrap_or(config::Theme::Dark);
        let preferred: Vec<String> = ws.preferred_members.clone().unwrap_or_default();
        let (pref, rest): (Vec<_>, Vec<_>) = member_infos
            .iter()
            .cloned()
            .partition(|m| preferred.iter().any(|p| Some(p.as_str()) == m.get("slug").and_then(|s| s.as_str())));
        let ctx = json!({
            "theme": theme.class(),
            "name": ws.name.clone().unwrap_or_else(|| "My Oranda Workspace".to_string()),
            "prefix": "",
            "additional_css": false,
            "favicon": false,
            "preferred_members": pref,
            "members": rest,
        });
        let html = crate::tmpl::render_escaped(crate::templates::WORKSPACE_INDEX, &ctx);
        std::fs::write(dist.join("index.html"), html).map_err(|e| OrandaError::other(e.to_string()))?;
    }
    message::success(&format!("Your site builds are located in `{}`.", dist_dir));
    Ok(())
}
