/// Scan arguments before clap to reproduce the original help/version behaviour.
fn prescan(args: &[String]) {
    let mut path: Vec<&str> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = args[i].as_str();
        if a == "--" {
            break;
        }
        if a == "-h" || a == "--help" {
            print_help(&path, a == "--help");
            std::process::exit(0);
        }
        if (a == "-V" || a == "--version") && path.is_empty() {
            println!("oranda 0.6.5");
            std::process::exit(0);
        }
        if a == "help" {
            let valid_here = matches!(path.as_slice(), [] | ["generate"]);
            if valid_here {
                let rest: Vec<String> = args[i + 1..].to_vec();
                if path.is_empty() {
                    help_subcommand(&rest);
                } else {
                    // generate help [ci]
                    let mut full = vec!["generate".to_string()];
                    full.extend(rest);
                    help_subcommand(&full);
                }
            }
            return;
        }
        let is_sub = match path.as_slice() {
            [] => matches!(a, "build" | "dev" | "serve" | "generate"),
            ["generate"] => a == "ci",
            _ => false,
        };
        if is_sub {
